INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85999, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我明天要去火车站见了一位朋友。", "corrected_sentence": "我明天要去火车站见一位朋友。", "error_description": "错误形式：「见了一位朋友」；正确形式：「见一位朋友」。句子说的是明天的计划，“了”表示动作已经完成，与“明天”冲突，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
