INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86000, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "动词，看到、遇到；也指会面。", "primary_collocate": null, "pronunciation": "jiàn", "ipa": "tɕjɛn˥˩", "syllable_count": 1, "sentences": [{"text": "下班后我要去见一个朋友。", "target_word": "见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他见我进来，笑了笑。", "target_word": "见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你明天有空见我吗？", "target_word": "见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上个月我在北京见过他。", "target_word": "见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他见雨停了，就出门去了。", "target_word": "见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想见你，请你去办公室。", "target_word": "见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她见小狗饿了，给它拿了点吃的。", "target_word": "见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下次见，我再给你打电话。", "target_word": "见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很久没见奶奶了，想去看看她。", "target_word": "见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家见他不高兴，都不说话了。", "target_word": "见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "见了", "label": "体标"}, {"form": "见过", "label": "体标"}, {"form": "见面", "label": "复合"}, {"form": "看见", "label": "复合"}], "register": "通用", "sense_fingerprint": "见：动词，看到、遇到，也指会面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60f41c19-c9f1-4287-85b2-aea15cba001d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86000, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "见", "is_correct": true, "explanation": "正确：见（jiàn，第四声），意思是看到、遇到或会面。"}, {"text": "间", "is_correct": false, "explanation": "jiān（第一声）与 jiàn（第四声）声调不同，意思是房间。"}, {"text": "减", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）声调不同，意思是减少。"}, {"text": "坚", "is_correct": false, "explanation": "jiān（第一声）与 jiàn（第四声）声调不同，意思是坚固。"}, {"text": "歉", "is_correct": false, "explanation": "qiàn 与 jiàn 声母不同（q 与 j），声调相同，意思是抱歉。"}], "explanations": {"见": "正确：见（jiàn，第四声），意思是看到、遇到或会面。", "间": "jiān（第一声）与 jiàn（第四声）声调不同，意思是房间。", "减": "jiǎn（第三声）与 jiàn（第四声）声调不同，意思是减少。", "坚": "jiān（第一声）与 jiàn（第四声）声调不同，意思是坚固。", "歉": "qiàn 与 jiàn 声母不同（q 与 j），声调相同，意思是抱歉。"}, "sentence_index": null, "correct_answer": "见"}, "level_3": {"options": [{"text": "见", "is_correct": true, "explanation": "正确：“见”表示会面，“下班后我要去见一个朋友”通顺。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示丢弃，“去扔一个朋友”语义荒谬。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象通常是物品或身体，不能说“洗一个朋友”。"}, {"text": "摸", "is_correct": false, "explanation": "搭配：“摸”的对象是物体或身体部位，不用于人际交往，“摸一个朋友”不通。"}], "explanations": {"见": "正确：“见”表示会面，“下班后我要去见一个朋友”通顺。", "扔": "语义：“扔”表示丢弃，“去扔一个朋友”语义荒谬。", "洗": "搭配：“洗”的对象通常是物品或身体，不能说“洗一个朋友”。", "摸": "搭配：“摸”的对象是物体或身体部位，不用于人际交往，“摸一个朋友”不通。"}, "sentence_index": 0, "correct_answer": "见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她昨晚见了一个好梦。", "explanation": "这里应该用〈做〉。做梦要用“做”，“见”表示看到或会面，不能用于做梦。"}, {"text": "我昨天在音乐厅见了一首曲子。", "explanation": "这里应该用〈听〉。听曲子要用“听”，“见”不表示听觉，应说“听了一首曲子”。"}, {"text": "他对我见了一句谢谢。", "explanation": "这里应该用〈说〉。说谢谢要用“说”，“见”不表示说话的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86000, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "见", "is_correct": true, "explanation": "正确：见（jiàn，第四声），意思是看到、遇到或会面。"}, {"text": "尖", "is_correct": false, "explanation": "jiān（第一声）与 jiàn（第四声）声调不同，意思是尖。"}, {"text": "简", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）声调不同，意思是简单。"}, {"text": "降", "is_correct": false, "explanation": "jiàng 与 jiàn 韵母不同（ang 与 an），声调相同，意思是降落。"}, {"text": "欠", "is_correct": false, "explanation": "qiàn 与 jiàn 声母不同（q 与 j），声调相同，意思是欠。"}], "explanations": {"见": "正确：见（jiàn，第四声），意思是看到、遇到或会面。", "尖": "jiān（第一声）与 jiàn（第四声）声调不同，意思是尖。", "简": "jiǎn（第三声）与 jiàn（第四声）声调不同，意思是简单。", "降": "jiàng 与 jiàn 韵母不同（ang 与 an），声调相同，意思是降落。", "欠": "qiàn 与 jiàn 声母不同（q 与 j），声调相同，意思是欠。"}, "sentence_index": null, "correct_answer": "见"}, "level_3": {"options": [{"text": "见", "is_correct": true, "explanation": "正确：“见”表示察觉到，“她见小狗饿了”表示她看出小狗饿了，通顺。"}, {"text": "闻", "is_correct": false, "explanation": "语义：“闻”指用鼻子嗅，不表示察觉到小狗饿了，“她闻小狗饿了”不通。"}, {"text": "瞪", "is_correct": false, "explanation": "语义：“瞪”表示睁大眼睛看人，不能表示察觉到情况，“她瞪小狗饿了”不通。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的对象是衣服鞋袜，不能用来说“穿小狗饿了”。"}], "explanations": {"见": "正确：“见”表示察觉到，“她见小狗饿了”表示她看出小狗饿了，通顺。", "闻": "语义：“闻”指用鼻子嗅，不表示察觉到小狗饿了，“她闻小狗饿了”不通。", "瞪": "语义：“瞪”表示睁大眼睛看人，不能表示察觉到情况，“她瞪小狗饿了”不通。", "穿": "搭配：“穿”的对象是衣服鞋袜，不能用来说“穿小狗饿了”。"}, "sentence_index": 6, "correct_answer": "见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在院子里见到了花香。", "explanation": "这里应该用〈闻〉。花香要用鼻子感受，应说“闻到了花香”；“见”只表示看到，不能用于闻气味。"}, {"text": "她见到了蛋糕的甜味。", "explanation": "这里应该用〈尝〉。甜味要用味觉感受，应说“尝到了甜味”；“见”不能表示品尝的感受。"}, {"text": "她每天早上都见澡。", "explanation": "这里应该用〈洗〉。洗澡要用“洗”，“见”不能表示清洗的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
