INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86001, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "“图”是画出来给人看的东西。", "primary_collocate": null, "pronunciation": "tú", "ipa": "tʰu˧˥", "syllable_count": 1, "sentences": [{"text": "老师在黑板上画了一张图。", "target_word": "图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里有很多图。", "target_word": "图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看图，然后回答问题。", "target_word": "图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子喜欢看有图的书。", "target_word": "图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他画的图很好看。", "target_word": "图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图上有一只小狗和一个小女孩。", "target_word": "图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图是我妹妹画的。", "target_word": "图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我们讲故事，还给我们看图。", "target_word": "图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上的图帮我明白了这个词。", "target_word": "图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能给我画一张图吗？", "target_word": "图", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "幅", "label": "量词"}, {"form": "图画", "label": "复合"}, {"form": "圖", "label": "繁体"}], "register": "中性", "sense_fingerprint": "画出来给人看的画或插图", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a266faf8-e42e-483b-9de3-08d044cde7d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86001, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "图", "is_correct": true, "explanation": "正确。“图”（tú）指画出来给人看的东西。"}, {"text": "土", "is_correct": false, "explanation": "tǔ（第三声）与 tú（第二声）声调不同，意思是土地、泥土。"}, {"text": "兔", "is_correct": false, "explanation": "tù（第四声）与 tú（第二声）声调不同，意思是兔子。"}, {"text": "突", "is_correct": false, "explanation": "tū（第一声）与 tú（第二声）声调不同，意思是突然、突出。"}], "explanations": {"图": "正确。“图”（tú）指画出来给人看的东西。", "土": "tǔ（第三声）与 tú（第二声）声调不同，意思是土地、泥土。", "兔": "tù（第四声）与 tú（第二声）声调不同，意思是兔子。", "突": "tū（第一声）与 tú（第二声）声调不同，意思是突然、突出。"}, "sentence_index": null, "correct_answer": "图"}, "level_3": {"options": [{"text": "图", "is_correct": true, "explanation": "正确。“画了一张图”中的“图”指画出来的形象。"}, {"text": "字", "is_correct": false, "explanation": "搭配：“画”不与“字”搭配，写字才说“写”。"}, {"text": "歌", "is_correct": false, "explanation": "语义：歌是唱出来的，不能用“画”来表示。"}, {"text": "文章", "is_correct": false, "explanation": "搭配：文章是写出来的，不能说“画了一张文章”。"}], "explanations": {"图": "正确。“画了一张图”中的“图”指画出来的形象。", "字": "搭配：“画”不与“字”搭配，写字才说“写”。", "歌": "语义：歌是唱出来的，不能用“画”来表示。", "文章": "搭配：文章是写出来的，不能说“画了一张文章”。"}, "sentence_index": 0, "correct_answer": "图"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张图是用铅笔写的。", "explanation": "这里应该用〈画〉。图是画出来的，不能用“写”。"}, {"text": "他这样做是图钱。", "explanation": "这里的“图”是动词，指贪图、谋求，并不是画出来的东西。"}, {"text": "我在书店买了一只图。", "explanation": "这里应该用〈张〉。“只”用于动物等，画要用“张”或“幅”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86001, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "图", "is_correct": true, "explanation": "正确。“图”（tú）指画出来给人看的东西。"}, {"text": "吐", "is_correct": false, "explanation": "tǔ（第三声）与 tú（第二声）声调不同，意思是吐出。"}, {"text": "秃", "is_correct": false, "explanation": "tū（第一声）与 tú（第二声）声调不同，意思是没有头发。"}, {"text": "兔", "is_correct": false, "explanation": "tù（第四声）与 tú（第二声）声调不同，意思是兔子。"}], "explanations": {"图": "正确。“图”（tú）指画出来给人看的东西。", "吐": "tǔ（第三声）与 tú（第二声）声调不同，意思是吐出。", "秃": "tū（第一声）与 tú（第二声）声调不同，意思是没有头发。", "兔": "tù（第四声）与 tú（第二声）声调不同，意思是兔子。"}, "sentence_index": null, "correct_answer": "图"}, "level_3": {"options": [{"text": "图", "is_correct": true, "explanation": "正确。“这张图是我妹妹画的”中的“图”指画出来的东西。"}, {"text": "歌", "is_correct": false, "explanation": "语义：歌是唱出来的，不能用“画”来表示。"}, {"text": "信", "is_correct": false, "explanation": "搭配：信是写出来的，“画”不与“信”搭配。"}, {"text": "曲子", "is_correct": false, "explanation": "语义：曲子是唱出来或演奏出来的，不能用“画”。"}], "explanations": {"图": "正确。“这张图是我妹妹画的”中的“图”指画出来的东西。", "歌": "语义：歌是唱出来的，不能用“画”来表示。", "信": "搭配：信是写出来的，“画”不与“信”搭配。", "曲子": "语义：曲子是唱出来或演奏出来的，不能用“画”。"}, "sentence_index": 6, "correct_answer": "图"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你能给我念一张图吗？", "explanation": "这里应该说〈看〉。图是用来看的，不能用“念”。"}, {"text": "你图什么呀？", "explanation": "这里的“图”指贪求、图谋，并不是画出来的东西。"}, {"text": "你能给我画一本图吗？", "explanation": "这里应该用〈张〉。“本”用于书籍，图是单张的画。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86001, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师在本子上画了一只图。", "corrected_sentence": "老师在本子上画了一张图。", "error_description": "“图”（画）用量词“张”来计量，“只”用于动物。“一只图”是错误的，应为“一张图”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86001, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这图张是我弟弟画的。", "corrected_sentence": "这张图是我弟弟画的。", "error_description": "量词“张”应放在“图”前面。“图张”的语序是错误的，应为“这张图”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
