INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86002, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用线条或符号画出来、表示位置、数字或道理的图表、地图或示意图。", "primary_collocate": null, "pronunciation": "tú", "ipa": "tʰu˧˥", "syllable_count": 1, "sentences": [{"text": "请看图中的红线，它表示今年的天气。", "target_word": "图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照着图走，你就能找到那家商店。", "target_word": "图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图上有每个城市的名字。", "target_word": "图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图里的数字是去年的价格。", "target_word": "图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用一张图说明水是怎么变成雨的。", "target_word": "图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在纸上画了一张图，告诉我们房子在哪儿。", "target_word": "图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看不懂这张图，请你给我讲讲。", "target_word": "图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图的左边是山，右边是河。", "target_word": "图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看图可以知道每月有多少雨。", "target_word": "图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图下面写着每个数字的意思。", "target_word": "图", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "地图", "label": "复合"}, {"form": "图表", "label": "复合"}, {"form": "圖", "label": "繁体"}], "register": "中性", "sense_fingerprint": "表示位置、数字或道理的图表、地图、示意图", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a266faf8-e42e-483b-9de3-08d044cde7d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86002, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "图", "is_correct": true, "explanation": "正确。“图”（tú）指图表、地图等示意图。"}, {"text": "吐", "is_correct": false, "explanation": "tǔ（第三声）与 tú（第二声）声调不同，意思是吐出。"}, {"text": "秃", "is_correct": false, "explanation": "tū（第一声）与 tú（第二声）声调不同，意思是没有头发。"}, {"text": "兔", "is_correct": false, "explanation": "tù（第四声）与 tú（第二声）声调不同，意思是兔子。"}], "explanations": {"图": "正确。“图”（tú）指图表、地图等示意图。", "吐": "tǔ（第三声）与 tú（第二声）声调不同，意思是吐出。", "秃": "tū（第一声）与 tú（第二声）声调不同，意思是没有头发。", "兔": "tù（第四声）与 tú（第二声）声调不同，意思是兔子。"}, "sentence_index": null, "correct_answer": "图"}, "level_3": {"options": [{"text": "图", "is_correct": true, "explanation": "正确。“图中的红线”指图表上画的线条。"}, {"text": "诗", "is_correct": false, "explanation": "语义：诗是用文字写的，没有可以看的红线。"}, {"text": "歌", "is_correct": false, "explanation": "语义：歌是唱的，不能说“歌中的红线”。"}, {"text": "曲子", "is_correct": false, "explanation": "搭配：“看”不与“曲子”搭配，曲子是用来听的。"}], "explanations": {"图": "正确。“图中的红线”指图表上画的线条。", "诗": "语义：诗是用文字写的，没有可以看的红线。", "歌": "语义：歌是唱的，不能说“歌中的红线”。", "曲子": "搭配：“看”不与“曲子”搭配，曲子是用来听的。"}, "sentence_index": 0, "correct_answer": "图"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在墙上写了一张图。", "explanation": "这里应该用〈画〉。图是画出来的，“写”用于文字，不能这样说。"}, {"text": "他这样做是图钱。", "explanation": "这里的“图”是动词，指贪图、谋求，并不是图表或示意图。"}, {"text": "我在墙上看到一只图。", "explanation": "这里应该用〈张〉。“只”用于动物，图表要用“张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86002, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "图", "is_correct": true, "explanation": "正确。“图”（tú）指图表、地图等示意图。"}, {"text": "土", "is_correct": false, "explanation": "tǔ（第三声）与 tú（第二声）声调不同，意思是土地、泥土。"}, {"text": "兔", "is_correct": false, "explanation": "tù（第四声）与 tú（第二声）声调不同，意思是兔子。"}, {"text": "突", "is_correct": false, "explanation": "tū（第一声）与 tú（第二声）声调不同，意思是突然、突出。"}], "explanations": {"图": "正确。“图”（tú）指图表、地图等示意图。", "土": "tǔ（第三声）与 tú（第二声）声调不同，意思是土地、泥土。", "兔": "tù（第四声）与 tú（第二声）声调不同，意思是兔子。", "突": "tū（第一声）与 tú（第二声）声调不同，意思是突然、突出。"}, "sentence_index": null, "correct_answer": "图"}, "level_3": {"options": [{"text": "图", "is_correct": true, "explanation": "正确。“看不懂这张图”指看不懂图表。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：歌是唱的，不能说“这张歌”，也不能用“看”。"}, {"text": "文章", "is_correct": false, "explanation": "搭配：文章一般说“一篇”，不用“张”来计量。"}, {"text": "小说", "is_correct": false, "explanation": "搭配：小说一般用“本”或“部”计量，不用“张”。"}], "explanations": {"图": "正确。“看不懂这张图”指看不懂图表。", "歌": "搭配：歌是唱的，不能说“这张歌”，也不能用“看”。", "文章": "搭配：文章一般说“一篇”，不用“张”来计量。", "小说": "搭配：小说一般用“本”或“部”计量，不用“张”。"}, "sentence_index": 6, "correct_answer": "图"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一只图下面写着每个数字的意思。", "explanation": "这里应该用〈张〉。“只”用于动物，图表用“张”。"}, {"text": "他借钱给你，是图你的东西。", "explanation": "这里的“图”是动词，指贪图、谋求，并不是图表。"}, {"text": "这封图下面写着每个数字的意思。", "explanation": "这里应该用〈张〉。“封”用于信件，图表要用“张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86002, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "照着这只图走，你就能找到那家商店。", "corrected_sentence": "照着这张图走，你就能找到那家商店。", "error_description": "地图、示意图用量词“张”计量，“只”用于动物。“这只图”是错误的，应为“这张图”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86002, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一直看不懂这张的图，请你给我讲讲。", "corrected_sentence": "我一直看不懂这张图，请你给我讲讲。", "error_description": "错误：“这张”后面不能加“的”直接修饰“图”，应说“这张图”，去掉“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
