INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86003, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“有人”是说有一个人，但不说是谁。", "primary_collocate": null, "pronunciation": "yǒu rén", "ipa": "jou˨˩˦ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "有人在门口等你。", "target_word": "有人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面有人敲门。", "target_word": "有人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚才有人给你打电话了。", "target_word": "有人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人在楼下叫我的名字。", "target_word": "有人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天晚上有人来过我家。", "target_word": "有人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里有人在睡觉。", "target_word": "有人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人把你的书拿走了。", "target_word": "有人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上的花是有人送的。", "target_word": "有人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听见有人在唱歌。", "target_word": "有人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人找你，快去看看吧。", "target_word": "有人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "有一个人，不说是谁", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97e07d7-e53b-4f4d-b1cf-a3cc62b4f69f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86003, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有人", "is_correct": true, "explanation": "正确。“有人”指一个不知道是谁的人，“有人在门口等你”句意通顺。"}, {"text": "自己", "is_correct": false, "explanation": "语义：“自己”指说话涉及的人本身，不能单独作主语表示“有一个不知道是谁的人”。"}, {"text": "你们", "is_correct": false, "explanation": "语义：“你们”指听话的人，与句中“等你”的指向矛盾。"}, {"text": "每个", "is_correct": false, "explanation": "搭配：“每个”后面要接名词，单独作主语，句子不成立。"}], "explanations": {"有人": "正确。“有人”指一个不知道是谁的人，“有人在门口等你”句意通顺。", "自己": "语义：“自己”指说话涉及的人本身，不能单独作主语表示“有一个不知道是谁的人”。", "你们": "语义：“你们”指听话的人，与句中“等你”的指向矛盾。", "每个": "搭配：“每个”后面要接名词，单独作主语，句子不成立。"}, "sentence_index": 0, "correct_answer": "有人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个座位有人了。", "explanation": "这里的“有人”是“座位已被占用”的意思，不是指“有一个不知道是谁的人”。"}, {"text": "我们班有人都没来上课。", "explanation": "这里的“有人”表示存在某人，与“都没”的全体否定相冲突；表示全体否定要用“没有人”。"}, {"text": "有人是我的妈妈，她每天给我做饭。", "explanation": "这里说话人知道是谁，应该直接说“我妈妈”；“有人”只指不知道是谁的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86003, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有人", "is_correct": true, "explanation": "正确。“有人”指一个不知道是谁的人，“有人把你的书拿走了”句意通顺。"}, {"text": "这儿", "is_correct": false, "explanation": "语义：“这儿”表示地点，不能作“把你的书拿走”这一动作的施事。"}, {"text": "每人", "is_correct": false, "explanation": "语义：“每人”指所有人，与“有一个不知道是谁的人”的意思不符。"}, {"text": "哪个", "is_correct": false, "explanation": "语义：“哪个”表示在一定范围内选择，用于疑问，不能用于陈述句。"}], "explanations": {"有人": "正确。“有人”指一个不知道是谁的人，“有人把你的书拿走了”句意通顺。", "这儿": "语义：“这儿”表示地点，不能作“把你的书拿走”这一动作的施事。", "每人": "语义：“每人”指所有人，与“有一个不知道是谁的人”的意思不符。", "哪个": "语义：“哪个”表示在一定范围内选择，用于疑问，不能用于陈述句。"}, "sentence_index": 6, "correct_answer": "有人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "洗手间里有人，请等一下。", "explanation": "这里的“有人”表示洗手间被占用，不是指“有一个不知道是谁的人”。"}, {"text": "他在公司里有人，办事很方便。", "explanation": "这里的“有人”是“有关系、有靠山”的意思，不是指“有一个不知道是谁的人”。"}, {"text": "有人是我的朋友，但我不认识他。", "explanation": "“有人”表示有一个不知道是谁的人，这里又说“是我的朋友”，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86003, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "楼下有人了唱歌。", "corrected_sentence": "楼下有人在唱歌。", "error_description": "“了”用在了应当用“在”的位置：表示动作正在进行要用“在”，“了”表示完成，不能直接放在动词“唱歌”前。正确说法是“楼下有人在唱歌。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86003, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教室里不有人在学习。", "corrected_sentence": "教室里没有人在学习。", "error_description": "“有”的否定要用“没”，不能用“不”。正确说法是“教室里没有人在学习。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
