INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86004, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "代词，指不确定的某个人或某些人。", "primary_collocate": null, "pronunciation": "yǒu rén", "ipa": "joʊ˨˩˦ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "有人喜欢喝茶，有人喜欢喝咖啡。", "target_word": "有人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人说这家店的菜很好吃。", "target_word": "有人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说有人在网上买到了便宜机票。", "target_word": "有人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人觉得学汉语很难，有人觉得很有意思。", "target_word": "有人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人早上跑步，有人晚上跑步。", "target_word": "有人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人问我为什么不吃肉。", "target_word": "有人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人认为多喝水对身体好。", "target_word": "有人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有人跳舞，有人打太极拳。", "target_word": "有人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人告诉我，那家医院很远。", "target_word": "有人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议上有人提出了新办法。", "target_word": "有人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "指不确定的某个人或某些人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97e07d7-e53b-4f4d-b1cf-a3cc62b4f69f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86004, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有人", "is_correct": true, "explanation": "正确。有人指不确定的某个人或某些人。"}, {"text": "游人", "is_correct": false, "explanation": "游人（yóu rén）第一个音节是第二声，与有人（yǒu rén）的第三声声调不同，意思是游览的人。"}, {"text": "诱人", "is_correct": false, "explanation": "诱人（yòu rén）第一个音节是第四声，与有人的第三声声调不同，意思是有吸引力。"}, {"text": "偶人", "is_correct": false, "explanation": "偶人（ǒu rén）比有人（yǒu rén）少了声母 y，声调相同，意思是木偶、玩偶。"}], "explanations": {"有人": "正确。有人指不确定的某个人或某些人。", "游人": "游人（yóu rén）第一个音节是第二声，与有人（yǒu rén）的第三声声调不同，意思是游览的人。", "诱人": "诱人（yòu rén）第一个音节是第四声，与有人的第三声声调不同，意思是有吸引力。", "偶人": "偶人（ǒu rén）比有人（yǒu rén）少了声母 y，声调相同，意思是木偶、玩偶。"}, "sentence_index": null, "correct_answer": "有人"}, "level_3": {"options": [{"text": "有人", "is_correct": true, "explanation": "正确。“有人”指不确定的某个人，与后面的“有人”相对。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问代词，用来提问；这里是陈述句，应指不确定的人，用“有人”。"}, {"text": "哪位", "is_correct": false, "explanation": "语义：“哪位”是疑问代词，用来礼貌地问是谁；这里是陈述句，应指不确定的人，用“有人”。"}, {"text": "什么人", "is_correct": false, "explanation": "语义：“什么人”是疑问短语，问的是人的身份，不能用来陈述不确定的人。"}], "explanations": {"有人": "正确。“有人”指不确定的某个人，与后面的“有人”相对。", "谁": "语义：“谁”是疑问代词，用来提问；这里是陈述句，应指不确定的人，用“有人”。", "哪位": "语义：“哪位”是疑问代词，用来礼貌地问是谁；这里是陈述句，应指不确定的人，用“有人”。", "什么人": "语义：“什么人”是疑问短语，问的是人的身份，不能用来陈述不确定的人。"}, "sentence_index": 0, "correct_answer": "有人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "有人是王老师，他教我们汉语。", "explanation": "这里的“有人”指不知道是谁的人，说话人已经知道是谁时，应直接说出身份，不能用“有人”。"}, {"text": "我们班有人都举手了。", "explanation": "这里应该用〈大家〉。“有人”只指一部分人，不能和表示全体的“都”搭配。"}, {"text": "有人是我的爸爸，他在北京工作。", "explanation": "“有人”指不知道是谁的人；说话人已经知道是自己的爸爸，应直接说“我的爸爸在北京工作”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86004, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有人", "is_correct": true, "explanation": "正确。“有人”指不确定的人，用来陈述“认为多喝水对身体好”的人群。"}, {"text": "哪些人", "is_correct": false, "explanation": "语义：“哪些人”是疑问短语，用来问是哪些人，句中是陈述，不能这样用。"}, {"text": "哪儿", "is_correct": false, "explanation": "语义：“哪儿”是问地点的疑问代词，不能指人，也不能用在这个陈述句里。"}, {"text": "哪个", "is_correct": false, "explanation": "语义：“哪个”是疑问代词，问是哪一个，这里表示的是不确定的人，不能用它陈述。"}], "explanations": {"有人": "正确。“有人”指不确定的人，用来陈述“认为多喝水对身体好”的人群。", "哪些人": "语义：“哪些人”是疑问短语，用来问是哪些人，句中是陈述，不能这样用。", "哪儿": "语义：“哪儿”是问地点的疑问代词，不能指人，也不能用在这个陈述句里。", "哪个": "语义：“哪个”是疑问代词，问是哪一个，这里表示的是不确定的人，不能用它陈述。"}, "sentence_index": 6, "correct_answer": "有人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会议上有人一个人都不同意这个办法，大家都很惊讶。", "explanation": "这里“有人”指部分人存在，与“一个人都不”的全体否定矛盾；应说“会议上没有人同意这个办法”。"}, {"text": "有人是我们的校长，他提出了新办法。", "explanation": "“有人”指不知道是谁的人；已知是校长时应直接说“我们的校长提出了新办法”。"}, {"text": "有人是我的同屋小王，他每天都很早起床。", "explanation": "“有人”指不确定的人；已经说出是“同屋小王”，就不能再用“有人”，应直接说“我的同屋小王每天都很早起床”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86004, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门外不有人在敲门。", "corrected_sentence": "门外有人在敲门。", "error_description": "“不”不能直接放在“有”前面；此句是肯定陈述，不需要否定，应说“门外有人在敲门”。否定“有人”的存在要用“没有”，如“门外没有人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86004, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教室里不有人。", "corrected_sentence": "教室里没有人。", "error_description": "否定“有人”的存在要用“没有”，应说“没有人”；“不”不能否定动词“有”，所以“教室里不有人”不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
