INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86005, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "“当时”是说事情发生的那个时候。", "primary_collocate": null, "pronunciation": "dāng shí", "ipa": "tɑŋ˥ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "当时我还不会说汉语。", "target_word": "当时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当时天已经黑了。", "target_word": "当时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当时他不在家。", "target_word": "当时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我记得当时下着大雨。", "target_word": "当时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当时你为什么不告诉我？", "target_word": "当时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当时大家都很高兴。", "target_word": "当时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情发生的当时，我正在上班。", "target_word": "当时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当时没有听清楚老师的话。", "target_word": "当时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当时我们住在一个小城市。", "target_word": "当时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我当时很紧张，什么也说不出来。", "target_word": "当时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事情发生的那个时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97e07d7-e53b-4f4d-b1cf-a3cc62b4f69f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86005, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "当时", "is_correct": true, "explanation": "正确。“当时”指事情发生的那个时候。"}, {"text": "党史", "is_correct": false, "explanation": "党史（dǎng shǐ）两个音节的声调都与当时（dāng shí）不同，意思是党的历史。"}, {"text": "当值", "is_correct": false, "explanation": "当值（dāng zhí）第二个音节的声母是 zh，与当时（dāng shí）的 sh 不同，意思是值班。"}, {"text": "当事", "is_correct": false, "explanation": "当事（dāng shì）第二个音节是第四声，与当时的第二声声调不同，意思是有关的当事人。"}], "explanations": {"当时": "正确。“当时”指事情发生的那个时候。", "党史": "党史（dǎng shǐ）两个音节的声调都与当时（dāng shí）不同，意思是党的历史。", "当值": "当值（dāng zhí）第二个音节的声母是 zh，与当时（dāng shí）的 sh 不同，意思是值班。", "当事": "当事（dāng shì）第二个音节是第四声，与当时的第二声声调不同，意思是有关的当事人。"}, "sentence_index": null, "correct_answer": "当时"}, "level_3": {"options": [{"text": "当时", "is_correct": true, "explanation": "正确。“当时”指事情发生的那个时候，与“还不会说汉语”所说的过去情况相配。"}, {"text": "将来", "is_correct": false, "explanation": "语义：“将来”指以后的时间，与句中说的过去情况时间不合。"}, {"text": "未来", "is_correct": false, "explanation": "语义：“未来”指今后的时间，与句中指过去的情况不合。"}, {"text": "此后", "is_correct": false, "explanation": "语义：“此后”指某事之后的时间，与句中所说那个时候的情况不合。"}], "explanations": {"当时": "正确。“当时”指事情发生的那个时候，与“还不会说汉语”所说的过去情况相配。", "将来": "语义：“将来”指以后的时间，与句中说的过去情况时间不合。", "未来": "语义：“未来”指今后的时间，与句中指过去的情况不合。", "此后": "语义：“此后”指某事之后的时间，与句中所说那个时候的情况不合。"}, "sentence_index": 0, "correct_answer": "当时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "当时请大家准时到场。", "explanation": "这里应该用〈届时〉。“当时”指事情发生的那个时候，不能用于还没到来的时间。"}, {"text": "我们约好当时见面。", "explanation": "这里应该用〈届时〉。“当时”指已经发生的那个时候，不能用于约定将来的见面。"}, {"text": "将来的当时，你会很忙。", "explanation": "这里应该用〈将来〉的时间说法。“当时”只指已经发生或正在发生的时候，不能用来指将来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86005, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当时", "is_correct": true, "explanation": "正确。“当时”指事情发生的那个时候，与“事情发生的”搭配。"}, {"text": "随后", "is_correct": false, "explanation": "语法：“随后”是副词，不能受“事情发生的”修饰，也不指事情发生的那个时候。"}, {"text": "眼下", "is_correct": false, "explanation": "语义：“眼下”指现在，不能指过去事情发生的时候。"}, {"text": "目前", "is_correct": false, "explanation": "搭配：“目前”多作状语，不说“事情发生的目前”，不能用来修饰“事情发生的”这样的定语。"}], "explanations": {"当时": "正确。“当时”指事情发生的那个时候，与“事情发生的”搭配。", "随后": "语法：“随后”是副词，不能受“事情发生的”修饰，也不指事情发生的那个时候。", "眼下": "语义：“眼下”指现在，不能指过去事情发生的时候。", "目前": "搭配：“目前”多作状语，不说“事情发生的目前”，不能用来修饰“事情发生的”这样的定语。"}, "sentence_index": 6, "correct_answer": "当时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我现在当时在北京工作。", "explanation": "这里的“当时”指过去的那个时刻，不能和表示现在的“现在”同时用来指同一时间。"}, {"text": "他每次当时都迟到。", "explanation": "“当时”指过去某一个时候，不能和“每次”一起说多次重复的事，应说“他每次都迟到”。"}, {"text": "以后当时我会告诉你真相。", "explanation": "“当时”只指过去那个时候，不能用于将来，应去掉“当时”，说“以后我会告诉你真相”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86005, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我当时的很害怕。", "corrected_sentence": "我当时很害怕。", "error_description": "“的”后面需要名词作中心语，“当时的很害怕”不成立，应去掉“的”，说“我当时很害怕”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86005, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的当时没有时间吃饭。", "corrected_sentence": "我当时没有时间吃饭。", "error_description": "“我”和“当时”之间不能加“的”，应说“我当时没有时间吃饭”；“我的当时”不成词，句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
