INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86006, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "名词，指过去事情发生的那段时间。", "primary_collocate": null, "pronunciation": "dāng shí", "ipa": "tɑŋ˥ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "当时的生活很简单。", "target_word": "当时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当时的我刚上小学，还不太懂事。", "target_word": "当时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当时的火车比现在慢得多。", "target_word": "当时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷常说起当时的故事。", "target_word": "当时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当时的老师对我们很严格。", "target_word": "当时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学毕业后，当时的同学都去了不同的城市。", "target_word": "当时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当时的电视很小，只有黑白的。", "target_word": "当时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当时的我不懂这些道理。", "target_word": "当时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片里是当时的老房子。", "target_word": "当时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当时的工资不高，但生活很平静。", "target_word": "当时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "过去事情发生的那段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97e07d7-e53b-4f4d-b1cf-a3cc62b4f69f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86006, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "当时", "is_correct": true, "explanation": "正确。“当时”指过去事情发生的那段时间。"}, {"text": "党史", "is_correct": false, "explanation": "党史（dǎng shǐ）两个音节的声调都与当时（dāng shí）不同，意思是党的历史。"}, {"text": "当事", "is_correct": false, "explanation": "当事（dāng shì）第二个音节是第四声，与当时的第二声声调不同，意思是有关的当事人。"}, {"text": "当值", "is_correct": false, "explanation": "当值（dāng zhí）第二个音节的声母是 zh，与当时（dāng shí）的 sh 不同，意思是值班。"}], "explanations": {"当时": "正确。“当时”指过去事情发生的那段时间。", "党史": "党史（dǎng shǐ）两个音节的声调都与当时（dāng shí）不同，意思是党的历史。", "当事": "当事（dāng shì）第二个音节是第四声，与当时的第二声声调不同，意思是有关的当事人。", "当值": "当值（dāng zhí）第二个音节的声母是 zh，与当时（dāng shí）的 sh 不同，意思是值班。"}, "sentence_index": null, "correct_answer": "当时"}, "level_3": {"options": [{"text": "当时", "is_correct": true, "explanation": "正确。“当时”指过去的那段时间，与“的生活”相配。"}, {"text": "下面", "is_correct": false, "explanation": "语义：“下面”是方位词，指位置，不指一段时间，说“下面的生活”时间意义不通。"}, {"text": "已经", "is_correct": false, "explanation": "语法：“已经”是副词，不能加“的”修饰名词“生活”。"}, {"text": "对面", "is_correct": false, "explanation": "搭配：“对面”多修饰地点，不说“对面的生活”。"}], "explanations": {"当时": "正确。“当时”指过去的那段时间，与“的生活”相配。", "下面": "语义：“下面”是方位词，指位置，不指一段时间，说“下面的生活”时间意义不通。", "已经": "语法：“已经”是副词，不能加“的”修饰名词“生活”。", "对面": "搭配：“对面”多修饰地点，不说“对面的生活”。"}, "sentence_index": 0, "correct_answer": "当时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们计划当时去国外读书。", "explanation": "这里应该用〈日后〉。“当时”指过去的那段时间，不能用来说将来的计划。"}, {"text": "明天的当时，我们都在学习。", "explanation": "这里应该用〈明天〉的时间说法。“当时”指过去的那段时间，不能用来指明天。"}, {"text": "明年的当时，我们会搬到上海。", "explanation": "这里的“当时”指过去的那段时间，不能用来指明年，所以不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86006, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当时", "is_correct": true, "explanation": "正确。“当时”指过去的那段时间，修饰“电视”。"}, {"text": "马上", "is_correct": false, "explanation": "语法：“马上”是副词，不能加“的”修饰名词“电视”。"}, {"text": "背后", "is_correct": false, "explanation": "搭配：“背后”多用于“背后的原因”之类，不用来修饰物体，不说“背后的电视”。"}, {"text": "已经", "is_correct": false, "explanation": "语法：“已经”是副词，不能加“的”修饰名词“电视”。"}], "explanations": {"当时": "正确。“当时”指过去的那段时间，修饰“电视”。", "马上": "语法：“马上”是副词，不能加“的”修饰名词“电视”。", "背后": "搭配：“背后”多用于“背后的原因”之类，不用来修饰物体，不说“背后的电视”。", "已经": "语法：“已经”是副词，不能加“的”修饰名词“电视”。"}, "sentence_index": 6, "correct_answer": "当时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天的当时都去跑步。", "explanation": "这里的“当时”指过去的某段时间，不能用来说经常发生的事，应该说“每天”。"}, {"text": "我现在的当时很忙。", "explanation": "这里的“当时”指过去，不能和表示现在的“现在”一起修饰同一段时间。"}, {"text": "以后的当时，我们会很开心。", "explanation": "“当时”指过去的那段时间，不能用于将来，应说“以后我们会很开心”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86006, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在当时的工作很忙。", "corrected_sentence": "当时的工作很忙。", "error_description": "“当时”作句子主语前不需要介词“在”，应说“当时的工作很忙”；加了“在”以后句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86006, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张照片拍的是当时小镇。", "corrected_sentence": "这张照片拍的是当时的小镇。", "error_description": "“当时”修饰名词“小镇”时要加“的”，应说“当时的小镇”；少了“的”，句子不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86007, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "石头", "is_correct": false, "explanation": "无关：“石头”指岩石的小块，与“过去”没有反义关系。"}, {"text": "海洋", "is_correct": false, "explanation": "无关：“海洋”指大片海水，与“过去”没有反义关系。"}, {"text": "现在", "is_correct": true, "explanation": "正确。“现在”与“过去”相对，指当下的时间。"}, {"text": "窗户", "is_correct": false, "explanation": "无关：“窗户”指墙上透光通气的开口，与“过去”没有反义关系。"}], "correct_answer": "现在", "explanations": {"石头": "无关：“石头”指岩石的小块，与“过去”没有反义关系。", "海洋": "无关：“海洋”指大片海水，与“过去”没有反义关系。", "现在": "正确。“现在”与“过去”相对，指当下的时间。", "窗户": "无关：“窗户”指墙上透光通气的开口，与“过去”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86007, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "地毯", "is_correct": false, "explanation": "无关：“地毯”指铺在地面上的织物，与“过去”没有反义关系。"}, {"text": "雨水", "is_correct": false, "explanation": "无关：“雨水”指从天上落下的水，与“过去”没有反义关系。"}, {"text": "现在", "is_correct": true, "explanation": "正确。“现在”与“过去”相对，指当下的时间。"}, {"text": "钢琴", "is_correct": false, "explanation": "无关：“钢琴”是一种乐器，与“过去”没有反义关系。"}], "correct_answer": "现在", "explanations": {"地毯": "无关：“地毯”指铺在地面上的织物，与“过去”没有反义关系。", "雨水": "无关：“雨水”指从天上落下的水，与“过去”没有反义关系。", "现在": "正确。“现在”与“过去”相对，指当下的时间。", "钢琴": "无关：“钢琴”是一种乐器，与“过去”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86007, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "“过去”是已经走过的时间，是今天以前的日子。", "primary_collocate": null, "pronunciation": "guò qù", "ipa": "kwo⁵¹ tɕʰy⁵¹", "syllable_count": 2, "sentences": [{"text": "过去的日子很苦，现在好多了。", "target_word": "过去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想起了过去和朋友玩的日子。", "target_word": "过去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去一周，我每天都睡得很晚。", "target_word": "过去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是回忆过去的快乐时光。", "target_word": "过去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去的三天一直下雨。", "target_word": "过去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去两天我一直在家复习。", "target_word": "过去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去的几个月，她一直在学中文。", "target_word": "过去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去人们写信，现在人们发微信。", "target_word": "过去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里写着这个城市过去的故事。", "target_word": "过去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也不能改变过去，只能看将来。", "target_word": "过去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "過去", "label": "繁体"}], "register": "中性", "sense_fingerprint": "已经走过的日子，今天以前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1dfd233-60e1-4be7-a6ef-22ae12c1f292') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86007, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "现在", "is_correct": false, "explanation": "语义：“现在的日子很苦，现在好多了”前后自相矛盾。"}, {"text": "过去", "is_correct": true, "explanation": "正确。“过去”指已经走过的日子，与后句“现在好多了”形成对比。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“花园的日子”不成立，“日子”不能由“花园”修饰。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“房子的日子”不成立，与“日子很苦”的表述不合。"}], "explanations": {"现在": "语义：“现在的日子很苦，现在好多了”前后自相矛盾。", "过去": "正确。“过去”指已经走过的日子，与后句“现在好多了”形成对比。", "花园": "搭配：“花园的日子”不成立，“日子”不能由“花园”修饰。", "房子": "搭配：“房子的日子”不成立，与“日子很苦”的表述不合。"}, "sentence_index": 0, "correct_answer": "过去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他正在记录这次活动的过去。", "explanation": "这里应该用〈过程〉。“过去”指已经走过的时间，不能用来指活动正在进行的阶段。"}, {"text": "请耐心等待项目的过去。", "explanation": "这里应该用〈过程〉。“过去”指已经走过的时间，不能用来指项目推进的阶段。"}, {"text": "这次手术的过去需要两小时。", "explanation": "这里应该用〈过程〉。“过去”指已经走过的时间，不能用来指手术进行的过程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86007, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "搭配：“桌子的几个月”不成立，“几个月”不能由“桌子”修饰。"}, {"text": "下午", "is_correct": false, "explanation": "语义：“下午的几个月”时间范围不合，与“几个月”的说法矛盾。"}, {"text": "过去", "is_correct": true, "explanation": "正确。“过去的几个月”指已经走过的几个月，与句意一致。"}, {"text": "电影", "is_correct": false, "explanation": "搭配：电影不能用“几个月”来计量或修饰，与句意不合。"}], "explanations": {"桌子": "搭配：“桌子的几个月”不成立，“几个月”不能由“桌子”修饰。", "下午": "语义：“下午的几个月”时间范围不合，与“几个月”的说法矛盾。", "过去": "正确。“过去的几个月”指已经走过的几个月，与句意一致。", "电影": "搭配：电影不能用“几个月”来计量或修饰，与句意不合。"}, "sentence_index": 6, "correct_answer": "过去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "过去我们明年再去旅行吧。", "explanation": "这里应该用〈以后〉。“过去”指已经走过的时间，不能与“明年”这样的将来时间搭配来提出邀约。"}, {"text": "过去我们下周开会吧。", "explanation": "这里应该用〈下周〉。“过去”指已经走过的时间，不能与“下周”这样的将来时间搭配。"}, {"text": "过去请大家注意安全。", "explanation": "这里应该用〈今后〉。“过去”指已经走过的时间，不能用来对将来提出要求。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86007, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老人总是怀念过去老朋友。", "corrected_sentence": "老人总是怀念过去的老朋友。", "error_description": "错误：漏了“的”。“过去”修饰名词“老朋友”时要加“的”，应说“过去的老朋友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86007, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "过去地几年，他一直很努力。", "corrected_sentence": "过去的几年，他一直很努力。", "error_description": "错误：“地”用错。“过去”修饰名词“几年”时要用“的”，“地”用于修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86008, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "桌子", "is_correct": false, "explanation": "无关：“桌子”是家具名称，与“过去”没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "无关：“河流”指水的流动体，与“过去”没有反义关系。"}, {"text": "现在", "is_correct": true, "explanation": "正确。“现在”与“过去”相对，指当下的时间。"}, {"text": "电影", "is_correct": false, "explanation": "无关：“电影”指影视作品，与“过去”没有反义关系。"}], "correct_answer": "现在", "explanations": {"桌子": "无关：“桌子”是家具名称，与“过去”没有反义关系。", "河流": "无关：“河流”指水的流动体，与“过去”没有反义关系。", "现在": "正确。“现在”与“过去”相对，指当下的时间。", "电影": "无关：“电影”指影视作品，与“过去”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86008, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "空气", "is_correct": false, "explanation": "无关：“空气”指包围地球的气体，与“过去”没有反义关系。"}, {"text": "眼睛", "is_correct": false, "explanation": "无关：“眼睛”是人的视觉器官，与“过去”没有反义关系。"}, {"text": "现在", "is_correct": true, "explanation": "正确。“现在”与“过去”相对，指当下的时间。"}, {"text": "房间", "is_correct": false, "explanation": "无关：“房间”指建筑中的隔间，与“过去”没有反义关系。"}], "correct_answer": "现在", "explanations": {"空气": "无关：“空气”指包围地球的气体，与“过去”没有反义关系。", "眼睛": "无关：“眼睛”是人的视觉器官，与“过去”没有反义关系。", "现在": "正确。“现在”与“过去”相对，指当下的时间。", "房间": "无关：“房间”指建筑中的隔间，与“过去”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86008, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "名词，指现在以前的时间。", "primary_collocate": null, "pronunciation": "guò qù", "ipa": "kwo⁵¹ tɕʰy⁵¹", "syllable_count": 2, "sentences": [{"text": "过去这里是一片农田，现在是学校。", "target_word": "过去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很少说起自己的过去。", "target_word": "过去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能一直想着过去。", "target_word": "过去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去我每天骑自行车上班，现在开车。", "target_word": "过去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她已经忘了过去的不愉快。", "target_word": "过去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的过去没有人知道。", "target_word": "过去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她常常给孩子讲她的过去。", "target_word": "过去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去我不会游泳，现在游得很好。", "target_word": "过去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人喜欢回忆过去的生活。", "target_word": "过去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别总是提过去的错误了。", "target_word": "过去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "過去", "label": "繁体"}], "register": "中性", "sense_fingerprint": "现在以前的时间，与现在相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1dfd233-60e1-4be7-a6ef-22ae12c1f292') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86008, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "现在", "is_correct": false, "explanation": "语义：后句已有“现在是学校”，“现在这里是一片农田”与之冲突。"}, {"text": "过去", "is_correct": true, "explanation": "正确。“过去”指以前的时间，与后句“现在是学校”形成对比。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指未来，与“现在是学校”的时间对比矛盾。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”不是时间词，“书包这里是一片农田”不成立。"}], "explanations": {"现在": "语义：后句已有“现在是学校”，“现在这里是一片农田”与之冲突。", "过去": "正确。“过去”指以前的时间，与后句“现在是学校”形成对比。", "明天": "语义：“明天”指未来，与“现在是学校”的时间对比矛盾。", "书包": "语义：“书包”不是时间词，“书包这里是一片农田”不成立。"}, "sentence_index": 0, "correct_answer": "过去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们正在完成这个漫长的过去。", "explanation": "这里应该用〈过程〉。“过去”指已经过去的时间，不能用来指事情正在进行的阶段。"}, {"text": "实验的过去需要三个小时。", "explanation": "这里应该用〈过程〉。“过去”指已经过去的时间，不能用来指实验进行的过程。"}, {"text": "这项工作的过去还没有结束。", "explanation": "这里应该用〈过程〉。“过去”指已经过去的时间，不能用来指工作进行中的阶段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86008, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伞", "is_correct": false, "explanation": "语义：“讲她的伞”不成立，伞与讲述经历无关。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是可以用来讲述的内容，与句意不合。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“讲”的对象是故事或经历，不说“讲她的体温”。"}, {"text": "过去", "is_correct": true, "explanation": "正确。“讲她的过去”指讲述她以前的经历，与句意一致。"}], "explanations": {"伞": "语义：“讲她的伞”不成立，伞与讲述经历无关。", "冰箱": "语义：冰箱不是可以用来讲述的内容，与句意不合。", "体温": "搭配：“讲”的对象是故事或经历，不说“讲她的体温”。", "过去": "正确。“讲她的过去”指讲述她以前的经历，与句意一致。"}, "sentence_index": 6, "correct_answer": "过去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "过去你明天来找我吧。", "explanation": "这里应该用〈明天〉。“过去”指已经走过的时间，不能与“明天”这样的将来时间搭配。"}, {"text": "过去我们再见面吧。", "explanation": "这里应该用〈以后〉。“过去”指已经过去的时间，不能用来表示以后的约定。"}, {"text": "过去请你给我回个电话。", "explanation": "这里应该用〈稍后〉。“过去”指已经走过的时间，不能用来对将来的行动提出要求。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86008, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "过去地岁月让她变得坚强。", "corrected_sentence": "过去的岁月让她变得坚强。", "error_description": "错误：“地”用错。“过去”修饰名词“岁月”时要用“的”，“地”用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86008, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是我过去地照片。", "corrected_sentence": "这是我过去的照片。", "error_description": "错误：“地”用错。“过去”修饰名词“照片”时要用“的”，“地”用于修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
