INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86009, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“那些”是指离我们远一点的好几个人或东西。", "primary_collocate": null, "pronunciation": "nà xiē", "ipa": "na˥˩ ɕje˥˥", "syllable_count": 2, "sentences": [{"text": "那边那些书是我哥哥的。", "target_word": "那些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，那边那些孩子在玩什么？", "target_word": "那些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "角落里那些苹果是谁买的？", "target_word": "那些", "complexity_tier": "T3", "furigana": "nà xiē", "sentence_source": "generated"}, {"text": "那边那些人是我的同学。", "target_word": "那些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢那边那些衣服，太贵了。", "target_word": "那些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远处那些花开得真漂亮。", "target_word": "那些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那边教室里那些学生正在看书。", "target_word": "那些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把那边那些杯子拿过来。", "target_word": "那些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远处树上那些小鸟在唱歌。", "target_word": "那些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上那些照片是去年拍的。", "target_word": "那些", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "那些：指示较远的好几个人或东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T1: 3 words above tier T1 (max 2): 远处 (Zipf 3.84), 树上 (Zipf 3.82), 小鸟 (Zipf 3.85)']::text[], '60f41c19-c9f1-4287-85b2-aea15cba001d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86009, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "那些", "is_correct": true, "explanation": "正确。“那些”读作 nà xiē，指离说话人较远的几个。"}, {"text": "哪些", "is_correct": false, "explanation": "nǎ xiē（第三声）与 nà xiē（第四声）声调不同，意思是“哪几个”（疑问）。"}, {"text": "拿些", "is_correct": false, "explanation": "ná（第二声）与 nà（第四声）声调不同，意思是“拿一些”。"}, {"text": "辣些", "is_correct": false, "explanation": "là 与 nà 声母不同（l 与 n），意思是“辣一点”。"}], "explanations": {"那些": "正确。“那些”读作 nà xiē，指离说话人较远的几个。", "哪些": "nǎ xiē（第三声）与 nà xiē（第四声）声调不同，意思是“哪几个”（疑问）。", "拿些": "ná（第二声）与 nà（第四声）声调不同，意思是“拿一些”。", "辣些": "là 与 nà 声母不同（l 与 n），意思是“辣一点”。"}, "sentence_index": null, "correct_answer": "那些"}, "level_3": {"options": [{"text": "这种", "is_correct": false, "explanation": "搭配：“那边”指远处，“这种”指近处的一类，二者不能同用。"}, {"text": "那些", "is_correct": true, "explanation": "正确。“那些”指离说话人较远的几样，与“那边”一致。"}, {"text": "哪种", "is_correct": false, "explanation": "语义：“哪种”是疑问词，陈述句里不能用，这句是陈述句。"}, {"text": "这些", "is_correct": false, "explanation": "语义：“这些”指近处的几样，与“那边”矛盾。"}], "explanations": {"这种": "搭配：“那边”指远处，“这种”指近处的一类，二者不能同用。", "那些": "正确。“那些”指离说话人较远的几样，与“那边”一致。", "哪种": "语义：“哪种”是疑问词，陈述句里不能用，这句是陈述句。", "这些": "语义：“这些”指近处的几样，与“那边”矛盾。"}, "sentence_index": 0, "correct_answer": "那些"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那些书是我借的一本。", "explanation": "这里应该用〈那本〉。“那些”指多本，“一本”只指一本书，数量不一致。"}, {"text": "那些人是我的一个同学。", "explanation": "这里应该用〈那个〉。“那些”指多个人，“一个同学”只指一个人，数量不一致。"}, {"text": "那些杯子是我刚买的一个。", "explanation": "这里应该用〈那个〉。“那些”指多个，“一个”只指一个杯子，数量不一致。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86009, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "这个", "is_correct": false, "explanation": "搭配：“这个”指近处的一个，与“那边”方位冲突，也和复数的“学生”不搭配。"}, {"text": "那些", "is_correct": true, "explanation": "正确。“那些”指较远的几个，与“那边”一致，可修饰复数的“学生”。"}, {"text": "哪个", "is_correct": false, "explanation": "语义：“哪个”是疑问词，用在陈述句里不成立。"}, {"text": "这位", "is_correct": false, "explanation": "语义：“这位”指近处的一位（敬称），与“那边”和复数的“学生”都矛盾。"}], "explanations": {"这个": "搭配：“这个”指近处的一个，与“那边”方位冲突，也和复数的“学生”不搭配。", "那些": "正确。“那些”指较远的几个，与“那边”一致，可修饰复数的“学生”。", "哪个": "语义：“哪个”是疑问词，用在陈述句里不成立。", "这位": "语义：“这位”指近处的一位（敬称），与“那边”和复数的“学生”都矛盾。"}, "sentence_index": 6, "correct_answer": "那些"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那些画是我最喜欢的一幅。", "explanation": "这里应该用〈那幅〉。“那些”指多个，“一幅”只指一幅画，数量不一致。"}, {"text": "那些电影是我看过的一部。", "explanation": "这里应该用〈那部〉。“那些”指多个，“一部”只指一部电影，数量不一致。"}, {"text": "那些笔是我买的一支。", "explanation": "这里应该用〈那支〉。“那些”指多个，“一支”只指一支笔，数量不一致。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86009, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "远处那些的苹果很甜。", "corrected_sentence": "远处那些苹果很甜。", "error_description": "错误形式：「那些的苹果」；正确形式：「那些苹果」。“那些”直接修饰名词，后面不能加结构助词“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
