INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86010, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指示代词，指较远的多个人或事物。", "primary_collocate": null, "pronunciation": "nà xiē", "ipa": "na˥˩ ɕje˥˥", "syllable_count": 2, "sentences": [{"text": "远处那些是什么动物？", "target_word": "那些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天买的那些水果呢？", "target_word": "那些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站在门口的那些人是谁？", "target_word": "那些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对面那些房子都很新。", "target_word": "那些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不认识远处的那些人。", "target_word": "那些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园那边那些年轻人在打球。", "target_word": "那些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把那边那些椅子搬过来。", "target_word": "那些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上那些树都很高。", "target_word": "那些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那边墙角那些花都开了。", "target_word": "那些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那边柜子里那些衣服都是我的。", "target_word": "那些", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "那些：指示代词，指较远的多个人或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60f41c19-c9f1-4287-85b2-aea15cba001d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generatio