INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86010, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "那些", "is_correct": true, "explanation": "正确。“那些”读作 nà xiē，指离说话人较远的几个。"}, {"text": "哪些", "is_correct": false, "explanation": "nǎ xiē（第三声）与 nà xiē（第四声）声调不同，意思是“哪几个”（疑问）。"}, {"text": "拿些", "is_correct": false, "explanation": "ná（第二声）与 nà（第四声）声调不同，意思是“拿一些”。"}, {"text": "辣些", "is_correct": false, "explanation": "là 与 nà 声母不同（l 与 n），意思是“辣一点”。"}], "explanations": {"那些": "正确。“那些”读作 nà xiē，指离说话人较远的几个。", "哪些": "nǎ xiē（第三声）与 nà xiē（第四声）声调不同，意思是“哪几个”（疑问）。", "拿些": "ná（第二声）与 nà（第四声）声调不同，意思是“拿一些”。", "辣些": "là 与 nà 声母不同（l 与 n），意思是“辣一点”。"}, "sentence_index": null, "correct_answer": "那些"}, "level_3": {"options": [{"text": "这些", "is_correct": false, "explanation": "语义：“这些”指近处的几个，与“远处”矛盾。"}, {"text": "那些", "is_correct": true, "explanation": "正确。“那些”指远处的几个，与“远处”一致。"}, {"text": "这种", "is_correct": false, "explanation": "搭配：“远处”是远指，“这种”是近指的一类，二者不能同用。"}, {"text": "这个", "is_correct": false, "explanation": "语义：“这个”指近处的一个，与“远处”矛盾，也和复数的问句不合。"}], "explanations": {"这些": "语义：“这些”指近处的几个，与“远处”矛盾。", "那些": "正确。“那些”指远处的几个，与“远处”一致。", "这种": "搭配：“远处”是远指，“这种”是近指的一类，二者不能同用。", "这个": "语义：“这个”指近处的一个，与“远处”矛盾，也和复数的问句不合。"}, "sentence_index": 0, "correct_answer": "那些"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那些箱子是我的一个。", "explanation": "这里应该用〈那个〉。“那些”指多个，“一个”只指一个箱子，数量不一致。"}, {"text": "那些车是我爸爸的一辆。", "explanation": "这里应该用〈那辆〉。“那些”指多辆，“一辆”只指一辆车，数量不一致。"}, {"text": "那些房间是我的一间。", "explanation": "这里应该用〈那间〉。“那些”指多间，“一间”只指一间房，数量不一致。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validatio