INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86010, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "这把", "is_correct": false, "explanation": "搭配：“那边”是远指，“这把”指近处的一把，二者不能同用。"}, {"text": "那些", "is_correct": true, "explanation": "正确。“那些”指较远的几把，与“那边”一致，可修饰复数的“椅子”。"}, {"text": "这张", "is_correct": false, "explanation": "搭配：“这张”是近指，与“那边”的远指方位不搭配。"}, {"text": "哪把", "is_correct": false, "explanation": "语义：“哪把”是疑问词，用在请求句里不成立，这句是请对方搬椅子。"}], "explanations": {"这把": "搭配：“那边”是远指，“这把”指近处的一把，二者不能同用。", "那些": "正确。“那些”指较远的几把，与“那边”一致，可修饰复数的“椅子”。", "这张": "搭配：“这张”是近指，与“那边”的远指方位不搭配。", "哪把": "语义：“哪把”是疑问词，用在请求句里不成立，这句是请对方搬椅子。"}, "sentence_index": 6, "correct_answer": "那些"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那些衣服是我的一件。", "explanation": "这里应该用〈那件〉。“那些”指多件，“一件”只指一件衣服，数量不一致。"}, {"text": "那些裤子是我的一条。", "explanation": "这里应该用〈那条〉。“那些”指多条，“一条”只指一条裤子，数量不一致。"}, {"text": "那些帽子是我的一顶。", "explanation": "这里应该用〈那顶〉。“那些”指多顶，“一顶”只指一顶帽子，数量不一致。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86010, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "远处那些的房子都很新。", "corrected_sentence": "远处那些房子都很新。", "error_description": "错误：“那些”后面多加了“的”。正确：“那些”是指示词，后面直接接名词，应说“远处那些房子都很新”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86010, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那些一把椅子很舒服。", "corrected_sentence": "那些椅子很舒服。", "error_description": "错误：“那些”后面多加了数量短语“一把”。正确：“那些”后直接接名词，应说“那些椅子很舒服”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
