INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86011, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "“道”是人和车走的路。", "primary_collocate": null, "pronunciation": "dào", "ipa": "tɑʊ˥˩", "syllable_count": 1, "sentences": [{"text": "这条道很窄，开车要小心。", "target_word": "道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天走这条道去学校。", "target_word": "道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后，这条道很难走。", "target_word": "道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条道白天行人很多。", "target_word": "道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面的道被雪盖住了。", "target_word": "道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你走哪条道回家？", "target_word": "道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条道直走就到车站。", "target_word": "道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条道晚上没有灯。", "target_word": "道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走错道了，没找到饭店。", "target_word": "道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条道的两边都是树。", "target_word": "道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条道", "label": "量词"}], "register": "口语", "sense_fingerprint": "道路：人和车走的路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0c09091-d658-4b2c-8dad-66ea54b6e5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86011, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "道", "is_correct": true, "explanation": "道（dào）指人和车行走的路，正是听到的读音。"}, {"text": "刀", "is_correct": false, "explanation": "刀（dāo）与道（dào）声调不同（一声与四声），意思是刀具。"}, {"text": "套", "is_correct": false, "explanation": "套（tào）与道（dào）声母不同（t 与 d），声调相同，意思是套子。"}, {"text": "闹", "is_correct": false, "explanation": "闹（nào）与道（dào）声母不同（n 与 d），声调相同，意思是吵闹。"}], "explanations": {"道": "道（dào）指人和车行走的路，正是听到的读音。", "刀": "刀（dāo）与道（dào）声调不同（一声与四声），意思是刀具。", "套": "套（tào）与道（dào）声母不同（t 与 d），声调相同，意思是套子。", "闹": "闹（nào）与道（dào）声母不同（n 与 d），声调相同，意思是吵闹。"}, "sentence_index": null, "correct_answer": "道"}, "level_3": {"options": [{"text": "道", "is_correct": true, "explanation": "道指人和车行走的路，“这条道很窄，开车要小心”符合句意。"}, {"text": "河", "is_correct": false, "explanation": "语义：河不能用来开车，与“开车要小心”的语境矛盾。"}, {"text": "门", "is_correct": false, "explanation": "搭配：“门”的量词用“扇”，不说“这条门”。"}, {"text": "绳", "is_correct": false, "explanation": "语义：绳子不能用来开车，与句意矛盾。"}], "explanations": {"道": "道指人和车行走的路，“这条道很窄，开车要小心”符合句意。", "河": "语义：河不能用来开车，与“开车要小心”的语境矛盾。", "门": "搭配：“门”的量词用“扇”，不说“这条门”。", "绳": "语义：绳子不能用来开车，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这匹道很窄。", "explanation": "“匹”用于马等动物，道路的量词应是“条”。"}, {"text": "前面有一只道，很窄。", "explanation": "道路的量词应是“条”，这里用了动物等所用的量词，不能搭配道路。"}, {"text": "这把道很窄。", "explanation": "“把”用于有柄的器具、椅子等，道路的量词应是“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df381f64-996e-4af7-994f-7762088bac64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86011, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "道", "is_correct": true, "explanation": "道（dào）指人和车行走的路，正是听到的读音。"}, {"text": "倒", "is_correct": false, "explanation": "倒（dǎo）与道（dào）声调不同（三声与四声），意思是倒下。"}, {"text": "造", "is_correct": false, "explanation": "造（zào）与道（dào）声母不同（z 与 d），声调相同，意思是制造。"}, {"text": "报", "is_correct": false, "explanation": "报（bào）与道（dào）声母不同（b 与 d），声调相同，意思是报纸。"}], "explanations": {"道": "道（dào）指人和车行走的路，正是听到的读音。", "倒": "倒（dǎo）与道（dào）声调不同（三声与四声），意思是倒下。", "造": "造（zào）与道（dào）声母不同（z 与 d），声调相同，意思是制造。", "报": "报（bào）与道（dào）声母不同（b 与 d），声调相同，意思是报纸。"}, "sentence_index": null, "correct_answer": "道"}, "level_3": {"options": [{"text": "道", "is_correct": true, "explanation": "道指路，“这条道直走就到车站”符合句意。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼不能“直走”去车站，与句意矛盾。"}, {"text": "水", "is_correct": false, "explanation": "语义：水不能“直走”，与“到车站”的语境矛盾。"}, {"text": "尺", "is_correct": false, "explanation": "搭配：尺的量词用“把”或“根”，不说“这条尺”。"}], "explanations": {"道": "道指路，“这条道直走就到车站”符合句意。", "鱼": "语义：鱼不能“直走”去车站，与句意矛盾。", "水": "语义：水不能“直走”，与“到车站”的语境矛盾。", "尺": "搭配：尺的量词用“把”或“根”，不说“这条尺”。"}, "sentence_index": 6, "correct_answer": "道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天走这朵道去学校。", "explanation": "“朵”用于花等，道路的量词应是“条”。"}, {"text": "我们村子里有一口道。", "explanation": "“口”多用于井、锅等，道路的量词应是“条”。"}, {"text": "我们镇上新修了一座道，很宽。", "explanation": "道路的量词应是“条”，这里用的是用于山、桥等大型建筑的量词，不能搭配道路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df381f64-996e-4af7-994f-7762088bac64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86011, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只道通向公园。", "corrected_sentence": "那条道通向公园。", "error_description": "道路的量词要用“条”，“只”用于动物等，应为“那条道”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df381f64-996e-4af7-994f-7762088bac64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86011, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张道的两边都是花。", "corrected_sentence": "这条道的两边都是花。", "error_description": "道路的量词要用“条”，“张”用于纸、桌子等平面的东西，应为“这条道”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df381f64-996e-4af7-994f-7762088bac64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
