INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86013, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "倍是说一样东西变成了几个那么多。", "primary_collocate": null, "pronunciation": "bèi", "ipa": "pei̯˥˩", "syllable_count": 1, "sentences": [{"text": "今年的苹果是去年的两倍。", "target_word": "倍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家的书是我家的三倍。", "target_word": "倍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河的宽度是小河的五倍。", "target_word": "倍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个教室是我们旧教室的两倍大。", "target_word": "倍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃的饭是我的三倍。", "target_word": "倍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京的人口是我们小城的十倍。", "target_word": "倍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥的钱是我的四倍。", "target_word": "倍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个盒子里的糖是那个的两倍。", "target_word": "倍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天读的书是以前的三倍。", "target_word": "倍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的水果变成了原来的五倍。", "target_word": "倍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "加倍", "label": "复合"}, {"form": "倍数", "label": "复合"}], "register": "中性", "sense_fingerprint": "倍：某物是另一物的几个那么多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528460c6-b68d-4819-9976-ec879930a8cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86013, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "倍", "is_correct": true, "explanation": "倍（bèi）表示几倍的数量关系，是本题的正确答案。"}, {"text": "杯", "is_correct": false, "explanation": "bēi（第一声）与 bèi（第四声）声调不同，意思是杯子。"}, {"text": "北", "is_correct": false, "explanation": "běi（第三声）与 bèi（第四声）声调不同，意思是北方。"}, {"text": "配", "is_correct": false, "explanation": "pèi 与 bèi 声母不同（p 与 b），意思是配合。"}, {"text": "妹", "is_correct": false, "explanation": "mèi 与 bèi 声母不同（m 与 b），意思是妹妹。"}], "explanations": {"倍": "倍（bèi）表示几倍的数量关系，是本题的正确答案。", "杯": "bēi（第一声）与 bèi（第四声）声调不同，意思是杯子。", "北": "běi（第三声）与 bèi（第四声）声调不同，意思是北方。", "配": "pèi 与 bèi 声母不同（p 与 b），意思是配合。", "妹": "mèi 与 bèi 声母不同（m 与 b），意思是妹妹。"}, "sentence_index": null, "correct_answer": "倍"}, "level_3": {"options": [{"text": "倍", "is_correct": true, "explanation": "倍：表示“是去年的几倍”，与“两”搭配表示倍数关系。"}, {"text": "次", "is_correct": false, "explanation": "语义：“次”计动作或事件的次数，不能表示苹果产量的倍数关系。"}, {"text": "个", "is_correct": false, "explanation": "搭配：“个”计可数的个体，不能用在表示倍数的结构中。"}, {"text": "层", "is_correct": false, "explanation": "语义：“层”计空间或阶层，不能表示数量的倍数。"}], "explanations": {"倍": "倍：表示“是去年的几倍”，与“两”搭配表示倍数关系。", "次": "语义：“次”计动作或事件的次数，不能表示苹果产量的倍数关系。", "个": "搭配：“个”计可数的个体，不能用在表示倍数的结构中。", "层": "语义：“层”计空间或阶层，不能表示数量的倍数。"}, "sentence_index": 0, "correct_answer": "倍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了三倍书。", "explanation": "这里应该用〈本〉。倍表示相差的倍数，不能用来计算书的数量，数书要用“本”。"}, {"text": "我每天要洗三倍澡。", "explanation": "这里应该用〈次〉。倍表示数量之间的倍数，计算洗澡的次数要用“次”。"}, {"text": "我养了三倍猫。", "explanation": "这里应该用〈只〉。猫的量词是“只”，“倍”不能用来数猫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86013, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "倍", "is_correct": true, "explanation": "倍（bèi）表示几倍的数量关系，是本题的正确答案。"}, {"text": "笨", "is_correct": false, "explanation": "bèn 与 bèi 韵母不同（en 与 ei），意思是笨拙。"}, {"text": "悲", "is_correct": false, "explanation": "bēi（第一声）与 bèi（第四声）声调不同，意思是悲伤。"}, {"text": "费", "is_correct": false, "explanation": "fèi 与 bèi 声母不同（f 与 b），意思是费用。"}, {"text": "废", "is_correct": false, "explanation": "fèi 与 bèi 声母不同（f 与 b），意思是废除。"}], "explanations": {"倍": "倍（bèi）表示几倍的数量关系，是本题的正确答案。", "笨": "bèn 与 bèi 韵母不同（en 与 ei），意思是笨拙。", "悲": "bēi（第一声）与 bèi（第四声）声调不同，意思是悲伤。", "费": "fèi 与 bèi 声母不同（f 与 b），意思是费用。", "废": "fèi 与 bèi 声母不同（f 与 b），意思是废除。"}, "sentence_index": null, "correct_answer": "倍"}, "level_3": {"options": [{"text": "倍", "is_correct": true, "explanation": "倍：表示“是我的几倍”，与“四”搭配表示倍数关系。"}, {"text": "遍", "is_correct": false, "explanation": "语义：“遍”指从头到尾一次，计动作的次数，不表示钱的倍数。"}, {"text": "回", "is_correct": false, "explanation": "语义：“回”计动作的次数，不能表示钱的倍数关系。"}, {"text": "度", "is_correct": false, "explanation": "搭配：“度”多用于温度、程度，不能用来计算钱的倍数。"}], "explanations": {"倍": "倍：表示“是我的几倍”，与“四”搭配表示倍数关系。", "遍": "语义：“遍”指从头到尾一次，计动作的次数，不表示钱的倍数。", "回": "语义：“回”计动作的次数，不能表示钱的倍数关系。", "度": "搭配：“度”多用于温度、程度，不能用来计算钱的倍数。"}, "sentence_index": 6, "correct_answer": "倍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把这本书读了三倍。", "explanation": "这里应该用〈遍〉。倍表示倍数，计算从头到尾读的次数要用“遍”。"}, {"text": "我把这些钱分成了三倍。", "explanation": "这里应该用〈份〉。分钱要说“分成三份”，“倍”只表示倍数，不能用来表示分成的部分。"}, {"text": "我来过这里两倍。", "explanation": "这里应该用〈回〉。倍只表示倍数，计算来的次数要用“回”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86013, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台机器的产量是原来的三个倍。", "corrected_sentence": "这台机器的产量是原来的三倍。", "error_description": "错误：“三个倍”。正确：“三倍”。“倍”本身表示倍数，数词后直接接“倍”，不能再加量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86013, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这栋楼的高度是那栋的倍两。", "corrected_sentence": "这栋楼的高度是那栋的两倍。", "error_description": "错误：“倍两”。正确：“两倍”。表示倍数时，数词要放在“倍”前面，应说“两倍”，不能倒过来说“倍两”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
