INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86014, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词，表示某数是另一数的若干次。", "primary_collocate": null, "pronunciation": "bèi", "ipa": "pei̯˥˩", "syllable_count": 1, "sentences": [{"text": "十是五的两倍。", "target_word": "倍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "六是二的三倍。", "target_word": "倍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二十是四的五倍。", "target_word": "倍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一百是十的十倍。", "target_word": "倍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十二是三的四倍。", "target_word": "倍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "九的两倍是十八。", "target_word": "倍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三十是十五的两倍。", "target_word": "倍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "八是四的几倍？", "target_word": "倍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "四十是八的五倍。", "target_word": "倍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二十一是三的七倍。", "target_word": "倍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "加倍", "label": "复合"}, {"form": "倍数", "label": "复合"}], "register": "中性", "sense_fingerprint": "倍：数与数相比的倍数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528460c6-b68d-4819-9976-ec879930a8cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generati