INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86014, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "倍", "is_correct": true, "explanation": "倍（bèi）表示数与数之间的倍数关系，是本题的正确答案。"}, {"text": "杯", "is_correct": false, "explanation": "bēi（第一声）与 bèi（第四声）声调不同，意思是杯子。"}, {"text": "配", "is_correct": false, "explanation": "pèi 与 bèi 声母不同（p 与 b），意思是配合。"}, {"text": "笨", "is_correct": false, "explanation": "bèn 与 bèi 韵母不同（en 与 ei），意思是笨拙。"}, {"text": "费", "is_correct": false, "explanation": "fèi 与 bèi 声母不同（f 与 b），意思是费用。"}], "explanations": {"倍": "倍（bèi）表示数与数之间的倍数关系，是本题的正确答案。", "杯": "bēi（第一声）与 bèi（第四声）声调不同，意思是杯子。", "配": "pèi 与 bèi 声母不同（p 与 b），意思是配合。", "笨": "bèn 与 bèi 韵母不同（en 与 ei），意思是笨拙。", "费": "fèi 与 bèi 声母不同（f 与 b），意思是费用。"}, "sentence_index": null, "correct_answer": "倍"}, "level_3": {"options": [{"text": "倍", "is_correct": true, "explanation": "倍：“三十是十五的几倍”，与“两”搭配表示数之间的倍数关系。"}, {"text": "回", "is_correct": false, "explanation": "语义：“回”计动作的次数，不能表示数字之间的倍数。"}, {"text": "层", "is_correct": false, "explanation": "语义：“层”指空间或阶层，不能表示数字的倍数。"}, {"text": "度", "is_correct": false, "explanation": "搭配：“度”多用于温度、程度，不能表示数字的倍数。"}], "explanations": {"倍": "倍：“三十是十五的几倍”，与“两”搭配表示数之间的倍数关系。", "回": "语义：“回”计动作的次数，不能表示数字之间的倍数。", "层": "语义：“层”指空间或阶层，不能表示数字的倍数。", "度": "搭配：“度”多用于温度、程度，不能表示数字的倍数。"}, "sentence_index": 6, "correct_answer": "倍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我读过这本书两倍。", "explanation": "这里应该用〈遍〉。读书的次数要用“遍”，倍不能表示读的次数。"}, {"text": "他借了两倍书。", "explanation": "这里应该用〈本〉。借书的量词是“本”，“倍”不能用来数书。"}, {"text": "我参加过两倍考试。", "explanation": "这里应该用〈次〉。参加考试的次数要用“次”，倍只表示倍数关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86014, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "八是二的四个倍。", "corrected_sentence": "八是二的四倍。", "error_description": "错误：“四个倍”。正确：“四倍”。“倍”表示倍数，数词后直接接“倍”，不能再加量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86014, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "十二是四的倍三。", "corrected_sentence": "十二是四的三倍。", "error_description": "错误：“倍三”。正确：“三倍”。表示倍数时，数词要放在“倍”前面，应说“三倍”，不能倒过来说“倍三”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
