INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86015, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "“国内”是说自己的国家里面。", "primary_collocate": null, "pronunciation": "guó nèi", "ipa": "kwo˧˥ nei˥˩", "syllable_count": 2, "sentences": [{"text": "他很少去国外，一直在国内工作。", "target_word": "国内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国内的朋友常常给我寄东西。", "target_word": "国内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服在国内买很便宜。", "target_word": "国内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先在国内玩，然后去国外。", "target_word": "国内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在国内读完大学，才去美国。", "target_word": "国内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国内的春节很热闹。", "target_word": "国内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种手机国内也能买到。", "target_word": "国内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国内的火车又快又方便。", "target_word": "国内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想离开国内的家人。", "target_word": "国内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸常在国内出差，很少出国。", "target_word": "国内", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "国内外", "label": "复合"}, {"form": "國內", "label": "繁体"}], "register": "中性", "sense_fingerprint": "相对国外，指自己国家里面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a266faf8-e42e-483b-9de3-08d044cde7d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86015, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国外", "is_correct": false, "explanation": "语义：“国外”与前句“很少去国外”矛盾，“一直在国外工作”说不通。"}, {"text": "海外", "is_correct": false, "explanation": "语义：“海外”同样指国外，与“很少去国外”矛盾。"}, {"text": "国内", "is_correct": true, "explanation": "正确。“国内”指自己国家的里面，与前句“去国外”相对，符合“一直在……工作”。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“工作”的地点必须是场所或单位，不能说“在天气工作”。"}], "explanations": {"国外": "语义：“国外”与前句“很少去国外”矛盾，“一直在国外工作”说不通。", "海外": "语义：“海外”同样指国外，与“很少去国外”矛盾。", "国内": "正确。“国内”指自己国家的里面，与前句“去国外”相对，符合“一直在……工作”。", "天气": "搭配：“工作”的地点必须是场所或单位，不能说“在天气工作”。"}, "sentence_index": 0, "correct_answer": "国内"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场国内比赛有十个国家的选手参加。", "explanation": "这里应该用〈国际〉。“国内”指一个国家的范围之内，有多国选手参加的比赛要用“国际”。"}, {"text": "他去国内留学，已经三年了。", "explanation": "这里应该用〈国外〉。“留学”指到别的国家读书，“国内”只指本国范围之内，不能搭配“留学”。"}, {"text": "他能流利地说三种国内语。", "explanation": "这里应该用〈外国〉。“国内”只指本国范围之内，“外国语”指外国的语言，不能说“国内语”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86015, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国家", "is_correct": false, "explanation": "语义：“买到”的地点应是商店等场所，“国家”不是可以买到东西的地方。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：这里需要表示地方的词，“桌子也能买到”意思说不通。"}, {"text": "国内", "is_correct": true, "explanation": "正确。“国内”指自己国家的范围之内，说明这种手机在本国也能买到。"}, {"text": "灵魂", "is_correct": false, "explanation": "语义：“买到”的对象是商品，“灵魂”不能用来购买。"}], "explanations": {"国家": "语义：“买到”的地点应是商店等场所，“国家”不是可以买到东西的地方。", "桌子": "语义：这里需要表示地方的词，“桌子也能买到”意思说不通。", "国内": "正确。“国内”指自己国家的范围之内，说明这种手机在本国也能买到。", "灵魂": "语义：“买到”的对象是商品，“灵魂”不能用来购买。"}, "sentence_index": 6, "correct_answer": "国内"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "很多年轻人想移民国内，寻找更好的机会。", "explanation": "这里应该用〈海外〉。“移民”是迁到另一个国家定居，“国内”不能作移民的目的地。"}, {"text": "这些产品主要出口到国内。", "explanation": "这里应该用〈境外〉。“出口”是把货物运到国外，不能说“出口到国内”。"}, {"text": "这班飞机从北京出发，飞往国内的伦敦。", "explanation": "这里应该用〈异国〉。“国内”指本国范围之内，伦敦属于别的国家，不能说“国内的伦敦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86015, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本书在国内的卖出了十万本。", "corrected_sentence": "这本书在国内卖出了十万本。", "error_description": "错误：处所状语修饰动词时不用“的”，“在国内的卖出”应说“在国内卖出”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86015, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的父母一直国内生活。", "corrected_sentence": "他的父母一直在国内生活。", "error_description": "错误：表示处所的“国内”前漏了介词“在”，应说“一直在国内生活”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
