INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86016, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "名词，指一个国家的领土范围之内。", "primary_collocate": null, "pronunciation": "guó nèi", "ipa": "kwo˧˥ nei˥˩", "syllable_count": 2, "sentences": [{"text": "这座山的大部分都在国内。", "target_word": "国内", "complexity_tier": "T3", "furigana": "zhè zuò shān de dà bù fèn dōu zài guó nèi", "sentence_source": "generated"}, {"text": "国内有很多大城市，北京和上海最有名。", "target_word": "国内", "complexity_tier": "T3", "furigana": "guó nèi yǒu hěn duō dà chéng shì, běi jīng hé shàng hǎi zuì yǒu míng", "sentence_source": "generated"}, {"text": "国内各地的饭菜都不一样。", "target_word": "国内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路只在国内，不通到国外。", "target_word": "国内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国内最高的山在西边。", "target_word": "国内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司在国内有二十家商店。", "target_word": "国内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国内的机票比国外的便宜。", "target_word": "国内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛只有国内的学生参加。", "target_word": "国内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国内每个城市都有火车站。", "target_word": "国内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的飞机只在国内飞，不去别的国家。", "target_word": "国内", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "国内外", "label": "复合"}, {"form": "國內", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一个国家领土范围之内的各地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a266faf8-e42e-483b-9de3-08d044cde7d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86016, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工厂", "is_correct": false, "explanation": "语义：山不可能在工厂里，“大部分都在工厂”说不通。"}, {"text": "夏天", "is_correct": false, "explanation": "搭配：“在”后接处所，不能接时间词“夏天”来说山的位置。"}, {"text": "国内", "is_correct": true, "explanation": "正确。“国内”指一个国家的领土范围之内，符合“大部分都在……”说山在本国境内。"}, {"text": "学校", "is_correct": false, "explanation": "语义：山不可能在学校里，与“这座山”的语境不符。"}], "explanations": {"工厂": "语义：山不可能在工厂里，“大部分都在工厂”说不通。", "夏天": "搭配：“在”后接处所，不能接时间词“夏天”来说山的位置。", "国内": "正确。“国内”指一个国家的领土范围之内，符合“大部分都在……”说山在本国境内。", "学校": "语义：山不可能在学校里，与“这座山”的语境不符。"}, "sentence_index": 0, "correct_answer": "国内"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次会议有五十多个国家参加，是一次国内会议。", "explanation": "这里应该用〈国际〉。“国内”指一个国家的范围之内，多国参加的会议要用“国际”。"}, {"text": "他十年前移民到国内，现在已经很习惯了。", "explanation": "这里应该用〈国外〉。“移民”是离开本国到另一个国家定居，“国内”不能作移民的目的地。"}, {"text": "他的家在国内，但他常年在国内的伦敦工作。", "explanation": "这里应该用〈国外〉。伦敦在别的国家，“国内”只指本国范围之内，不能说“国内的伦敦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86016, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饭馆", "is_correct": false, "explanation": "语义：饭馆不卖机票，“饭馆的机票”说不通。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“机票”不属于“手机”，二者不能组成这样的定语搭配。"}, {"text": "国内", "is_correct": true, "explanation": "正确。“国内”指本国范围之内，与“比国外的便宜”形成对比，语义通顺。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不卖机票，“天空的机票”没有意义。"}], "explanations": {"饭馆": "语义：饭馆不卖机票，“饭馆的机票”说不通。", "手机": "搭配：“机票”不属于“手机”，二者不能组成这样的定语搭配。", "国内": "正确。“国内”指本国范围之内，与“比国外的便宜”形成对比，语义通顺。", "天空": "语义：天空不卖机票，“天空的机票”没有意义。"}, "sentence_index": 6, "correct_answer": "国内"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他下周要出境，去国内的分公司开会。", "explanation": "这里应该用〈国外〉。“出境”是离开本国到别的国家，与“国内”矛盾，不能去“国内”。"}, {"text": "这家工厂的产品大多出口到国内。", "explanation": "这里应该用〈国外〉。“出口”是把货物运到别的国家，不能说“出口到国内”。"}, {"text": "她计划去国内留学，学习两年日语。", "explanation": "这里应该用〈国外〉。“留学”是到别的国家读书，“国内”只指本国范围之内。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86016, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们的产品在国内的很受欢迎。", "corrected_sentence": "我们的产品在国内很受欢迎。", "error_description": "错误：“在国内”修饰形容词谓语时不能用“的”，应说“在国内很受欢迎”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86016, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种饮料只在国内销售，国内买不到。", "corrected_sentence": "这种饮料只在国内销售，国外买不到。", "error_description": "错误：“只在国内销售”说明本国有售，后半句“国内买不到”自相矛盾，应为“国外买不到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
