INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86017, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，用在后一分句，加重语气，强调某种结果或情况，相当于「就」的加强形式。", "primary_collocate": null, "pronunciation": "kě jiù", "ipa": "kʰɤ˨˩˦ tɕjoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "明天可就是新年了。", "target_word": "可就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你再不说话，我可就走了。", "target_word": "可就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要是再不去，可就晚了。", "target_word": "可就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这下可就好了，大家都来了。", "target_word": "可就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一来，事情可就麻烦了。", "target_word": "可就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天黑以后，路上可就不好走了。", "target_word": "可就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下个月可就要考试了，快复习吧。", "target_word": "可就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次机会没了，以后可就难找了。", "target_word": "可就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是大家都不来，这个会可就开不成了。", "target_word": "可就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长大了，你可就轻松了。", "target_word": "可就", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "用在后一分句，加重语气，强调结果或情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '090b0596-03c6-49fa-9960-4cdd5ded62a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86017, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可就", "is_correct": true, "explanation": "正确。“可就”在此加强语气，强调明天就是新年。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示事情已经发生，与“明天”这一将来时间相矛盾。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去的经历，不能用于“明天”这样的将来时间。"}, {"text": "忽然", "is_correct": false, "explanation": "搭配：“忽然”表示突然发生，不与“明天是新年”这种既定日期搭配。"}], "explanations": {"可就": "正确。“可就”在此加强语气，强调明天就是新年。", "已经": "语义：“已经”表示事情已经发生，与“明天”这一将来时间相矛盾。", "曾经": "语义：“曾经”指过去的经历，不能用于“明天”这样的将来时间。", "忽然": "搭配：“忽然”表示突然发生，不与“明天是新年”这种既定日期搭配。"}, "sentence_index": 0, "correct_answer": "可就"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里可就停车。", "explanation": "这里应该用〈可以〉。“可就”表示强调或结果，不表示许可，允许停车要用“可以”。"}, {"text": "这件事你可就决定。", "explanation": "这里应该用〈能〉。“可就”不表示能力，“你能决定这件事”才对。"}, {"text": "这个孩子可就十岁，却已经会弹钢琴了。", "explanation": "这里应该用〈才〉。“可就”强调结果，不表示年龄小，“这个孩子才十岁”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86017, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可就", "is_correct": true, "explanation": "正确。“可就”在此加强语气，强调下个月就要考试了。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”指刚发生的事，与“下个月”的将来安排矛盾。"}, {"text": "早就", "is_correct": false, "explanation": "语义：“早就”指很早以前已经发生，与“下个月”的将来时间冲突。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”表示持续的状态，不与“要……了”这种一次性的将来安排搭配。"}], "explanations": {"可就": "正确。“可就”在此加强语气，强调下个月就要考试了。", "刚刚": "语义：“刚刚”指刚发生的事，与“下个月”的将来安排矛盾。", "早就": "语义：“早就”指很早以前已经发生，与“下个月”的将来时间冲突。", "一直": "搭配：“一直”表示持续的状态，不与“要……了”这种一次性的将来安排搭配。"}, "sentence_index": 6, "correct_answer": "可就"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我可就进去吗？", "explanation": "这里应该用〈可以〉。“可就”不表示许可，询问能否进入要用“可以”。"}, {"text": "这些书我可就借给你。", "explanation": "这里应该用〈可以〉。“可就”不表示许可，“这些书我可以借给你”才对。"}, {"text": "这本书可就他的。", "explanation": "这里应该用〈是〉。“可就”不能直接用于判断句，“这本书是他的”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86017, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他要是不来，我可就就不等了。", "corrected_sentence": "他要是不来，我可就不等了。", "error_description": "重复副词：“可就”是一个整体副词，“就”已包含在内，不能再加“就”。应说“我可就不等了”，不能说“我可就就不等了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86017, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你再不快点儿，可的就晚了。", "corrected_sentence": "你再不快点儿，可就晚了。", "error_description": "错误：“可就”是一个整体副词，中间不能插入“的”。应说“可就晚了”，不能说“可的就晚了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
