INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86018, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，用于加强语气，常带有强调或转折的意味。", "primary_collocate": null, "pronunciation": "kě jiù", "ipa": "kʰɤ˨˩˦ tɕjoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他一走，家里可就安静了。", "target_word": "可就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天一冷，感冒的人可就多了。", "target_word": "可就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨一停，公园里的人可就多起来了。", "target_word": "可就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老王一回家，孩子们可就高兴了。", "target_word": "可就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱花完了，这个月可就难熬了。", "target_word": "可就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他平时很安静，一上台可就不一样了。", "target_word": "可就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要是答应了，可就不能改了。", "target_word": "可就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平时不复习，考试时可就麻烦了。", "target_word": "可就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个消息，大家可就着急了。", "target_word": "可就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了今天，这个价钱可就买不到了。", "target_word": "可就", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "前后情况对比，强调变化或转折后的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '090b0596-03c6-49fa-9960-4cdd5ded62a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86018, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可就", "is_correct": true, "explanation": "正确。“可就”在此表示前后情况对比，强调“一走”之后家里出现的变化。"}, {"text": "早就", "is_correct": false, "explanation": "语义：“早就”指很久以前已经发生，与“一走”引起的当下变化相矛盾。"}, {"text": "曾经", "is_correct": false, "explanation": "搭配：“曾经”表示过去的经历，不能与“一……就……”表示的即时结果搭配。"}, {"text": "向来", "is_correct": false, "explanation": "语义：“向来”指一贯如此，与“一走”才出现的变化矛盾。"}], "explanations": {"可就": "正确。“可就”在此表示前后情况对比，强调“一走”之后家里出现的变化。", "早就": "语义：“早就”指很久以前已经发生，与“一走”引起的当下变化相矛盾。", "曾经": "搭配：“曾经”表示过去的经历，不能与“一……就……”表示的即时结果搭配。", "向来": "语义：“向来”指一贯如此，与“一走”才出现的变化矛盾。"}, "sentence_index": 0, "correct_answer": "可就"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里可就吸烟吗？", "explanation": "这里应该用〈可以〉。“可就”不表示许可，询问能否吸烟要用“可以”。"}, {"text": "他可就游泳吗？", "explanation": "这里应该用〈会〉。“可就”不表示技能，询问会不会游泳要用“会”。"}, {"text": "你可就帮我拿一下书吗？", "explanation": "这里应该用〈可以〉。“可就”不表示请求或许可，请别人帮忙要用“可以”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86018, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可就", "is_correct": true, "explanation": "正确。“可就”在此表示前后情况对比，强调答应之后出现的变化。"}, {"text": "正在", "is_correct": false, "explanation": "语义：“正在”表示动作进行中，与“答应了”这一已完成的动作不相符，不能用于此句。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”表示持续的状态，不与“……了，……不能改了”这种变化结果搭配。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”指刚发生的事，与假设性的“要是答应了”不相符。"}], "explanations": {"可就": "正确。“可就”在此表示前后情况对比，强调答应之后出现的变化。", "正在": "语义：“正在”表示动作进行中，与“答应了”这一已完成的动作不相符，不能用于此句。", "一直": "搭配：“一直”表示持续的状态，不与“……了，……不能改了”这种变化结果搭配。", "刚刚": "语义：“刚刚”指刚发生的事，与假设性的“要是答应了”不相符。"}, "sentence_index": 6, "correct_answer": "可就"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我可就打电话给他吗？", "explanation": "这里应该用〈可以〉。“可就”不表示许可，询问能否打电话要用“可以”。"}, {"text": "我可就用一下你的笔吗？", "explanation": "这里应该用〈可以〉。“可就”不表示许可，借用东西要问“可以……吗”。"}, {"text": "他可就坐在前排吧。", "explanation": "这里应该用〈应该〉或〈最好〉。“可就”不表示建议，“他最好坐在前排”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86018, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天一黑，路上可就没人着。", "corrected_sentence": "天一黑，路上可就没人了。", "error_description": "体标误用：表示变化已经发生要用“了”，“着”表示持续状态，不能用于“没人”之后。正确为“天一黑，路上可就没人了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86018, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你要是不信，我不可就不管了。", "corrected_sentence": "你要是不信，我可就不管了。", "error_description": "“可就”是副词，前面不能再加否定词“不”。“不”只能用在“可就”之后的动词前。正确为“我可就不管了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
