INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86019, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "“天”是我们头上看到的高高的地方，指天空。", "primary_collocate": null, "pronunciation": "tiān", "ipa": "tʰjɛn˥", "syllable_count": 1, "sentences": [{"text": "天很蓝，云很白。", "target_word": "天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天上有一只鸟。", "target_word": "天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你看，天上有月亮。", "target_word": "天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天上的云越来越多了。", "target_word": "天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要下雨了，天一下子黑了。", "target_word": "天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上天很黑，天上有很多星星。", "target_word": "天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟在天上飞着，真自由。", "target_word": "天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他抬头看着天，想了很久。", "target_word": "天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机从天上飞过，留下一条白线。", "target_word": "天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停了，天慢慢晴了。", "target_word": "天", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "天上", "label": "复合"}], "register": "中性", "sense_fingerprint": "天：头顶上的天空", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e3854f-4e11-4bc9-a35e-a40d78ee0dbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86019, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "天", "is_correct": true, "explanation": "正确：听到的是 tiān（第一声），即“天”，指头顶的天空。"}, {"text": "甜", "is_correct": false, "explanation": "tián（第二声）与 tiān（第一声）声调不同，意思是甜。"}, {"text": "舔", "is_correct": false, "explanation": "tiǎn（第三声）与 tiān（第一声）声母、韵母相同，只差声调，意思是用舌头舔。"}, {"text": "填", "is_correct": false, "explanation": "tián（第二声）与 tiān（第一声）只差声调，意思是填入。"}], "explanations": {"天": "正确：听到的是 tiān（第一声），即“天”，指头顶的天空。", "甜": "tián（第二声）与 tiān（第一声）声调不同，意思是甜。", "舔": "tiǎn（第三声）与 tiān（第一声）声母、韵母相同，只差声调，意思是用舌头舔。", "填": "tián（第二声）与 tiān（第一声）只差声调，意思是填入。"}, "sentence_index": null, "correct_answer": "天"}, "level_3": {"options": [{"text": "天", "is_correct": true, "explanation": "正确：“天很蓝，云很白”描写头顶的天空，“天”符合语境。"}, {"text": "地", "is_correct": false, "explanation": "语义：“地”指大地，与后面“云很白”的天空场景不符。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“蓝”可以形容天空，却不能说饭很蓝。"}, {"text": "课", "is_correct": false, "explanation": "语义：“课”不是可以呈现颜色的事物，与“云很白”的场景无关。"}], "explanations": {"天": "正确：“天很蓝，云很白”描写头顶的天空，“天”符合语境。", "地": "语义：“地”指大地，与后面“云很白”的天空场景不符。", "饭": "搭配：“蓝”可以形容天空，却不能说饭很蓝。", "课": "语义：“课”不是可以呈现颜色的事物，与“云很白”的场景无关。"}, "sentence_index": 0, "correct_answer": "天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我站在山顶，看见一座天，很蓝。", "explanation": "这里应该用〈一片〉。“座”用于山、楼等大型固定物，不能计量“天”（天空）；这里要用“片”。"}, {"text": "我站在窗前，看见一棵天，很高。", "explanation": "这里应该用〈一片〉。“棵”用于树木，不能计量“天”（天空）；这里要用“片”。"}, {"text": "夜里我看见一只天，很黑。", "explanation": "这里应该用〈一片〉。“只”用于动物等，不能计量“天”（天空）；这里要用“片”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13402954-c630-4519-a3be-3fd308727130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86019, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "天", "is_correct": true, "explanation": "正确：听到的是 tiān（第一声），即“天”，指头顶的天空。"}, {"text": "田", "is_correct": false, "explanation": "tián（第二声）与 tiān（第一声）声调不同，意思是田地。"}, {"text": "舔", "is_correct": false, "explanation": "tiǎn（第三声）与 tiān（第一声）只差声调，意思是用舌头舔。"}, {"text": "贪", "is_correct": false, "explanation": "tān（第一声）与 tiān（第一声）只差介音 i，意思是贪心。"}], "explanations": {"天": "正确：听到的是 tiān（第一声），即“天”，指头顶的天空。", "田": "tián（第二声）与 tiān（第一声）声调不同，意思是田地。", "舔": "tiǎn（第三声）与 tiān（第一声）只差声调，意思是用舌头舔。", "贪": "tān（第一声）与 tiān（第一声）只差介音 i，意思是贪心。"}, "sentence_index": null, "correct_answer": "天"}, "level_3": {"options": [{"text": "天", "is_correct": true, "explanation": "正确：“小鸟在天上飞着”表示在空中飞，符合语境。"}, {"text": "碗", "is_correct": false, "explanation": "语义：“碗”是器皿，不能作为小鸟飞行的空间。"}, {"text": "墨水", "is_correct": false, "explanation": "搭配：“在……上飞”不能用“墨水”作处所。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”不是飞行的空间，与“小鸟飞着”不合。"}], "explanations": {"天": "正确：“小鸟在天上飞着”表示在空中飞，符合语境。", "碗": "语义：“碗”是器皿，不能作为小鸟飞行的空间。", "墨水": "搭配：“在……上飞”不能用“墨水”作处所。", "作业": "语义：“作业”不是飞行的空间，与“小鸟飞着”不合。"}, "sentence_index": 6, "correct_answer": "天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "傍晚我抬头，看见一颗天，很亮。", "explanation": "这里应该用〈一片〉。“颗”用于星星、果实等小而圆的东西，不能计量“天”（天空）；这里要用“片”。"}, {"text": "他站在门口，看见一扇天，很高。", "explanation": "这里应该用〈一片〉。“扇”用于门窗，不能计量“天”（天空）；这里要用“片”。"}, {"text": "我在屋里望见一面天，很蓝。", "explanation": "这里应该用〈一片〉。“面”用于镜子、旗子等平面的东西，不能计量“天”（天空）；这里要用“片”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13402954-c630-4519-a3be-3fd308727130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86019, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他抬头看见一个天，很蓝。", "corrected_sentence": "他抬头看见一片天，很蓝。", "error_description": "错误：“天”指天空，看到一片天时量词应为“片”，不能用“个”。正确：“他抬头看见一片天，很蓝。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13402954-c630-4519-a3be-3fd308727130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86019, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几只燕子在上天飞来飞去。", "corrected_sentence": "几只燕子在天上飞来飞去。", "error_description": "错误：“上天”是动词，表示升上天空或去世，不能表示“在天空中”；表示位置要说“在天上”。正确：“几只燕子在天上飞来飞去。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13402954-c630-4519-a3be-3fd308727130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
