INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86021, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "“然后”是说做完一件事，再接着做另一件事。", "primary_collocate": null, "pronunciation": "rán hòu", "ipa": "ɻan˧˥ xou˥˩", "syllable_count": 2, "sentences": [{"text": "我先洗手，然后吃饭。", "target_word": "然后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先做作业，然后看了一会儿电视。", "target_word": "然后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先往前走，然后在第二个路口往左拐。", "target_word": "然后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先把菜洗好，然后再切。", "target_word": "然后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先去超市，然后回家做饭。", "target_word": "然后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课以后，他先去吃饭，然后去图书馆。", "target_word": "然后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先写名字，然后写电话号码。", "target_word": "然后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她先笑了笑，然后慢慢地说了几句话。", "target_word": "然后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上我先跑步，然后洗澡。", "target_word": "然后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先喝点水，然后我们再说。", "target_word": "然后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "然後", "label": "繁体"}], "register": "中性", "sense_fingerprint": "然后：前一件事做完，再接着做下一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee9cc0a1-56c1-4470-a8fc-b7afcfb653ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86021, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "然后", "is_correct": true, "explanation": "然后：连接先后发生的动作，与前面的“先”呼应，填入空格正确。"}, {"text": "但是", "is_correct": false, "explanation": "语义：“但是”表转折，洗手和吃饭之间没有对比，与“先…”的顺序不合。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”需与后面的“但是”或“却”呼应，这里缺少呼应。"}, {"text": "而是", "is_correct": false, "explanation": "搭配：“而是”需与前面的“不是”呼应，这里没有否定词。"}], "explanations": {"然后": "然后：连接先后发生的动作，与前面的“先”呼应，填入空格正确。", "但是": "语义：“但是”表转折，洗手和吃饭之间没有对比，与“先…”的顺序不合。", "虽然": "搭配：“虽然”需与后面的“但是”或“却”呼应，这里缺少呼应。", "而是": "搭配：“而是”需与前面的“不是”呼应，这里没有否定词。"}, "sentence_index": 0, "correct_answer": "然后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "如果下雨，我们然后不去。", "explanation": "这里应该用〈就〉。“如果…就…”引出结果，然后只表示先后，不能引出结果。"}, {"text": "这个房间又大然后亮。", "explanation": "这里应该用〈而且〉。然后表示先后，不能连接并列的形容词，并列描述要用“而且”。"}, {"text": "他越跑然后越快。", "explanation": "这里应该用〈越…越…〉。“越跑越快”表示程度随着变化，然后只表示先后，不能插在中间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0dc6dfe-fc46-4ee2-b5fa-292425c0baf5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86021, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "然后", "is_correct": true, "explanation": "然后：连接先后发生的动作，与前面的“先”呼应，填入空格正确。"}, {"text": "否则", "is_correct": false, "explanation": "语义：“否则”表示另一种选择或后果，与“先写名字再写号码”的顺序不合。"}, {"text": "以及", "is_correct": false, "explanation": "语域：“以及”是书面并列用语，口语指令中用来连接两个动作很不自然。"}, {"text": "不但", "is_correct": false, "explanation": "搭配：“不但”需与“而且”或“还”呼应，这里缺少呼应。"}], "explanations": {"然后": "然后：连接先后发生的动作，与前面的“先”呼应，填入空格正确。", "否则": "语义：“否则”表示另一种选择或后果，与“先写名字再写号码”的顺序不合。", "以及": "语域：“以及”是书面并列用语，口语指令中用来连接两个动作很不自然。", "不但": "搭配：“不但”需与“而且”或“还”呼应，这里缺少呼应。"}, "sentence_index": 6, "correct_answer": "然后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "不管天气如何，然后我们去。", "explanation": "这里应该用〈都〉。“不管…都…”要与“都”呼应，然后只表示先后，不能替代“都”。"}, {"text": "不是喝茶，然后是喝咖啡。", "explanation": "这里应该用〈而是〉。“不是…而是…”表示对比，然后不能替代“而是”。"}, {"text": "虽然他很累，然后还在工作。", "explanation": "这里应该用〈却〉。“虽然…却…”表示让步，然后只表示先后，不能用在“虽然”之后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0dc6dfe-fc46-4ee2-b5fa-292425c0baf5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86021, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他先看书，然后了睡觉。", "corrected_sentence": "他先看书，然后睡觉。", "error_description": "“然后”后不能直接加“了”。“了”应加在动词之后，“然后了睡觉”不成立，应说“然后睡觉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0dc6dfe-fc46-4ee2-b5fa-292425c0baf5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86021, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们吃完晚饭，就然后去散步吧。", "corrected_sentence": "我们吃完晚饭，然后去散步吧。", "error_description": "“然后”前不能再加“就”。两者都表示先后，重复使用，应只用“然后”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0dc6dfe-fc46-4ee2-b5fa-292425c0baf5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
