INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86026, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示一直、始终、总是。", "primary_collocate": null, "pronunciation": "zǒng", "ipa": "tsʊŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "他心里总想着家乡。", "target_word": "总", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈总惦记着我吃得好不好。", "target_word": "总", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些年，她总记着老朋友的生日。", "target_word": "总", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人总爱坐在门口看路上的人。", "target_word": "总", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他嘴上不说，心里总觉得对不起你。", "target_word": "总", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小时候的事，我总记得很清楚。", "target_word": "总", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不管多忙，他总关心着孩子的学习。", "target_word": "总", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个孩子总不说话，大家都很担心。", "target_word": "总", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我总相信，努力一定会有结果。", "target_word": "总", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事我总觉得有点奇怪。", "target_word": "总", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "总是", "label": "复合"}, {"form": "总得", "label": "复合"}], "register": "口语", "sense_fingerprint": "总：副词，表示一直、始终，一种状态持续不变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4282b7-916c-4da7-bd32-a72c5ffbca2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86026, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "总", "is_correct": true, "explanation": "正确：总，zǒng（第三声），意思是一直、始终。"}, {"text": "宗", "is_correct": false, "explanation": "zōng（第一声）与 zǒng（第三声）声调不同，意思是宗族。"}, {"text": "纵", "is_correct": false, "explanation": "zòng（第四声）与 zǒng（第三声）声调不同，意思是放纵。"}, {"text": "种", "is_correct": false, "explanation": "zhǒng 与 zǒng 声母不同（zh/z），意思是种类。"}, {"text": "走", "is_correct": false, "explanation": "zǒu 与 zǒng 韵母不同（ou/ong），意思是行走。"}], "explanations": {"总": "正确：总，zǒng（第三声），意思是一直、始终。", "宗": "zōng（第一声）与 zǒng（第三声）声调不同，意思是宗族。", "纵": "zòng（第四声）与 zǒng（第三声）声调不同，意思是放纵。", "种": "zhǒng 与 zǒng 声母不同（zh/z），意思是种类。", "走": "zǒu 与 zǒng 韵母不同（ou/ong），意思是行走。"}, "sentence_index": null, "correct_answer": "总"}, "level_3": {"options": [{"text": "总", "is_correct": true, "explanation": "正确：“总”表示一直如此，与“想着”所表示的持续状态相符。"}, {"text": "突然", "is_correct": false, "explanation": "体貌：“突然”表示瞬间发生，与“想着”表示的持续状态相冲突。"}, {"text": "亲自", "is_correct": false, "explanation": "语义：“亲自”指本人亲身去做，“心里”是内心活动，不能亲身去做。"}, {"text": "赶紧", "is_correct": false, "explanation": "搭配：“赶紧”要求马上行动，不能修饰“心里想着”这样的持续状态。"}], "explanations": {"总": "正确：“总”表示一直如此，与“想着”所表示的持续状态相符。", "突然": "体貌：“突然”表示瞬间发生，与“想着”表示的持续状态相冲突。", "亲自": "语义：“亲自”指本人亲身去做，“心里”是内心活动，不能亲身去做。", "赶紧": "搭配：“赶紧”要求马上行动，不能修饰“心里想着”这样的持续状态。"}, "sentence_index": 0, "correct_answer": "总"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他总在去年夏天去过一次北京。", "explanation": "这里不能用“总”。“总”表示一直如此、反复出现，“去年夏天去过一次”是一次性的经历，两者矛盾。"}, {"text": "我总在昨天买了一辆新车。", "explanation": "这里不能用“总”。“总”表示一直如此，“昨天买了一辆新车”是一次性的事，两者矛盾。"}, {"text": "我们总刚刚搬进新家。", "explanation": "这里不能用“总”。“总”表示一直、反复如此，“刚刚搬进”是不久前发生的一次动作，两者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86026, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "总", "is_correct": true, "explanation": "正确：总，zǒng（第三声），意思是一直、始终。"}, {"text": "综", "is_correct": false, "explanation": "zōng（第一声）与 zǒng（第三声）声调不同，意思是综合。"}, {"text": "粽", "is_correct": false, "explanation": "zòng（第四声）与 zǒng（第三声）声调不同，意思是粽子。"}, {"text": "棕", "is_correct": false, "explanation": "zōng（第一声）与 zǒng（第三声）声调不同，意思是棕色。"}], "explanations": {"总": "正确：总，zǒng（第三声），意思是一直、始终。", "综": "zōng（第一声）与 zǒng（第三声）声调不同，意思是综合。", "粽": "zòng（第四声）与 zǒng（第三声）声调不同，意思是粽子。", "棕": "zōng（第一声）与 zǒng（第三声）声调不同，意思是棕色。"}, "sentence_index": null, "correct_answer": "总"}, "level_3": {"options": [{"text": "总", "is_correct": true, "explanation": "正确：“总”表示一直如此，与“关心着”的持续状态相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“不管多忙”后持续关心的意思相反。"}, {"text": "遂", "is_correct": false, "explanation": "语域：“遂”是书面语，与这句口语化的叙述不协调。"}, {"text": "乃", "is_correct": false, "explanation": "语域：“乃”是文言色彩很重的副词，放在这句白话里很突兀。"}], "explanations": {"总": "正确：“总”表示一直如此，与“关心着”的持续状态相符。", "偶尔": "语义：“偶尔”表示不常发生，与“不管多忙”后持续关心的意思相反。", "遂": "语域：“遂”是书面语，与这句口语化的叙述不协调。", "乃": "语域：“乃”是文言色彩很重的副词，放在这句白话里很突兀。"}, "sentence_index": 6, "correct_answer": "总"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座桥总在一九九八年建成。", "explanation": "这里不能用“总”。“总”表示一直、反复如此，“一九九八年建成”是一次性的事，两者矛盾。"}, {"text": "这次旅行，他总第一次坐飞机。", "explanation": "这里不能用“总”。“总”表示一直、反复如此，“第一次坐飞机”只发生一次，两者矛盾。"}, {"text": "他总一次性还清了所有欠款。", "explanation": "这里不能用“总”。“总”表示一直、反复如此，“一次性还清”是只发生一次的事，两者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86026, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一直以来，她坐总在第一排。", "corrected_sentence": "一直以来，她总坐在第一排。", "error_description": "错误在于“总”的位置。“总”是副词，应放在动词“坐”之前，说“总坐”；“坐总”语序不对，母语者会立刻觉得不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86026, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "不管多忙，他关总心着女儿的学习。", "corrected_sentence": "不管多忙，他总关心着女儿的学习。", "error_description": "错误在于“总”的位置。“总”是副词，应放在“关心”之前；插进双音节词“关心”中间，“关总心”不成词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
