INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86027, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86027, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "多时是很长的一段时间。", "primary_collocate": null, "pronunciation": "duō shí", "ipa": "tuɔ˥ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "他病了多时，一直没去上班。", "target_word": "多时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们没见面已经多时了。", "target_word": "多时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位老人在公园里走了多时。", "target_word": "多时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家在雨里站了多时，衣服都湿了。", "target_word": "多时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题他研究多时了。", "target_word": "多时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她盼着这一天，已经盼了多时。", "target_word": "多时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在门外叫了多时，没人理它。", "target_word": "多时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他早就走了多时，你追不上了。", "target_word": "多时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈在厨房里忙了多时，做了一桌菜。", "target_word": "多时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家的电视坏了多时，一直没有修。", "target_word": "多时", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "很长的一段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56992c47-6832-429b-9ec5-b51f9d7bdb63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86027, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "凌晨", "is_correct": false, "explanation": "搭配：“凌晨”是时点，不能作“病了”的时段，“病了凌晨”不成说法。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指将来的时间，与“病了”这件已经发生的事冲突。"}, {"text": "多时", "is_correct": true, "explanation": "多时：表示很长的时间，与“病了”和“一直没去上班”的语境相合。"}, {"text": "片刻", "is_correct": false, "explanation": "语义：“片刻”指极短的时间，与“一直没去上班”的持续状态相反。"}], "explanations": {"凌晨": "搭配：“凌晨”是时点，不能作“病了”的时段，“病了凌晨”不成说法。", "明天": "语义：“明天”指将来的时间，与“病了”这件已经发生的事冲突。", "多时": "多时：表示很长的时间，与“病了”和“一直没去上班”的语境相合。", "片刻": "语义：“片刻”指极短的时间，与“一直没去上班”的持续状态相反。"}, "sentence_index": 0, "correct_answer": "多时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他只站了多时就走了。", "explanation": "这里应该用〈片刻〉。多时指很长的时间，与“只”表示时间很短相矛盾。"}, {"text": "多时就过去了一周。", "explanation": "这里应该用〈转眼〉。多时指很长的时间，不能表示眨眼之间的快速变化。"}, {"text": "电话多时响了一下。", "explanation": "这里应该用〈刚刚〉。多时指很长的时间，与“一下”表示的短暂动作相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86027, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "今年", "is_correct": false, "explanation": "搭配：“今年”是年份，不能作“叫”的时段，“叫了今年”搭配不当。"}, {"text": "清晨", "is_correct": false, "explanation": "搭配：“清晨”是时点，不能表示持续的叫声，“叫了清晨”不成说法。"}, {"text": "多时", "is_correct": true, "explanation": "多时：表示很长的时间，与“叫了”和“没人理它”的语境相合。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指将来的时间，不能作“叫”的时段，“叫了明天”不成说法。"}], "explanations": {"今年": "搭配：“今年”是年份，不能作“叫”的时段，“叫了今年”搭配不当。", "清晨": "搭配：“清晨”是时点，不能表示持续的叫声，“叫了清晨”不成说法。", "多时": "多时：表示很长的时间，与“叫了”和“没人理它”的语境相合。", "明天": "语义：“明天”指将来的时间，不能作“叫”的时段，“叫了明天”不成说法。"}, "sentence_index": 6, "correct_answer": "多时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们昨天多时到了学校。", "explanation": "这里误把〈多时〉当作表示〈时刻〉的词用了。多时只表示很长的一段时间，不能指具体的时刻。"}, {"text": "会议清早多时开始。", "explanation": "这里误把〈多时〉当作表示〈时刻〉的词用了。多时只表示很长的一段时间，不能指具体的时刻。"}, {"text": "他那天多时离开了家。", "explanation": "这里误把〈多时〉当作表示〈时刻〉的词用了。多时只表示很长的一段时间，不能指具体的时刻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86027, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶在医院住了很多时，一直没回家。", "corrected_sentence": "奶奶在医院住了多时，一直没回家。", "error_description": "“多时”本身已表示很长的时间，前面不能再加“很”。应说“住了多时”，不说“住了很多时”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86027, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家的洗衣机坏多时，一直没有修。", "corrected_sentence": "我家的洗衣机坏了多时，一直没有修。", "error_description": "漏掉动态助词：单音节动词“坏”后面要加“了”，应说“坏了多时”，不说“坏多时”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
