INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86028, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很长的时间。", "primary_collocate": null, "pronunciation": "duō shí", "ipa": "tuɔ˥ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "我在门口等了多时，他才来。", "target_word": "多时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们已经分别多时了。", "target_word": "多时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事我想了多时，还是决定去。", "target_word": "多时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老朋友多时不见，今天特别高兴。", "target_word": "多时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人在客厅里坐了多时。", "target_word": "多时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她看着窗外，站了多时。", "target_word": "多时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店关门多时了，你还不知道吗？", "target_word": "多时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们谈了多时，也没谈出办法。", "target_word": "多时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他等候多时，终于见到了校长。", "target_word": "多时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子哭了多时，现在才睡着。", "target_word": "多时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "很长的一段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56992c47-6832-429b-9ec5-b51f9d7bdb63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86028, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "清晨", "is_correct": false, "explanation": "搭配：“清晨”是时点，不能作“等”的时段，“等了清晨”不成说法。"}, {"text": "多时", "is_correct": true, "explanation": "多时：表示很长的时间，与“等了”和“才来”的语境相合。"}, {"text": "今年", "is_correct": false, "explanation": "搭配：“今年”指一个年份，不能作“等”的时段，“等了今年”搭配不当。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指将来的时间，与“等了”所表示的已经过去的等候不符，“等了明天”不成说法。"}], "explanations": {"清晨": "搭配：“清晨”是时点，不能作“等”的时段，“等了清晨”不成说法。", "多时": "多时：表示很长的时间，与“等了”和“才来”的语境相合。", "今年": "搭配：“今年”指一个年份，不能作“等”的时段，“等了今年”搭配不当。", "明天": "语义：“明天”指将来的时间，与“等了”所表示的已经过去的等候不符，“等了明天”不成说法。"}, "sentence_index": 0, "correct_answer": "多时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我只等了多时，他就来了。", "explanation": "这里应该用〈一会儿〉。多时指很长的时间，与“只”表示时间很短相矛盾。"}, {"text": "他多时就明白了我的意思。", "explanation": "这里应该用〈一下子〉。多时指很长的时间，与“就”表示很快完成的语气相矛盾。"}, {"text": "车多时就要开了，快上车。", "explanation": "这里应该用〈马上〉。多时指很长的时间，与“就要”表示即将发生的语气相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86028, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "凌晨", "is_correct": false, "explanation": "搭配：“凌晨”是时点，不能作“关门”的时段，“关门凌晨了”不成说法。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指将来的时间，与“已经关门”的事实相冲突。"}, {"text": "多时", "is_correct": true, "explanation": "多时：表示很长的时间，与“关门……了”和“你还不知道吗”的语境相合。"}, {"text": "一瞬", "is_correct": false, "explanation": "语义：“一瞬”指刹那，与“你还不知道吗”所表达的久已如此的语境不合。"}], "explanations": {"凌晨": "搭配：“凌晨”是时点，不能作“关门”的时段，“关门凌晨了”不成说法。", "明天": "语义：“明天”指将来的时间，与“已经关门”的事实相冲突。", "多时": "多时：表示很长的时间，与“关门……了”和“你还不知道吗”的语境相合。", "一瞬": "语义：“一瞬”指刹那，与“你还不知道吗”所表达的久已如此的语境不合。"}, "sentence_index": 6, "correct_answer": "多时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他明天多时回来。", "explanation": "这里误把〈多时〉当作表示〈时刻〉的词用了。多时只表示很长的一段时间，不能指具体的时刻。"}, {"text": "会议下午多时开始。", "explanation": "这里误把〈多时〉当作表示〈时刻〉的词用了。多时只表示很长的一段时间，不能指具体的时刻。"}, {"text": "我们今天多时到达。", "explanation": "这里误把〈多时〉当作表示〈时刻〉的词用了。多时只表示很长的一段时间，不能指具体的时刻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86028, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在车站等了很多时，车才到。", "corrected_sentence": "我们在车站等了多时，车才到。", "error_description": "“多时”本身已表示很长的时间，前面不能再加“很”。应说“等了多时”，不说“等了很多时”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86028, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只小猫叫多时，现在才停下。", "corrected_sentence": "那只小猫叫了多时，现在才停下。", "error_description": "漏掉动态助词：单音节动词“叫”后面要加“了”，应说“叫了多时”，不说“叫多时”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
