INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86029, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“那个”是指离我们远一点的那一个人或东西。", "primary_collocate": null, "pronunciation": "nà ge", "ipa": "na⁵¹ kɤ⁰", "syllable_count": 2, "sentences": [{"text": "你要这个还是那个？", "target_word": "那个", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那个女孩是我的同学。", "target_word": "那个", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "河对面的那个房子很大。", "target_word": "那个", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个红色的包是我妈妈的。", "target_word": "那个", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前面走路的那个人是谁？", "target_word": "那个", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想买那个，不想买这个。", "target_word": "那个", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个老人每天都在公园里走路。", "target_word": "那个", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你把那个拿过来。", "target_word": "那个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个地方的饭菜很好吃。", "target_word": "那个", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他手里拿着的那个是什么？", "target_word": "那个", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "那些", "label": "复数"}], "register": "口语", "sense_fingerprint": "指离我们远一点的那一个人或东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53b78f9d-f217-4af1-8d7e-8b11ddac9746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86029, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "那个", "is_correct": true, "explanation": "目标词，nà ge，指离我们远一点的那一个人或东西。"}, {"text": "哪个", "is_correct": false, "explanation": "哪个 nǎge 与 那个 nàge 第一个音节声调不同（三声与四声），意思是“哪一个”，是疑问代词。"}, {"text": "那么", "is_correct": false, "explanation": "那么 nàme 与 那个 nàge 第二个音节声母不同（m 与 g），意思是“那样、那么”，不是指示代词。"}, {"text": "那棵", "is_correct": false, "explanation": "那棵 nàkē 与 那个 nàge 第二个音节声母不同（k 与 g）且声调不同，是“那”加量词“棵”的短语，意思是“那一棵（树）”。"}], "explanations": {"那个": "目标词，nà ge，指离我们远一点的那一个人或东西。", "哪个": "哪个 nǎge 与 那个 nàge 第一个音节声调不同（三声与四声），意思是“哪一个”，是疑问代词。", "那么": "那么 nàme 与 那个 nàge 第二个音节声母不同（m 与 g），意思是“那样、那么”，不是指示代词。", "那棵": "那棵 nàkē 与 那个 nàge 第二个音节声母不同（k 与 g）且声调不同，是“那”加量词“棵”的短语，意思是“那一棵（树）”。"}, "sentence_index": null, "correct_answer": "那个"}, "level_3": {"options": [{"text": "那个", "is_correct": true, "explanation": "与“这个”构成二选一的远近对比，“你要这个还是那个”。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”指人，这里是在两件东西之间选择。"}, {"text": "大家", "is_correct": false, "explanation": "语义：“大家”指人群，与两件物品的选择不符。"}, {"text": "每个", "is_correct": false, "explanation": "搭配：“每个”表示逐一、全体，不能与“还是”构成二选一。"}], "explanations": {"那个": "与“这个”构成二选一的远近对比，“你要这个还是那个”。", "谁": "语义：“谁”指人，这里是在两件东西之间选择。", "大家": "语义：“大家”指人群，与两件物品的选择不符。", "每个": "搭配：“每个”表示逐一、全体，不能与“还是”构成二选一。"}, "sentence_index": 0, "correct_answer": "那个"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你看，那个本子就在我手边。", "explanation": "“那个”指离说话人较远的事物；本子就在手边，这里应用〈这个〉。"}, {"text": "我手里拿着的那个东西，你看，就是这个。", "explanation": "东西就在说话人手里，应用〈这个〉指近处，不该先用“那个”。"}, {"text": "我现在穿的那个衣服是新买的。", "explanation": "衣服就穿在说话人身上，应说〈这件〉，不用“那个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86029, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "那个", "is_correct": true, "explanation": "指一位确定的老人，与“每天都在公园里走路”的具体描述相符。"}, {"text": "哪个", "is_correct": false, "explanation": "语义：“哪个”是疑问代词，陈述句中不能指一位确定的老人。"}, {"text": "什么", "is_correct": false, "explanation": "语义：“什么”用于问事物的性质，这里说的是老人，不能这样用。"}, {"text": "任何", "is_correct": false, "explanation": "搭配：“任何”表示任一，不能与“每天都在公园里走路”所指的具体老人搭配。"}], "explanations": {"那个": "指一位确定的老人，与“每天都在公园里走路”的具体描述相符。", "哪个": "语义：“哪个”是疑问代词，陈述句中不能指一位确定的老人。", "什么": "语义：“什么”用于问事物的性质，这里说的是老人，不能这样用。", "任何": "搭配：“任何”表示任一，不能与“每天都在公园里走路”所指的具体老人搭配。"}, "sentence_index": 6, "correct_answer": "那个"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我正在吃的那个苹果，就在我嘴边。", "explanation": "苹果就在说话人嘴边，指近处应用〈这个〉。"}, {"text": "那个都很便宜，你随便买吧。", "explanation": "“那个”只指一个；“都”指多样东西，这里应用〈那些〉。"}, {"text": "那个们都是我的朋友。", "explanation": "“那个”不能加“们”表示复数，应用〈那些〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86029, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个本书很好看。", "corrected_sentence": "那本书很好看。", "error_description": "“那个”已经带量词“个”，后面不能再加量词“本”，应说“那本书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86029, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个的孩子很聪明。", "corrected_sentence": "那个孩子很聪明。", "error_description": "“那个”后直接接名词时不加“的”，应说“那个孩子”；“那个的孩子”是错误的，“的”不能加在指示代词“那个”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
