INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86030, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指示代词，指较远的某个人或事物。", "primary_collocate": null, "pronunciation": "nà ge", "ipa": "na⁵¹ kɤ⁰", "syllable_count": 2, "sentences": [{"text": "这个是我的，那个是你的。", "target_word": "那个", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个人是我们的新老师。", "target_word": "那个", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你看，那个孩子在哭。", "target_word": "那个", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "桌子上的那个杯子是谁的？", "target_word": "那个", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不喜欢这个，我要那个。", "target_word": "那个", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个商店离我家很近。", "target_word": "那个", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把那个给我，谢谢。", "target_word": "那个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站在门口的那个人是谁？", "target_word": "那个", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个电影我已经看过了。", "target_word": "那个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "左边是我哥哥，右边那个是我弟弟。", "target_word": "那个", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "那些", "label": "复数"}], "register": "口语", "sense_fingerprint": "指示代词：指离说话人较远的人或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53b78f9d-f217-4af1-8d7e-8b11ddac9746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86030, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "那个", "is_correct": true, "explanation": "目标词，nà ge，指离说话人较远的人或事物。"}, {"text": "哪个", "is_correct": false, "explanation": "哪个 nǎge 与 那个 nàge 第一个音节声调不同（三声与四声），意思是“哪一个”，是疑问代词。"}, {"text": "那么", "is_correct": false, "explanation": "那么 nàme 与 那个 nàge 第二个音节声母不同（m 与 g），意思是“那样、那么”，不是指示代词。"}, {"text": "那棵", "is_correct": false, "explanation": "那棵 nàkē 与 那个 nàge 第二个音节声母不同（k 与 g）且声调不同，是“那”加量词“棵”的短语，意思是“那一棵（树）”。"}], "explanations": {"那个": "目标词，nà ge，指离说话人较远的人或事物。", "哪个": "哪个 nǎge 与 那个 nàge 第一个音节声调不同（三声与四声），意思是“哪一个”，是疑问代词。", "那么": "那么 nàme 与 那个 nàge 第二个音节声母不同（m 与 g），意思是“那样、那么”，不是指示代词。", "那棵": "那棵 nàkē 与 那个 nàge 第二个音节声母不同（k 与 g）且声调不同，是“那”加量词“棵”的短语，意思是“那一棵（树）”。"}, "sentence_index": null, "correct_answer": "那个"}, "level_3": {"options": [{"text": "那个", "is_correct": true, "explanation": "只有“那个”能与“这个”形成远近对比，构成“这个是我的，那个是你的”。"}, {"text": "了", "is_correct": false, "explanation": "语法：“了”是助词，不能作“是”的主语，句子不成立。"}, {"text": "哪个", "is_correct": false, "explanation": "语义：“哪个”是疑问代词，陈述句中不能这样用，“哪个是你的”是问句。"}, {"text": "每个", "is_correct": false, "explanation": "搭配：“每个”表示逐一、全体，与“这个是我的”的单独所指不搭配。"}], "explanations": {"那个": "只有“那个”能与“这个”形成远近对比，构成“这个是我的，那个是你的”。", "了": "语法：“了”是助词，不能作“是”的主语，句子不成立。", "哪个": "语义：“哪个”是疑问代词，陈述句中不能这样用，“哪个是你的”是问句。", "每个": "搭配：“每个”表示逐一、全体，与“这个是我的”的单独所指不搭配。"}, "sentence_index": 0, "correct_answer": "那个"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你看，那个杯子就在我手边。", "explanation": "“那个”指离说话人较远的事物；杯子就在手边，这里应用〈这个〉。"}, {"text": "我身上穿的那个衣服是新的。", "explanation": "衣服就穿在说话人身上，应说〈这件〉，不用“那个”。"}, {"text": "那个们都是我的同学。", "explanation": "“那个”不能加“们”表示复数，应用〈那些〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86030, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "那个", "is_correct": true, "explanation": "指已经指定的那一个东西，与“请把……给我”的具体所指相符。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”指人，这里要的是物件。"}, {"text": "某个", "is_correct": false, "explanation": "语义：“某个”表示不确定的一个，这里说话人要的是已指定的那一个。"}, {"text": "大家", "is_correct": false, "explanation": "搭配：“把……给我”要求具体事物作宾语，“大家”不能作被“给”的对象。"}], "explanations": {"那个": "指已经指定的那一个东西，与“请把……给我”的具体所指相符。", "谁": "语义：“谁”指人，这里要的是物件。", "某个": "语义：“某个”表示不确定的一个，这里说话人要的是已指定的那一个。", "大家": "搭配：“把……给我”要求具体事物作宾语，“大家”不能作被“给”的对象。"}, "sentence_index": 6, "correct_answer": "那个"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我手里的那个手机，你看，就是这个。", "explanation": "手机就在说话人手里，指近处应用〈这个〉。"}, {"text": "那个都很好吃，你多尝尝吧。", "explanation": "“那个”只指一个；“都”指多样东西，这里应用〈那些〉。"}, {"text": "那个手很疼，你快看看。", "explanation": "“那个”不能用于手，“手”要用量词〈只〉，应说“那只手”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86030, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个的小男孩在门口等你。", "corrected_sentence": "那个小男孩在门口等你。", "error_description": "“那个”后面不能直接加“的”，应说“那个小男孩”，“的”多余。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86030, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个的苹果很甜，那个香蕉也很甜。", "corrected_sentence": "那个苹果很甜，那个香蕉也很甜。", "error_description": "“那个”是指示词，后面不能直接加“的”，应说“那个苹果”，“的”多余。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
