INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86031, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“一切”是说全部的东西，一样也不少。", "primary_collocate": null, "pronunciation": "yí qiè", "ipa": "i˧˥ tɕʰjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "他把一切都带来了。", "target_word": "一切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火灾把房子里的一切都烧光了。", "target_word": "一切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的一切我都很喜欢。", "target_word": "一切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家的时候，他把一切都装进了箱子。", "target_word": "一切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他卖掉了房子和车，还有一切值钱的东西。", "target_word": "一切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子要的一切，妈妈都给他买了。", "target_word": "一切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的一切东西都很便宜。", "target_word": "一切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗把桌上的一切都推到了地上。", "target_word": "一切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前，请检查你带的一切。", "target_word": "一切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你需要的一切，这里都有。", "target_word": "一切", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一切｜代词｜全部的东西，一样也不少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '683cea7f-9faf-4ce5-be29-922b841282d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86031, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一切", "is_correct": true, "explanation": "正确：“一切”指全部的东西，作“把”的宾语，与“都带来了”的总括相合。"}, {"text": "一起", "is_correct": false, "explanation": "词性：“一起”是副词，不能作“把”的宾语。"}, {"text": "任何", "is_correct": false, "explanation": "搭配：“任何”须修饰名词，不能单独作“把”的宾语。"}, {"text": "非常", "is_correct": false, "explanation": "词性：“非常”是副词，只能修饰形容词或动词，不能作“把”的宾语。"}], "explanations": {"一切": "正确：“一切”指全部的东西，作“把”的宾语，与“都带来了”的总括相合。", "一起": "词性：“一起”是副词，不能作“把”的宾语。", "任何": "搭配：“任何”须修饰名词，不能单独作“把”的宾语。", "非常": "词性：“非常”是副词，只能修饰形容词或动词，不能作“把”的宾语。"}, "sentence_index": 0, "correct_answer": "一切"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子一切的假期都在家玩玩具。", "explanation": "这里应该用〈整个〉。“一切”指事物或情况，不修饰整段时间，应说“整个假期”。"}, {"text": "饭好了，一切都围坐在桌前。", "explanation": "这里应该用〈大家〉。“一切”指事物或情况，不能指人“围坐”，指人应说“大家”。"}, {"text": "他一切地把衣服装进了箱子。", "explanation": "这里应该用〈仔细〉。“一切”不能作状语修饰动作的方式，应说“仔细地”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86031, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一切", "is_correct": true, "explanation": "正确：“一切”概括这家店的全部东西，与“都很便宜”的总括语气相合。"}, {"text": "大家", "is_correct": false, "explanation": "搭配：“大家”指人，不能修饰“东西”。"}, {"text": "自己", "is_correct": false, "explanation": "语义：“自己”指本人，与“这家店”的所属关系不合。"}, {"text": "他们", "is_correct": false, "explanation": "搭配：“他们”是人称代词，不能用来修饰“东西”。"}], "explanations": {"一切": "正确：“一切”概括这家店的全部东西，与“都很便宜”的总括语气相合。", "大家": "搭配：“大家”指人，不能修饰“东西”。", "自己": "语义：“自己”指本人，与“这家店”的所属关系不合。", "他们": "搭配：“他们”是人称代词，不能用来修饰“东西”。"}, "sentence_index": 6, "correct_answer": "一切"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我一切周末都在家里看书。", "explanation": "这里应该用〈整个〉。“一切”不修饰时间词，表示整段时间应说“整个周末”。"}, {"text": "老师一切的学生都去图书馆看书。", "explanation": "这里应该用〈全体〉。说某位老师所带的整群学生时，应说“老师的全体学生”；“一切”不这样放在“老师”后面修饰“学生”。"}, {"text": "饭后，一切都去散步了。", "explanation": "这里应该用〈大伙〉。“一切”指事物，不能指人作主语去“散步”，指人应说“大伙”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86031, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把一切的收拾好了，准备出发。", "corrected_sentence": "他把一切都收拾好了，准备出发。", "error_description": "错误：“的”用在了“一切”与动词之间。正确：“都”须紧跟“一切”，总括前面的宾语，即“把一切都收拾好了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86031, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把一切个都交给了朋友。", "corrected_sentence": "他把一切都交给了朋友。", "error_description": "错误：“一切”指全部的东西，不能再加量词“个”。正确：删去“个”，说“把一切都交给了朋友”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
