INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86032, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86032, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "代词，指全部的事物或情况。", "primary_collocate": null, "pronunciation": "yī qiè", "ipa": "i˥ tɕʰjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "只要你努力，一切都会好起来。", "target_word": "一切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个消息，他忘了一切。", "target_word": "一切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过这次考试，一切都变了。", "target_word": "一切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请放心，一切都在我们的计划中。", "target_word": "一切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一切顺利，我们明天就能到。", "target_word": "一切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了孩子，愿意放弃一切。", "target_word": "一切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了新的城市，一切都要重新开始。", "target_word": "一切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一切问题都有办法解决。", "target_word": "一切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说手术很成功，一切正常。", "target_word": "一切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着说：“放心吧，一切交给我。”", "target_word": "一切", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一切｜代词｜指全部的事物或情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '683cea7f-9faf-4ce5-be29-922b841282d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86032, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一切", "is_correct": true, "explanation": "正确：“一切”指全部的事情，作句子主语，“都”总括它，与“只要你努力”的条件相合。"}, {"text": "别人", "is_correct": false, "explanation": "语义：“都会好起来”的结果应落在努力的“你”身上，“别人”指他人，与“你努力”的因果关系不符。"}, {"text": "东西", "is_correct": false, "explanation": "语义：“东西”指物件，物件不会“好起来”，与“只要你努力”的因果关系不符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不受“你努力”影响，与“只要你努力”的因果关系不符。"}], "explanations": {"一切": "正确：“一切”指全部的事情，作句子主语，“都”总括它，与“只要你努力”的条件相合。", "别人": "语义：“都会好起来”的结果应落在努力的“你”身上，“别人”指他人，与“你努力”的因果关系不符。", "东西": "语义：“东西”指物件，物件不会“好起来”，与“只要你努力”的因果关系不符。", "天气": "语义：“天气”不受“你努力”影响，与“只要你努力”的因果关系不符。"}, "sentence_index": 0, "correct_answer": "一切"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一切天都要跑步。", "explanation": "这里应该用〈每〉。“一切”指全部事物，不表示每天重复的动作，应说“每天都要跑步”。"}, {"text": "我们一切去台上唱歌吧。", "explanation": "这里应该用〈一起〉。“一切”是代词，不能作状语表示“共同”，应说“一起”。"}, {"text": "他每天都一切地完成作业。", "explanation": "这里应该用〈认真〉。“一切”不能作状语修饰动作的方式，应说“认真地完成作业”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86032, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一切", "is_correct": true, "explanation": "正确：“一切”概括新城市里的所有事情，与“都要重新开始”相合。"}, {"text": "那个", "is_correct": false, "explanation": "搭配：“那个”指单个事物，不能与表示总括的“都”搭配。"}, {"text": "任何", "is_correct": false, "explanation": "搭配：“任何”须修饰名词，不能单独作“都要重新开始”的主语。"}, {"text": "某人", "is_correct": false, "explanation": "语义：“某人”指不确定的一个人，与“到了新的城市”这一整体情境不合。"}], "explanations": {"一切": "正确：“一切”概括新城市里的所有事情，与“都要重新开始”相合。", "那个": "搭配：“那个”指单个事物，不能与表示总括的“都”搭配。", "任何": "搭配：“任何”须修饰名词，不能单独作“都要重新开始”的主语。", "某人": "语义：“某人”指不确定的一个人，与“到了新的城市”这一整体情境不合。"}, "sentence_index": 6, "correct_answer": "一切"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我一切假期都在家里看书。", "explanation": "这里应该用〈整个〉。“一切”不修饰时间词，表示整段时间应说“整个假期”。"}, {"text": "老师一切学生都去图书馆看书。", "explanation": "这里应该用〈全体〉。说某位老师所带的整群学生时，应说“老师的全体学生”；“一切”不这样直接放在“老师”后面修饰“学生”。"}, {"text": "晚会结束后，一切都回家了。", "explanation": "这里应该用〈大伙〉。“一切”指事物，不能指人作主语“回家”，指人应说“大伙”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86032, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会议结束后，一切把安排好了。", "corrected_sentence": "会议结束后，一切都安排好了。", "error_description": "错误：“把”用在了“一切”之后、动词之前，但“把”字句需要宾语紧跟“把”之后，此处“把”之后没有宾语。正确：“一切”作主语时，“都”应紧跟其后，即“一切都安排好了”，“都”用来总括前面的主语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86032, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他被一切都告诉了我。", "corrected_sentence": "他把一切都告诉了我。", "error_description": "错误：“被”用在了本应使用“把”的位置。“一切”是“告诉”的受事，应用“把”将其提到动词前，即“把一切都告诉了我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
