INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86035, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "用于“不管/无论……多么……，都……”的让步句中，表示不论程度有多高。", "primary_collocate": null, "pronunciation": "duō me", "ipa": "tuɔ˥ mɤ", "syllable_count": 2, "sentences": [{"text": "不管路多么远，我都要去。", "target_word": "多么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无论多么忙，他每天都读书。", "target_word": "多么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不管天气多么冷，他都跑步。", "target_word": "多么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无论工作多么累，她都很开心。", "target_word": "多么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不管多么难，我们也不放弃。", "target_word": "多么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不管这座楼多么高，我都要爬上去。", "target_word": "多么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无论多么大的雨，比赛都要开始。", "target_word": "多么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不管多么晚回家，都会给我打电话。", "target_word": "多么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不管问题多么小，都要问老师。", "target_word": "多么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无论多么好吃的菜，天天吃也会吃腻。", "target_word": "多么", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "多麼", "label": "繁体"}], "register": "中性", "sense_fingerprint": "多么：用于无论/不管句，表示不论程度多高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5929168-3d77-4b29-8202-61f2e45ccbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86035, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多么", "is_correct": true, "explanation": "正确。“不管……都”的让步结构要用“多么”引出程度。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“不管……都”的让步结构中不能用“很”。"}, {"text": "最", "is_correct": false, "explanation": "语义：“最”表示最高程度，不能表示“无论程度多高”的让步。"}, {"text": "太", "is_correct": false, "explanation": "语义：“太”表示超过适度，与“不管……都”的让步意思不符。"}], "explanations": {"多么": "正确。“不管……都”的让步结构要用“多么”引出程度。", "很": "搭配：“不管……都”的让步结构中不能用“很”。", "最": "语义：“最”表示最高程度，不能表示“无论程度多高”的让步。", "太": "语义：“太”表示超过适度，与“不管……都”的让步意思不符。"}, "sentence_index": 0, "correct_answer": "多么"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你买了多么书？", "explanation": "这里应该用〈多少〉。多么表示程度，问数量要用“多少”。"}, {"text": "你今年多么大了？", "explanation": "“多么”不用于问年龄，问年龄应说“多大”。"}, {"text": "他读书读了多么久？", "explanation": "这里应该用〈多久〉。多么表示程度，问时间长短要用“多久”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf63402e-b0a6-4bb5-92d4-c4b877c967f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86035, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多么", "is_correct": true, "explanation": "正确。“无论……”的让步结构要用“多么”引出程度。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“无论……”的让步结构中不能用“非常”。"}, {"text": "更", "is_correct": false, "explanation": "语义：“更”表示比较，与“无论……都”的让步意思不符。"}, {"text": "特别", "is_correct": false, "explanation": "语义：“特别”表示特殊，与程度让步的意思不符。"}], "explanations": {"多么": "正确。“无论……”的让步结构要用“多么”引出程度。", "非常": "搭配：“无论……”的让步结构中不能用“非常”。", "更": "语义：“更”表示比较，与“无论……都”的让步意思不符。", "特别": "语义：“特别”表示特殊，与程度让步的意思不符。"}, "sentence_index": 6, "correct_answer": "多么"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是多么来学校的？", "explanation": "这里应该用〈怎么〉。多么只表示程度，问方式要用“怎么”。"}, {"text": "我们的班长多么高？", "explanation": "“多么”不用于问身高，问高矮应说“多高”。"}, {"text": "这件衣服多么钱？", "explanation": "这里应该用〈多少〉。多么表示程度，问价钱要用“多少”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf63402e-b0a6-4bb5-92d4-c4b877c967f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86035, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "不管雨多么很大，我们都要去学校。", "corrected_sentence": "不管雨多么大，我们都要去学校。", "error_description": "错误形式是“多么很大”，正确形式是“多么大”。“多么”已表示程度很高，不能再与“很”同用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf63402e-b0a6-4bb5-92d4-c4b877c967f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86035, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "无论题目多么很难，他都会去做。", "corrected_sentence": "无论题目多么难，他都会去做。", "error_description": "错误形式是“多么很难”，正确形式是“多么难”。“多么”已表示程度很高，不能再与“很”同用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf63402e-b0a6-4bb5-92d4-c4b877c967f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
