INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86037, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "“人口”是一个地方住着的所有的人。", "primary_collocate": null, "pronunciation": "rén kǒu", "ipa": "ʐən˧˥ kʰoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个小城市的人口不多。", "target_word": "人口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里人口很多，街上总是很热闹。", "target_word": "人口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村子的人口越来越少。", "target_word": "人口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大城市的人口常常很多。", "target_word": "人口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个岛上人口很少，只有一家商店。", "target_word": "人口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里人口少，晚上很安静。", "target_word": "人口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方人口多，所以学校也多。", "target_word": "人口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇的人口里，老人最多。", "target_word": "人口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城里的人口多，路上车也多。", "target_word": "人口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为人口少，这里的车不太多。", "target_word": "人口", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人口数", "label": "复合"}, {"form": "人口普查", "label": "复合"}, {"form": "流动人口", "label": "复合"}], "register": "中性", "sense_fingerprint": "一个地方住着的全部居民", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a266faf8-e42e-483b-9de3-08d044cde7d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86037, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "房价", "is_correct": false, "explanation": "搭配：“房价”用“高／低”来描述，不说“不多”。"}, {"text": "理想", "is_correct": false, "explanation": "语义：城市没有“理想”，“这个小城市的理想不多”说不通。"}, {"text": "人口", "is_correct": true, "explanation": "正确。“人口”指一个地方居住的全部居民，可以说“人口不多”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：城市不谈“年龄不多”，与“这个小城市”的语境不合。"}], "explanations": {"房价": "搭配：“房价”用“高／低”来描述，不说“不多”。", "理想": "语义：城市没有“理想”，“这个小城市的理想不多”说不通。", "人口": "正确。“人口”指一个地方居住的全部居民，可以说“人口不多”。", "年龄": "语义：城市不谈“年龄不多”，与“这个小城市”的语境不合。"}, "sentence_index": 0, "correct_answer": "人口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个班的人口有三十人。", "explanation": "这里应该用〈人数〉。“人口”指一个地区住着的全部居民，班级里的人要用“人数”。"}, {"text": "这个景点每年有一百万人口。", "explanation": "这里应该用〈游客〉。“人口”指一个地区住着的全部居民，来景点参观的人要用“游客”。"}, {"text": "公园里的人口很多，大家都在散步。", "explanation": "这里应该用〈游人〉。“人口”指一个地方住着的全部居民，来公园玩的人要用“游人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86037, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气不能用“多”来比较数量，“天气多，所以学校也多”没有意义。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色多”和“学校也多”之间没有因果关系，句子说不通。"}, {"text": "人口", "is_correct": true, "explanation": "正确。“人口多”说明地方居民多，“所以学校也多”因果关系通顺。"}, {"text": "海拔", "is_correct": false, "explanation": "搭配：“海拔”用“高／低”来描述，不说“多”。"}], "explanations": {"天气": "语义：天气不能用“多”来比较数量，“天气多，所以学校也多”没有意义。", "颜色": "语义：“颜色多”和“学校也多”之间没有因果关系，句子说不通。", "人口": "正确。“人口多”说明地方居民多，“所以学校也多”因果关系通顺。", "海拔": "搭配：“海拔”用“高／低”来描述，不说“多”。"}, "sentence_index": 6, "correct_answer": "人口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "剧场里的人口很多，座位都坐满了。", "explanation": "这里应该用〈观众〉。“人口”指一个地区的全部居民，看演出的人要用“观众”。"}, {"text": "这次会议的人口都已经到齐了。", "explanation": "这里应该用〈人员〉。“人口”指地区居民总数，参加会议的人要用“人员”。"}, {"text": "车上的人口很多，大家都站着。", "explanation": "这里应该用〈乘客〉。“人口”不指车里的人，乘车的人要用“乘客”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86037, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市有三百万个人口。", "corrected_sentence": "这个城市有三百万人口。", "error_description": "错误：“人口”前不能用量词“个”，应说“三百万人口”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86037, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小镇的人口跟去年少了不少。", "corrected_sentence": "这个小镇的人口比去年少了不少。", "error_description": "错误：表示比较的介词应是“比”，不能用“跟”。“比去年少了不少”是正确说法，“跟去年”不能直接表示比较。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
