INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86038, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个国家或地区内居住的人的总数。", "primary_collocate": null, "pronunciation": "rén kǒu", "ipa": "ʐən˧˥ kʰoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "中国的人口有十四亿多。", "target_word": "人口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的人口每年都在增加。", "target_word": "人口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界人口已经超过八十亿。", "target_word": "人口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区的人口比去年少了一些。", "target_word": "人口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日本的人口越来越少。", "target_word": "人口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们查一查各国的人口。", "target_word": "人口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家人口最多的城市是哪个？", "target_word": "人口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们国家的人口有多少？", "target_word": "人口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张表写着每个地区的人口。", "target_word": "人口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "印度的人口和中国差不多。", "target_word": "人口", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人口数", "label": "复合"}, {"form": "人口普查", "label": "复合"}, {"form": "流动人口", "label": "复合"}], "register": "中性", "sense_fingerprint": "国家或地区居民的总数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a266faf8-e42e-483b-9de3-08d044cde7d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86038, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "面积", "is_correct": false, "explanation": "语义：“面积”是土地大小，不以“亿”人计，“中国的面积有十四亿多”说不通。"}, {"text": "语言", "is_correct": false, "explanation": "语义：“语言”不能按人数说“有十四亿多”，句子没有意义。"}, {"text": "人口", "is_correct": true, "explanation": "正确。“人口”指一个国家的居民总数，可以说“中国的人口有十四亿多”。"}, {"text": "城市", "is_correct": false, "explanation": "搭配：“十四亿多”是对人的计数，不能用来计算“城市”的数量。"}], "explanations": {"面积": "语义：“面积”是土地大小，不以“亿”人计，“中国的面积有十四亿多”说不通。", "语言": "语义：“语言”不能按人数说“有十四亿多”，句子没有意义。", "人口": "正确。“人口”指一个国家的居民总数，可以说“中国的人口有十四亿多”。", "城市": "搭配：“十四亿多”是对人的计数，不能用来计算“城市”的数量。"}, "sentence_index": 0, "correct_answer": "人口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的人口有三千人。", "explanation": "这里应该用〈员工〉。“人口”指国家或地区的居民总数，公司里的人要用“员工”。"}, {"text": "这辆公共汽车的人口有五十人。", "explanation": "这里应该用〈乘客〉。“人口”指国家或地区的居民总数，坐车的人要用“乘客”。"}, {"text": "这家医院的人口很多，医生很忙。", "explanation": "这里应该用〈病人〉。“人口”指一个国家或地区的居民总数，医院里看病的人要用“病人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86038, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气不能比较“最多”，“天气最多的城市”没有意义。"}, {"text": "房价", "is_correct": false, "explanation": "搭配：“房价”用“高／低”来描述，不说“最多”。"}, {"text": "人口", "is_correct": true, "explanation": "正确。“人口最多的城市”指居民最多的城市，与“这个国家”的语境相符。"}, {"text": "学费", "is_correct": false, "explanation": "搭配：“学费”用“高／低”来描述，不说“最多”。"}], "explanations": {"天气": "语义：天气不能比较“最多”，“天气最多的城市”没有意义。", "房价": "搭配：“房价”用“高／低”来描述，不说“最多”。", "人口": "正确。“人口最多的城市”指居民最多的城市，与“这个国家”的语境相符。", "学费": "搭配：“学费”用“高／低”来描述，不说“最多”。"}, "sentence_index": 6, "correct_answer": "人口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛的人口有十万人。", "explanation": "这里应该用〈观众〉。“人口”指国家或地区的居民总数，比赛现场的人要用“观众”。"}, {"text": "这次培训的人口都到了。", "explanation": "这里应该用〈学员〉。“人口”指地区居民总数，参加培训的人要用“学员”。"}, {"text": "这支球队的人口有二十五人。", "explanation": "这里应该用〈队员〉。“人口”指国家或地区的居民总数，球队里的人要用“队员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86038, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家的人口跟去年增加了不少。", "corrected_sentence": "这个国家的人口比去年增加了不少。", "error_description": "错误：表示比较的介词应用“比”，说“比去年增加了不少”，不能用“跟”。“跟”表示并列或伴随，不能直接引出比较的基准。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86038, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个地区的人口减少了过五万。", "corrected_sentence": "这个地区的人口减少了五万。", "error_description": "错误：“了”和“过”不能同时用在同一动词后，应只用“了”，说“减少了五万”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
