INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86039, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“另”是说除了前面说的，还有别的一个。", "primary_collocate": null, "pronunciation": "lìng", "ipa": "liŋ⁵¹", "syllable_count": 1, "sentences": [{"text": "我还有另一个问题想问你。", "target_word": "另", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事他还有另一个想法。", "target_word": "另", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "除了红色的，我还有另一件白色的。", "target_word": "另", "complexity_tier": "T3", "furigana": "chú le hóng sè de wǒ hái yǒu lìng yí jiàn bái sè de", "sentence_source": "generated"}, {"text": "请在另一张纸上写。", "target_word": "另", "complexity_tier": "T3", "furigana": "qǐng zài lìng yī zhāng zhǐ shàng xiě", "sentence_source": "generated"}, {"text": "这个门坏了，你从另一个门走吧。", "target_word": "另", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个不好用，我想换另一个。", "target_word": "另", "complexity_tier": "T3", "furigana": "zhè ge bù hǎo yòng wǒ xiǎng huàn lìng yí gè", "sentence_source": "generated"}, {"text": "这份是我的，另一份是你的。", "target_word": "另", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们明天不见面，改到另一天吧。", "target_word": "另", "complexity_tier": "T3", "furigana": "wǒ men míng tiān bú jiàn miàn, gǎi dào lìng yī tiān ba", "sentence_source": "generated"}, {"text": "一个人去不好，我想再找另一个朋友一起去。", "target_word": "另", "complexity_tier": "T3", "furigana": "yí gè rén qù bù hǎo, wǒ xiǎng zài zhǎo lìng yí gè péng you yì qǐ qù", "sentence_source": "generated"}, {"text": "我有两个哥哥，一个在北京，另一个在上海。", "target_word": "另", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "另外", "label": "复合"}, {"form": "另行", "label": "复合"}], "register": "中性", "sense_fingerprint": "除了前面说的，还有别的一个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53b78f9d-f217-4af1-8d7e-8b11ddac9746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86039, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "另", "is_correct": true, "explanation": "目标词，lìng，表示除了前面说的，还有别的一个。"}, {"text": "零", "is_correct": false, "explanation": "零 líng 与 另 lìng 声调不同（二声与四声），意思是“零”。"}, {"text": "领", "is_correct": false, "explanation": "领 lǐng 与 另 lìng 声调不同（三声与四声），意思是“领子、领导”。"}, {"text": "冷", "is_correct": false, "explanation": "冷 lěng 与 另 lìng 韵母不同（e 与 i），声调也不同，意思是“冷”。"}], "explanations": {"另": "目标词，lìng，表示除了前面说的，还有别的一个。", "零": "零 líng 与 另 lìng 声调不同（二声与四声），意思是“零”。", "领": "领 lǐng 与 另 lìng 声调不同（三声与四声），意思是“领子、领导”。", "冷": "冷 lěng 与 另 lìng 韵母不同（e 与 i），声调也不同，意思是“冷”。"}, "sentence_index": null, "correct_answer": "另"}, "level_3": {"options": [{"text": "另", "is_correct": true, "explanation": "“另一个问题”表示前面说的以外还有一个，与句意相符。"}, {"text": "每", "is_correct": false, "explanation": "语义：“每一个问题”表示全体，与“还有……一个”矛盾。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”不能修饰数量词“一个”。"}, {"text": "太", "is_correct": false, "explanation": "语法：“太”不能修饰数量词“一个”。"}], "explanations": {"另": "“另一个问题”表示前面说的以外还有一个，与句意相符。", "每": "语义：“每一个问题”表示全体，与“还有……一个”矛盾。", "很": "语法：“很”不能修饰数量词“一个”。", "太": "语法：“太”不能修饰数量词“一个”。"}, "sentence_index": 0, "correct_answer": "另"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请在另张纸上写。", "explanation": "“另”后要先接“一”再接量词，应说〈另一张纸〉，不能直接接量词。"}, {"text": "请在纸另一张上写。", "explanation": "“另一张”作定语，应放在名词“纸”之前，应说〈另一张纸〉。"}, {"text": "请在另一的纸上写。", "explanation": "“另一”之后要接量词，不能用“的”，应说〈另一张纸〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86039, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "另", "is_correct": true, "explanation": "目标词，lìng，表示除了前面说的，还有别的一个。"}, {"text": "灵", "is_correct": false, "explanation": "灵 líng 与 另 lìng 声调不同，意思是“灵活、灵魂”。"}, {"text": "岭", "is_correct": false, "explanation": "岭 lǐng 与 另 lìng 声调不同，意思是“山岭”。"}, {"text": "愣", "is_correct": false, "explanation": "愣 lèng 与 另 lìng 韵母不同（e 与 i），意思是“发愣”。"}], "explanations": {"另": "目标词，lìng，表示除了前面说的，还有别的一个。", "灵": "灵 líng 与 另 lìng 声调不同，意思是“灵活、灵魂”。", "岭": "岭 lǐng 与 另 lìng 声调不同，意思是“山岭”。", "愣": "愣 lèng 与 另 lìng 韵母不同（e 与 i），意思是“发愣”。"}, "sentence_index": null, "correct_answer": "另"}, "level_3": {"options": [{"text": "另", "is_correct": true, "explanation": "“另一份”表示除了这份以外的另一份，与句意相符。"}, {"text": "只", "is_correct": false, "explanation": "语义：“只”表示仅有，与“另一份是你的”的另有对象矛盾。"}, {"text": "就", "is_correct": false, "explanation": "搭配：“就”与“这份”的对比不搭配，句子要说明另外那一份。"}, {"text": "正", "is_correct": false, "explanation": "语义：“正”表示正在，与句子的分配关系无关。"}], "explanations": {"另": "“另一份”表示除了这份以外的另一份，与句意相符。", "只": "语义：“只”表示仅有，与“另一份是你的”的另有对象矛盾。", "就": "搭配：“就”与“这份”的对比不搭配，句子要说明另外那一份。", "正": "语义：“正”表示正在，与句子的分配关系无关。"}, "sentence_index": 6, "correct_answer": "另"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今天很累，另不想去上班。", "explanation": "这里表示同样，应说〈也〉；“另”表示在已说的以外另有，不表示同样。"}, {"text": "我的书很多，你借另本吧。", "explanation": "“另”后要先接“一”再接量词，应说〈另一本〉。"}, {"text": "我只有一个妹妹，另一个妹妹在上海。", "explanation": "只有一个妹妹，就不存在“另一个”，与“另”的预设矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86039, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他另的朋友住在北京。", "corrected_sentence": "他另一个朋友住在北京。", "error_description": "这里“另”与“朋友”之间缺少数词“一个”，应说“另一个朋友”，不能直接说“另的朋友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86039, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们换另家店吧。", "corrected_sentence": "我们换另一家店吧。", "error_description": "“另”与“家”之间缺少数词“一”，应说“另一家店”，不能直接说“另家店”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
