INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86040, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示在已说的以外，相当于“另外”。", "primary_collocate": null, "pronunciation": "lìng", "ipa": "liŋ⁵¹", "syllable_count": 1, "sentences": [{"text": "这个太贵了，我们另买一个吧。", "target_word": "另", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店没有，我们另找一家。", "target_word": "另", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个办法不行，我们另想办法。", "target_word": "另", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不喜欢这份工作，想另找一份。", "target_word": "另", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事明天不行，我们另约时间。", "target_word": "另", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间太小，请你另给我们一间。", "target_word": "另", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的饭太咸，我们另做一个菜吧。", "target_word": "另", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说有事，其实另有原因。", "target_word": "另", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路不通，我们另走一条吧。", "target_word": "另", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支笔坏了，你另拿一支用吧。", "target_word": "另", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "另外", "label": "复合"}, {"form": "另行", "label": "复合"}], "register": "中性", "sense_fingerprint": "副词：在已说的以外，另行（做某事）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53b78f9d-f217-4af1-8d7e-8b11ddac9746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86040, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "另", "is_correct": true, "explanation": "目标词，lìng，副词，表示在已说的以外。"}, {"text": "零", "is_correct": false, "explanation": "零 líng 与 另 lìng 声调不同（二声与四声），意思是“零”。"}, {"text": "领", "is_correct": false, "explanation": "领 lǐng 与 另 lìng 声调不同（三声与四声），意思是“领子、领导”。"}, {"text": "冷", "is_correct": false, "explanation": "冷 lěng 与 另 lìng 韵母不同（e 与 i），声调也不同，意思是“冷”。"}], "explanations": {"另": "目标词，lìng，副词，表示在已说的以外。", "零": "零 líng 与 另 lìng 声调不同（二声与四声），意思是“零”。", "领": "领 lǐng 与 另 lìng 声调不同（三声与四声），意思是“领子、领导”。", "冷": "冷 lěng 与 另 lìng 韵母不同（e 与 i），声调也不同，意思是“冷”。"}, "sentence_index": null, "correct_answer": "另"}, "level_3": {"options": [{"text": "另", "is_correct": true, "explanation": "“另买一个”表示在已说的以外另选一个，与“太贵了”的语境相符。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”修饰形容词，不能直接修饰动词“买”。"}, {"text": "把", "is_correct": false, "explanation": "语法：“把”字句要求“把”后接宾语再接动词，“我们把买一个”不成句。"}, {"text": "被", "is_correct": false, "explanation": "语法：“被”字句需要受事与施事的结构，“我们被买一个”不成句。"}], "explanations": {"另": "“另买一个”表示在已说的以外另选一个，与“太贵了”的语境相符。", "很": "语法：“很”修饰形容词，不能直接修饰动词“买”。", "把": "语法：“把”字句要求“把”后接宾语再接动词，“我们把买一个”不成句。", "被": "语法：“被”字句需要受事与施事的结构，“我们被买一个”不成句。"}, "sentence_index": 0, "correct_answer": "另"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去年得了第一名，今年另得了第一名。", "explanation": "这里表示再次发生，应用〈又〉。“另”表示在已说的以外另外，不表示重复。"}, {"text": "我们吃完饭，另再去看电影吧。", "explanation": "“另”与“再”不能连用，应只用〈再〉。"}, {"text": "他会唱歌，我另会唱歌。", "explanation": "这里表示同样，应用〈也〉；“另”表示在已说的以外另做，不表示同样。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86040, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "另", "is_correct": true, "explanation": "目标词，lìng，副词，表示在已说的以外。"}, {"text": "灵", "is_correct": false, "explanation": "灵 líng 与 另 lìng 声调不同，意思是“灵活、灵魂”。"}, {"text": "岭", "is_correct": false, "explanation": "岭 lǐng 与 另 lìng 声调不同，意思是“山岭”。"}, {"text": "愣", "is_correct": false, "explanation": "愣 lèng 与 另 lìng 韵母不同（e 与 i），意思是“发愣”。"}], "explanations": {"另": "目标词，lìng，副词，表示在已说的以外。", "灵": "灵 líng 与 另 lìng 声调不同，意思是“灵活、灵魂”。", "岭": "岭 lǐng 与 另 lìng 声调不同，意思是“山岭”。", "愣": "愣 lèng 与 另 lìng 韵母不同（e 与 i），意思是“发愣”。"}, "sentence_index": null, "correct_answer": "另"}, "level_3": {"options": [{"text": "另", "is_correct": true, "explanation": "“另做一个菜”表示在已说的以外另做，与“饭太咸”的语境相符。"}, {"text": "太", "is_correct": false, "explanation": "语法：“太”修饰形容词，不能直接修饰动词“做”，“我们太做一个菜吧”不成句。"}, {"text": "对", "is_correct": false, "explanation": "语法：“对”是介词，后面需接对象，“我们对做一个菜吧”不成句。"}, {"text": "却", "is_correct": false, "explanation": "语义：“却”表示转折，句子前后没有转折关系。"}], "explanations": {"另": "“另做一个菜”表示在已说的以外另做，与“饭太咸”的语境相符。", "太": "语法：“太”修饰形容词，不能直接修饰动词“做”，“我们太做一个菜吧”不成句。", "对": "语法：“对”是介词，后面需接对象，“我们对做一个菜吧”不成句。", "却": "语义：“却”表示转折，句子前后没有转折关系。"}, "sentence_index": 6, "correct_answer": "另"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书我另看过了，内容很好。", "explanation": "这里应说〈已经〉。“另”表示在已说的以外另有，不表示已经做过某事。"}, {"text": "他太累了，另不想动。", "explanation": "这里应说〈也〉。“另”表示在已说的以外另有，不表示同样。"}, {"text": "他昨天来过，今天另又来了一次。", "explanation": "“另”与“又”不能连用，且“另”不表示重复，应只用〈又〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86040, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次我们约另时间吧。", "corrected_sentence": "这次我们另约时间吧。", "error_description": "“另”是副词，应放在动词“约”之前，说“另约时间”，不能放在动词后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86040, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个饭馆没开门，我们去一另家吧。", "corrected_sentence": "这个饭馆没开门，我们去另一家吧。", "error_description": "“另”与“一”的顺序颠倒，应说“另一家”，“一另家”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
