INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86041, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "少女是年纪还小、慢慢长大的女孩。", "primary_collocate": null, "pronunciation": "shào nǚ", "ipa": "ʂɑʊ˥˩ ny˨˩˦", "syllable_count": 2, "sentences": [{"text": "那个少女站在窗边看书。", "target_word": "少女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少女慢慢长大，开始喜欢写日记。", "target_word": "少女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有一位少女在拉小提琴。", "target_word": "少女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个少女十五岁，很爱唱歌。", "target_word": "少女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少女穿着白裙子，走进了教室。", "target_word": "少女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小女孩变成了少女。", "target_word": "少女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片里的少女是我的妹妹。", "target_word": "少女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少女们在树下聊天，笑得很开心。", "target_word": "少女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有个少女正在河边洗衣服。", "target_word": "少女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写的是一个少女的成长故事。", "target_word": "少女", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "少女们", "label": "复数"}, {"form": "一位少女", "label": "量词"}, {"form": "少女时代", "label": "复合"}], "register": "中性", "sense_fingerprint": "年纪还小、正在长大的女孩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd86389b0-f4c1-4e9d-ad63-6659a36e1d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86041, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "少女", "is_correct": true, "explanation": "少女：年纪还小的女孩，能站在窗边看书。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会看书，与“看书”矛盾。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：“看书”要求有生命的施事，桌子不能看书。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘不能站，也不能看书。"}], "explanations": {"少女": "少女：年纪还小的女孩，能站在窗边看书。", "石头": "语义：石头不会看书，与“看书”矛盾。", "桌子": "配价：“看书”要求有生命的施事，桌子不能看书。", "窗帘": "语义：窗帘不能站，也不能看书。"}, "sentence_index": 0, "correct_answer": "少女"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个少女今年六十岁，头发都白了。", "explanation": "这里应该用〈老太太〉。少女指年纪还小、正在长大的女孩，不能说六十岁、头发都白了的人。"}, {"text": "这个少女还要妈妈喂饭，每天都哭。", "explanation": "这里应该用〈孩子〉。少女指正在长大的年轻女孩，不能指需要妈妈喂饭的小孩。"}, {"text": "这个少女已经结婚二十年，孩子都上大学了。", "explanation": "这里应该用〈妇女〉。少女指年纪还小、正在长大的女孩，不能指结婚多年、孩子已上大学的女性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86041, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "少女", "is_correct": true, "explanation": "少女：年轻的女孩，可以是“我的妹妹”。"}, {"text": "少年", "is_correct": false, "explanation": "语义：少年是男性，不能是“我的妹妹”。"}, {"text": "叔叔", "is_correct": false, "explanation": "语义：叔叔是男性长辈，不能是“我的妹妹”。"}, {"text": "猫", "is_correct": false, "explanation": "搭配：“我的妹妹”指人，猫不能作妹妹。"}], "explanations": {"少女": "少女：年轻的女孩，可以是“我的妹妹”。", "少年": "语义：少年是男性，不能是“我的妹妹”。", "叔叔": "语义：叔叔是男性长辈，不能是“我的妹妹”。", "猫": "搭配：“我的妹妹”指人，猫不能作妹妹。"}, "sentence_index": 6, "correct_answer": "少女"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位少女已经八十岁了，每天在公园跳舞。", "explanation": "这里应该用〈老太太〉。少女指年轻的女孩，不能说八十岁的人。"}, {"text": "这位少女生了三个孩子，全家都很爱她。", "explanation": "这里应该用〈妇女〉。少女指年纪还小的女孩，不能说已经生了孩子的人。"}, {"text": "这位少女是我的邻居，已经退休了。", "explanation": "这里应该用〈阿姨〉。少女指年纪还小、正在长大的女孩，不能说已经退休的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86041, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一头少女在河边唱歌。", "corrected_sentence": "一位少女在河边唱歌。", "error_description": "量词错误：“少女”指人，应用“位”，不能用“头”（“头”用于牛、猪等动物）。正确说法是“一位少女在河边唱歌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86041, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几个少女们在树下聊天。", "corrected_sentence": "几个少女在树下聊天。", "error_description": "复数错误：“几个”这类数词后面的名词不加“们”，应说“几个少女”，“们”不能与数词连用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
