INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86042, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "年纪轻的女子，一般指十几岁的女孩。", "primary_collocate": null, "pronunciation": "shào nǚ", "ipa": "ʂɑʊ˥˩ ny˨˩˦", "syllable_count": 2, "sentences": [{"text": "十六岁的少女常常想很多事情。", "target_word": "少女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位少女走过来问我路。", "target_word": "少女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的衣服很受少女欢迎。", "target_word": "少女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个少女背着书包去上学。", "target_word": "少女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少女的头发又黑又长。", "target_word": "少女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的少女爱上了一个画家。", "target_word": "少女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几个少女在商店门口等朋友。", "target_word": "少女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她还是少女时，住在小城里。", "target_word": "少女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少女红着脸，不说话。", "target_word": "少女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在车站遇到一位少女，她在哭。", "target_word": "少女", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "少女们", "label": "复数"}, {"form": "一位少女", "label": "量词"}, {"form": "少女时代", "label": "复合"}], "register": "中性", "sense_fingerprint": "十几岁的年轻女子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd86389b0-f4c1-4e9d-ad63-6659a36e1d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86042, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "少女", "is_correct": true, "explanation": "少女：十几岁的年轻女子，符合“十六岁”的年龄。"}, {"text": "老人", "is_correct": false, "explanation": "语义：十六岁不是老人，年龄不符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会想事情，与“常常想很多事情”矛盾。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“十六岁”只修饰人，不能说“十六岁的窗户”。"}], "explanations": {"少女": "少女：十几岁的年轻女子，符合“十六岁”的年龄。", "老人": "语义：十六岁不是老人，年龄不符。", "石头": "语义：石头不会想事情，与“常常想很多事情”矛盾。", "窗户": "搭配：“十六岁”只修饰人，不能说“十六岁的窗户”。"}, "sentence_index": 0, "correct_answer": "少女"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位少女有三个孩子，每天都很忙。", "explanation": "这里应该用〈妈妈〉。少女指十几岁的年轻女子，不能说已经有三个孩子的人。"}, {"text": "那位少女今年八十岁了，身体很好。", "explanation": "这里应该用〈老太太〉。少女指十几岁的年轻女子，不能说八十岁的人。"}, {"text": "这位少女的孙子已经上小学了。", "explanation": "这里应该用〈奶奶〉。少女指十几岁的年轻女子，不能指有孙子的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86042, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "少女", "is_correct": true, "explanation": "少女：十几岁的年轻女子，能在商店门口等朋友。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会等朋友，与句意矛盾。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘不会走路，也不会在商店门口等人。"}, {"text": "电视", "is_correct": false, "explanation": "配价：“等朋友”要求有生命的施事，电视不能等人。"}], "explanations": {"少女": "少女：十几岁的年轻女子，能在商店门口等朋友。", "桌子": "语义：桌子不会等朋友，与句意矛盾。", "窗帘": "语义：窗帘不会走路，也不会在商店门口等人。", "电视": "配价：“等朋友”要求有生命的施事，电视不能等人。"}, "sentence_index": 6, "correct_answer": "少女"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位少女年纪很大，走路要拄拐杖。", "explanation": "这里应该用〈老人〉。少女指十几岁的年轻女子，不能说年纪很大的人。"}, {"text": "那位少女今年七十岁，身体很好。", "explanation": "这里应该用〈婆婆〉。少女指十几岁的年轻女子，不能说七十岁的人。"}, {"text": "少女刚学会说话，很可爱。", "explanation": "这里应该用〈宝宝〉。少女是十几岁的年轻女子，不能指刚学会说话的小孩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86042, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个少女们在车站等公交车。", "corrected_sentence": "两个少女在车站等公交车。", "error_description": "复数错误：“两个”这类数词后面的名词不加“们”，应说“两个少女”，“们”不能与数词连用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86042, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "街上走来一只少女，她很高兴。", "corrected_sentence": "街上走来一位少女，她很高兴。", "error_description": "量词错误：“少女”指人，应用“位”或“个”，不能用“只”（“只”用于动物等）。应说“一位少女”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
