INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86043, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "记者是写新闻或拍新闻的人，他们告诉大家发生了什么事。", "primary_collocate": null, "pronunciation": "jì zhě", "ipa": "tɕi⁵¹ ʈʂɤ²¹⁴", "syllable_count": 2, "sentences": [{"text": "这位记者每天写新闻。", "target_word": "记者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者问了市长三个问题。", "target_word": "记者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐是电视台的记者。", "target_word": "记者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多记者在门口等着他。", "target_word": "记者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者拿着相机去了现场。", "target_word": "记者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他长大以后想当记者。", "target_word": "记者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个记者在路边拍照片。", "target_word": "记者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者把看到的事告诉了大家。", "target_word": "记者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个女记者说话很快。", "target_word": "记者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天有一个记者要来我们学校。", "target_word": "记者", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "女记者", "label": "复合"}, {"form": "新闻记者", "label": "复合"}, {"form": "記者", "label": "繁体"}], "register": "中性", "sense_fingerprint": "写或拍新闻、告诉大家发生了什么事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53b78f9d-f217-4af1-8d7e-8b11ddac9746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86043, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "记者", "is_correct": true, "explanation": "正确答案。记者指写或拍新闻、告诉大家发生了什么事的人，读作 jì zhě。"}, {"text": "记着", "is_correct": false, "explanation": "jì zhe（轻声）与 jì zhě 第二个音节声调不同，意思是记住、记得。"}, {"text": "挤着", "is_correct": false, "explanation": "jǐ zhe 与 jì zhě 两个音节的声调都不同，意思是被挤、挤压着。"}, {"text": "集着", "is_correct": false, "explanation": "jí zhe 与 jì zhě 第一个音节声调不同，意思是聚集着。"}, {"text": "积着", "is_correct": false, "explanation": "jī zhe 与 jì zhě 第一个音节声调不同，意思是积存着、堆积着。"}], "explanations": {"记者": "正确答案。记者指写或拍新闻、告诉大家发生了什么事的人，读作 jì zhě。", "记着": "jì zhe（轻声）与 jì zhě 第二个音节声调不同，意思是记住、记得。", "挤着": "jǐ zhe 与 jì zhě 两个音节的声调都不同，意思是被挤、挤压着。", "集着": "jí zhe 与 jì zhě 第一个音节声调不同，意思是聚集着。", "积着": "jī zhe 与 jì zhě 第一个音节声调不同，意思是积存着、堆积着。"}, "sentence_index": null, "correct_answer": "记者"}, "level_3": {"options": [{"text": "记者", "is_correct": true, "explanation": "正确答案。“记者”是写新闻或拍新闻的人，符合“每天写新闻”。"}, {"text": "医生", "is_correct": false, "explanation": "语义：医生不写新闻，句子说的是写新闻的人。"}, {"text": "演员", "is_correct": false, "explanation": "语义：演员不写新闻，与“每天写新闻”的主语不符。"}, {"text": "作曲家", "is_correct": false, "explanation": "搭配：作曲家写的是乐曲，不能说“写新闻”。"}], "explanations": {"记者": "正确答案。“记者”是写新闻或拍新闻的人，符合“每天写新闻”。", "医生": "语义：医生不写新闻，句子说的是写新闻的人。", "演员": "语义：演员不写新闻，与“每天写新闻”的主语不符。", "作曲家": "搭配：作曲家写的是乐曲，不能说“写新闻”。"}, "sentence_index": 0, "correct_answer": "记者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的记者很年轻。", "explanation": "这里应该用〈作曲家〉。写歌的是作曲家，记者负责采访和报道，不能说“这首歌的记者”。"}, {"text": "这位记者每天给病人打针。", "explanation": "这里应该用〈护士〉。给病人打针是护士的工作，记者负责采访和报道。"}, {"text": "这位记者每天带游客去景点。", "explanation": "这里应该用〈导游〉。记者的工作是采访和报道新闻，带游客游览景点要用导游。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86043, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "记者", "is_correct": true, "explanation": "正确答案。记者指写或拍新闻、告诉大家发生了什么事的人，读作 jì zhě。"}, {"text": "寄着", "is_correct": false, "explanation": "jì zhe（轻声）与 jì zhě 第二个音节声调不同，意思是邮寄着。"}, {"text": "击着", "is_correct": false, "explanation": "jī zhe 与 jì zhě 第一个音节声调不同，意思是击打着。"}, {"text": "急着", "is_correct": false, "explanation": "jí zhe 与 jì zhě 第一个音节声调不同，意思是着急、急于。"}], "explanations": {"记者": "正确答案。记者指写或拍新闻、告诉大家发生了什么事的人，读作 jì zhě。", "寄着": "jì zhe（轻声）与 jì zhě 第二个音节声调不同，意思是邮寄着。", "击着": "jī zhe 与 jì zhě 第一个音节声调不同，意思是击打着。", "急着": "jí zhe 与 jì zhě 第一个音节声调不同，意思是着急、急于。"}, "sentence_index": null, "correct_answer": "记者"}, "level_3": {"options": [{"text": "记者", "is_correct": true, "explanation": "正确答案。“记者”在路边拍照片，符合句子语境。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿不会拍照片，与句意不符。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫不会拍照片，与句意不符。"}, {"text": "士子", "is_correct": false, "explanation": "语域：“士子”是文言词，日常口语和现代报道中不用。"}], "explanations": {"记者": "正确答案。“记者”在路边拍照片，符合句子语境。", "婴儿": "语义：婴儿不会拍照片，与句意不符。", "猫": "语义：猫不会拍照片，与句意不符。", "士子": "语域：“士子”是文言词，日常口语和现代报道中不用。"}, "sentence_index": 6, "correct_answer": "记者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位记者在法庭上替被告辩护。", "explanation": "这里应该用〈律师〉。在法庭上替被告辩护是律师的工作，记者负责采访和报道新闻。"}, {"text": "这位记者每天在路口指挥交通。", "explanation": "这里应该用〈交警〉。在路口指挥交通是交警的工作，记者不做这种工作。"}, {"text": "这位记者每天给病人看病。", "explanation": "这里应该用〈医生〉。记者不给病人看病，看病要用医生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86043, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天有很多记者们来采访。", "corrected_sentence": "今天有很多记者来采访。", "error_description": "错误在“记者们”。“很多”已经表示人数多，后面不能再加“们”，应说“很多记者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86043, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我姐姐是一只记者。", "corrected_sentence": "我姐姐是一位记者。", "error_description": "错误在量词“只”。“只”多用于动物或成对的物品，指人的“记者”要用量词“位”，应说“一位记者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
