INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86044, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "报刊、电台、电视台等机构中从事采访和报道新闻的人员。", "primary_collocate": null, "pronunciation": "jì zhě", "ipa": "tɕi⁵¹ ʈʂɤ²¹⁴", "syllable_count": 2, "sentences": [{"text": "他是报社的记者。", "target_word": "记者", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "电台的记者正在采访那位老人。", "target_word": "记者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家报纸的记者去了很多国家。", "target_word": "记者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者到现场报道了这次比赛。", "target_word": "记者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视台的记者问大家对新办法的看法。", "target_word": "记者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做了十年记者，去过很多地方。", "target_word": "记者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者在会议后写了一篇报道。", "target_word": "记者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报社今天派记者去山里采访。", "target_word": "记者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的记者对工作很认真。", "target_word": "记者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位记者采访过很多有名的人。", "target_word": "记者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "摄影记者", "label": "复合"}, {"form": "战地记者", "label": "复合"}, {"form": "記者", "label": "繁体"}], "register": "中性", "sense_fingerprint": "报刊、电台、电视台中采访和报道新闻的人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53b78f9d-f217-4af1-8d7e-8b11ddac9746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86044, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "记者", "is_correct": true, "explanation": "正确答案。记者指报刊、电台、电视台中采访和报道新闻的人员，读作 jì zhě。"}, {"text": "记着", "is_correct": false, "explanation": "jì zhe（轻声）与 jì zhě 第二个音节声调不同，意思是记住、记得。"}, {"text": "挤着", "is_correct": false, "explanation": "jǐ zhe 与 jì zhě 两个音节的声调都不同，意思是被挤、挤压着。"}, {"text": "集着", "is_correct": false, "explanation": "jí zhe 与 jì zhě 第一个音节声调不同，意思是聚集着。"}, {"text": "积着", "is_correct": false, "explanation": "jī zhe 与 jì zhě 第一个音节声调不同，意思是积存着、堆积着。"}], "explanations": {"记者": "正确答案。记者指报刊、电台、电视台中采访和报道新闻的人员，读作 jì zhě。", "记着": "jì zhe（轻声）与 jì zhě 第二个音节声调不同，意思是记住、记得。", "挤着": "jǐ zhe 与 jì zhě 两个音节的声调都不同，意思是被挤、挤压着。", "集着": "jí zhe 与 jì zhě 第一个音节声调不同，意思是聚集着。", "积着": "jī zhe 与 jì zhě 第一个音节声调不同，意思是积存着、堆积着。"}, "sentence_index": null, "correct_answer": "记者"}, "level_3": {"options": [{"text": "记者", "is_correct": true, "explanation": "正确答案。“记者”是报社中采访和报道新闻的人员，符合句意。"}, {"text": "学生", "is_correct": false, "explanation": "语义：报社不是学校，不会有学生。"}, {"text": "农民", "is_correct": false, "explanation": "语义：农民不在报社工作，与“报社的”搭配的身份不符。"}, {"text": "报纸", "is_correct": false, "explanation": "搭配：“是”后面接的是人，不能说“他是报纸”。"}], "explanations": {"记者": "正确答案。“记者”是报社中采访和报道新闻的人员，符合句意。", "学生": "语义：报社不是学校，不会有学生。", "农民": "语义：农民不在报社工作，与“报社的”搭配的身份不符。", "报纸": "搭配：“是”后面接的是人，不能说“他是报纸”。"}, "sentence_index": 0, "correct_answer": "记者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "记者在比赛中吹哨停止了比赛。", "explanation": "这里应该用〈裁判〉。吹哨、判罚比赛是裁判的工作，记者负责采访和报道。"}, {"text": "这位记者每天在学校给学生上数学课。", "explanation": "这里应该用〈老师〉。给学生上课是老师的工作，记者负责采访和报道新闻。"}, {"text": "记者在比赛中射门。", "explanation": "这里应该用〈球员〉。记者是采访和报道的人，不参加比赛射门，射门要用球员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86044, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "记者", "is_correct": true, "explanation": "正确答案。记者指报刊、电台、电视台中采访和报道新闻的人员，读作 jì zhě。"}, {"text": "寄着", "is_correct": false, "explanation": "jì zhe（轻声）与 jì zhě 第二个音节声调不同，意思是邮寄着。"}, {"text": "击着", "is_correct": false, "explanation": "jī zhe 与 jì zhě 第一个音节声调不同，意思是击打着。"}, {"text": "急着", "is_correct": false, "explanation": "jí zhe 与 jì zhě 第一个音节声调不同，意思是着急、急于。"}], "explanations": {"记者": "正确答案。记者指报刊、电台、电视台中采访和报道新闻的人员，读作 jì zhě。", "寄着": "jì zhe（轻声）与 jì zhě 第二个音节声调不同，意思是邮寄着。", "击着": "jī zhe 与 jì zhě 第一个音节声调不同，意思是击打着。", "急着": "jí zhe 与 jì zhě 第一个音节声调不同，意思是着急、急于。"}, "sentence_index": null, "correct_answer": "记者"}, "level_3": {"options": [{"text": "记者", "is_correct": true, "explanation": "正确答案。记者在会议后写报道，符合句意。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师一般不写会议报道，与句意不符。"}, {"text": "士子", "is_correct": false, "explanation": "语域：“士子”是文言词，不用于现代新闻报道的语境。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机通常不写会议报道，与“写了一篇报道”不符。"}], "explanations": {"记者": "正确答案。记者在会议后写报道，符合句意。", "厨师": "语义：厨师一般不写会议报道，与句意不符。", "士子": "语域：“士子”是文言词，不用于现代新闻报道的语境。", "司机": "语义：司机通常不写会议报道，与“写了一篇报道”不符。"}, "sentence_index": 6, "correct_answer": "记者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位记者设计过很多房子。", "explanation": "这里应该用〈设计师〉。记者的工作是采访和报道，设计房子要用设计师。"}, {"text": "这位记者治好过很多病人。", "explanation": "这里应该用〈医生〉。记者不给病人治病，治病要用医生。"}, {"text": "这位记者每天在厨房里做菜。", "explanation": "这里应该用〈厨师〉。在厨房做菜是厨师的工作，记者负责采访和报道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86044, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年成为一只记者。", "corrected_sentence": "他去年成为一名记者。", "error_description": "错误在量词“只”。“只”用于动物或成对的东西，指人的“记者”应用“名”或“位”，应说“一名记者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86044, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "许多记者们都来采访了那位老人。", "corrected_sentence": "许多记者都来采访了那位老人。", "error_description": "错误在“记者们”。“许多”已经表示人数多，后面不能再加“们”，应说“许多记者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
