INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86049, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "“间”用来数房间，比如一间屋子。", "primary_collocate": null, "pronunciation": "jiān", "ipa": "tɕjɛn˥", "syllable_count": 1, "sentences": [{"text": "我家有三间卧室。", "target_word": "间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间屋子又大又亮。", "target_word": "间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们订了两间房。", "target_word": "间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他租了一间小屋子。", "target_word": "间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼上有一间书房。", "target_word": "间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，哪一间是厨房？", "target_word": "间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套房子有两间卧室和一个客厅。", "target_word": "间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把那间屋子收拾得很干净。", "target_word": "间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那间屋子里住着一位老人。", "target_word": "间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间客厅很大，窗户朝南。", "target_word": "间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "間", "label": "繁体"}, {"form": "间间", "label": "重叠"}], "register": "中性", "sense_fingerprint": "量词，数房间、屋子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d8f0e7b-36d4-4a15-8847-6d6ee72c61b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86049, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "间", "is_correct": true, "explanation": "正确：jiān，量词“间”，用于房间、屋子"}, {"text": "江", "is_correct": false, "explanation": "jiāng 与 jiān 韵尾不同（-ng 与 -n），意思是江河"}, {"text": "千", "is_correct": false, "explanation": "qiān 与 jiān 声母不同（q 与 j），意思是一千"}, {"text": "减", "is_correct": false, "explanation": "jiǎn（第三声）与 jiān（第一声）声调不同，意思是减少"}, {"text": "建", "is_correct": false, "explanation": "jiàn（第四声）与 jiān 声调不同，意思是建造"}, {"text": "先", "is_correct": false, "explanation": "xiān 与 jiān 声母不同（x 与 j），意思是先后"}], "explanations": {"间": "正确：jiān，量词“间”，用于房间、屋子", "江": "jiāng 与 jiān 韵尾不同（-ng 与 -n），意思是江河", "千": "qiān 与 jiān 声母不同（q 与 j），意思是一千", "减": "jiǎn（第三声）与 jiān（第一声）声调不同，意思是减少", "建": "jiàn（第四声）与 jiān 声调不同，意思是建造", "先": "xiān 与 jiān 声母不同（x 与 j），意思是先后"}, "sentence_index": null, "correct_answer": "间"}, "level_3": {"options": [{"text": "间", "is_correct": true, "explanation": "正确：“间”用于房间，“我家有三间卧室”"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”用于桌子、纸张等平面的东西，不能数卧室"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”用于动物和成对东西中的一个，不能数卧室"}, {"text": "块", "is_correct": false, "explanation": "语义：“块”指成块的东西，不指房间"}], "explanations": {"间": "正确：“间”用于房间，“我家有三间卧室”", "张": "搭配：“张”用于桌子、纸张等平面的东西，不能数卧室", "只": "搭配：“只”用于动物和成对东西中的一个，不能数卧室", "块": "语义：“块”指成块的东西，不指房间"}, "sentence_index": 0, "correct_answer": "间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一间书。", "explanation": "这里应该用〈本〉。“间”用于房间、屋子，书要用“本”来数"}, {"text": "他买了一间裤子。", "explanation": "这里应该用〈条〉。裤子用“条”来数，“间”用于房间、屋子。"}, {"text": "河上有一间桥。", "explanation": "这里应该用〈座〉。桥用“座”来数，“间”用于房间"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc1a1d69-248a-48c6-9872-687195f3abb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86049, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "间", "is_correct": true, "explanation": "正确：jiān，量词“间”，用于房间、屋子"}, {"text": "将", "is_correct": false, "explanation": "jiāng 与 jiān 韵尾不同（-ng 与 -n），意思是将要"}, {"text": "鲜", "is_correct": false, "explanation": "xiān 与 jiān 声母不同（x 与 j），意思是新鲜"}, {"text": "剪", "is_correct": false, "explanation": "jiǎn（第三声）与 jiān（第一声）声调不同，意思是剪刀"}, {"text": "件", "is_correct": false, "explanation": "jiàn（第四声）与 jiān 声调不同，意思是件（量词）"}], "explanations": {"间": "正确：jiān，量词“间”，用于房间、屋子", "将": "jiāng 与 jiān 韵尾不同（-ng 与 -n），意思是将要", "鲜": "xiān 与 jiān 声母不同（x 与 j），意思是新鲜", "剪": "jiǎn（第三声）与 jiān（第一声）声调不同，意思是剪刀", "件": "jiàn（第四声）与 jiān 声调不同，意思是件（量词）"}, "sentence_index": null, "correct_answer": "间"}, "level_3": {"options": [{"text": "间", "is_correct": true, "explanation": "正确：“间”用于房间，“两间卧室”"}, {"text": "本", "is_correct": false, "explanation": "搭配：“本”用于书册，不能数卧室"}, {"text": "台", "is_correct": false, "explanation": "搭配：“台”用于机器等，不能数卧室"}, {"text": "座", "is_correct": false, "explanation": "语义：“座”指山、楼等大型建筑，不指房间"}], "explanations": {"间": "正确：“间”用于房间，“两间卧室”", "本": "搭配：“本”用于书册，不能数卧室", "台": "搭配：“台”用于机器等，不能数卧室", "座": "语义：“座”指山、楼等大型建筑，不指房间"}, "sentence_index": 6, "correct_answer": "间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家养了三间猫。", "explanation": "这里应该用〈只〉。“间”用于房间，猫要用“只”来数"}, {"text": "这间大楼有二十层。", "explanation": "这里应该用〈座〉。“座”用于楼、山等大型建筑，“间”只用于房间"}, {"text": "我家买了一间手机。", "explanation": "这里应该用〈部〉。手机用“部”来数，“间”用于房间"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc1a1d69-248a-48c6-9872-687195f3abb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warn