INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86052, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "由政治主张相同的人组成的政治组织。", "primary_collocate": null, "pronunciation": "dǎng", "ipa": "tɑŋ˨˩", "syllable_count": 1, "sentences": [{"text": "这个国家有三个大的党。", "target_word": "党", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这个党的主要负责人。", "target_word": "党", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个党在选举中得到了很多支持。", "target_word": "党", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党的政策对农村很重要。", "target_word": "党", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个党在会上为税收吵了起来。", "target_word": "党", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她十八岁时加入了这个党。", "target_word": "党", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个党主张提高工人的工资。", "target_word": "党", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个党的领导人今天发表了讲话。", "target_word": "党", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党和政府一起帮助受灾的人民。", "target_word": "党", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪个党赢了这次选举，还不知道。", "target_word": "党", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "黨", "label": "繁体"}, {"form": "政党", "label": "复合"}, {"form": "党员", "label": "复合"}], "register": "中性", "sense_fingerprint": "政治主张相同的人组成的政治组织，如参加选举、制定政策的政党", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2ce387-de1a-4dee-a2b5-d7f05cb692cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86052, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "党", "is_correct": true, "explanation": "党 dǎng（第三声）：由政治主张相同的人组成的政治组织。"}, {"text": "当", "is_correct": false, "explanation": "dāng（第一声）与 dǎng（第三声）声调不同，意思是担任、当作。"}, {"text": "懂", "is_correct": false, "explanation": "dǒng 与 dǎng 韵母不同（ong 与 ang），意思是明白。"}, {"text": "等", "is_correct": false, "explanation": "děng 与 dǎng 韵母不同（e 与 a），意思是等待。"}, {"text": "胆", "is_correct": false, "explanation": "dǎn 与 dǎng 韵尾不同（n 与 ng），意思是胆子。"}], "explanations": {"党": "党 dǎng（第三声）：由政治主张相同的人组成的政治组织。", "当": "dāng（第一声）与 dǎng（第三声）声调不同，意思是担任、当作。", "懂": "dǒng 与 dǎng 韵母不同（ong 与 ang），意思是明白。", "等": "děng 与 dǎng 韵母不同（e 与 a），意思是等待。", "胆": "dǎn 与 dǎng 韵尾不同（n 与 ng），意思是胆子。"}, "sentence_index": null, "correct_answer": "党"}, "level_3": {"options": [{"text": "党", "is_correct": true, "explanation": "党：政治组织，正合“国家有三个大的……”指三个主要政党。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不是政治组织，不能说国家有三个大的蛋糕。"}, {"text": "梦", "is_correct": false, "explanation": "搭配：“国家有”后接“梦”不成立，不能说国家有三个大的梦。"}, {"text": "杯子", "is_correct": false, "explanation": "语义：杯子是器具，不是国家的组成部分。"}], "explanations": {"党": "党：政治组织，正合“国家有三个大的……”指三个主要政党。", "蛋糕": "语义：蛋糕不是政治组织，不能说国家有三个大的蛋糕。", "梦": "搭配：“国家有”后接“梦”不成立，不能说国家有三个大的梦。", "杯子": "语义：杯子是器具，不是国家的组成部分。"}, "sentence_index": 0, "correct_answer": "党"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班里的同学组成了一个党，常常一起去图书馆。", "explanation": "这里应该用〈小组〉。党指政治组织，班里同学组成的群体不能叫党。"}, {"text": "我们班的党每学期都组织一次郊游。", "explanation": "这里应该用〈班级〉。党指政治组织，班级的活动不用“党”来说。"}, {"text": "我们国家有三只党。", "explanation": "这里应该用〈个〉。党是组织，量词用“个”，“只”一般用于动物，不用于政党。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86052, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "党", "is_correct": true, "explanation": "党 dǎng（第三声）：由政治主张相同的人组成的政治组织。"}, {"text": "躺", "is_correct": false, "explanation": "tǎng 与 dǎng 声母不同（t 与 d），意思是躺下。"}, {"text": "顶", "is_correct": false, "explanation": "dǐng 与 dǎng 韵母不同（ing 与 ang），意思是顶住、顶端。"}, {"text": "荡", "is_correct": false, "explanation": "dàng（第四声）与 dǎng（第三声）声调不同，意思是摇荡。"}, {"text": "朗", "is_correct": false, "explanation": "lǎng 与 dǎng 声母不同（l 与 d），意思是明朗。"}], "explanations": {"党": "党 dǎng（第三声）：由政治主张相同的人组成的政治组织。", "躺": "tǎng 与 dǎng 声母不同（t 与 d），意思是躺下。", "顶": "dǐng 与 dǎng 韵母不同（ing 与 ang），意思是顶住、顶端。", "荡": "dàng（第四声）与 dǎng（第三声）声调不同，意思是摇荡。", "朗": "lǎng 与 dǎng 声母不同（l 与 d），意思是明朗。"}, "sentence_index": null, "correct_answer": "党"}, "level_3": {"options": [{"text": "党", "is_correct": true, "explanation": "党：政治组织，正合“主张提高工人的工资”，只有组织或人能主张。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是建筑，不能主张提高工资。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是场所，不会提出政治主张。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“主张”需要能发表意见的主语，“石头”不能充当。"}], "explanations": {"党": "党：政治组织，正合“主张提高工人的工资”，只有组织或人能主张。", "房子": "语义：房子是建筑，不能主张提高工资。", "花园": "语义：花园是场所，不会提出政治主张。", "石头": "配价：“主张”需要能发表意见的主语，“石头”不能充当。"}, "sentence_index": 6, "correct_answer": "党"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末我们在家开党，邀请了很多朋友。", "explanation": "这里应该用〈派对〉。“党”是政治组织，不指聚会活动。"}, {"text": "这个党每个星期都组织比赛，成员很多。", "explanation": "这里应该用〈俱乐部〉。“党”不用于比赛、娱乐类的团体。"}, {"text": "这家党每天卖面包，生意很好。", "explanation": "这里应该用〈面包店〉。“党”是政治组织，不做买卖、不经营商品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86052, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "党们的政策对城市也很重要。", "corrected_sentence": "党的政策对城市也很重要。", "error_description": "“党”是名词，表示政治组织，后面不能加复数词尾“们”。应直接说“党的政策”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86052, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只党主张减少工人的负担。", "corrected_sentence": "这个党主张减少工人的负担。", "error_description": "量词错误：“党”表示组织，应该用量词“个”，“只”多用于动物等。应改为“这个党”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
