INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86054, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "男女相爱的感情。", "primary_collocate": null, "pronunciation": "ài qíng", "ipa": "aɪ˥˩ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这部电影讲的是一个爱情故事。", "target_word": "爱情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的爱情从大学开始。", "target_word": "爱情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人都希望得到真正的爱情。", "target_word": "爱情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她觉得爱情比钱更重要。", "target_word": "爱情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱情需要两个人一起努力。", "target_word": "爱情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌写的是男女之间的爱情。", "target_word": "爱情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的爱情故事让很多人感动。", "target_word": "爱情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，爱情和结婚不是一回事。", "target_word": "爱情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在爱情里，信任非常重要。", "target_word": "爱情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷奶奶的爱情让我很羡慕。", "target_word": "爱情", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "段", "label": "量词"}, {"form": "爱情片", "label": "复合"}, {"form": "愛情", "label": "繁体"}], "register": "中性", "sense_fingerprint": "男女之间相爱的感情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87aa3fbb-5473-40d6-85f3-a36aa4409ac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86054, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能作为电影讲述的内容，句子说不通。"}, {"text": "爱情", "is_correct": true, "explanation": "爱情：男女相爱的感情，电影讲的是一个这样的故事，与句意相符。"}, {"text": "螺丝钉", "is_correct": false, "explanation": "语义：螺丝钉是细小的零件，作为电影讲述的题材搭配别扭，句意不通。"}, {"text": "非常", "is_correct": false, "explanation": "词性：“非常”是副词，不能放在“一个”后面修饰“故事”。"}], "explanations": {"冰箱": "语义：冰箱不能作为电影讲述的内容，句子说不通。", "爱情": "爱情：男女相爱的感情，电影讲的是一个这样的故事，与句意相符。", "螺丝钉": "语义：螺丝钉是细小的零件，作为电影讲述的题材搭配别扭，句意不通。", "非常": "词性：“非常”是副词，不能放在“一个”后面修饰“故事”。"}, "sentence_index": 0, "correct_answer": "爱情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对父母有深厚的爱情，每天都陪他们吃饭。", "explanation": "这里应该用〈亲情〉。爱情指男女之间相爱的感情，对父母的感情应说亲情。"}, {"text": "他们之间有过一条很美好的爱情。", "explanation": "这里应该用〈一段〉。爱情的量词是“段”，“条”用于长条形的东西，不用于爱情。"}, {"text": "我和同学之间有很深的爱情，十年了都没变。", "explanation": "这里应该用〈友情〉。爱情专指男女相爱的感情，同学之间应说友情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86054, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "认真", "is_correct": false, "explanation": "词性：“认真”是形容词，“他们的认真故事”不成话，句子不通。"}, {"text": "停车场", "is_correct": false, "explanation": "语义：停车场是停车的场所，很难成为让很多人感动的“故事”，句意别扭。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "语义：垃圾桶是盛放垃圾的器具，很难成为让很多人感动的“故事”，句意别扭。"}, {"text": "爱情", "is_correct": true, "explanation": "爱情：男女相爱的感情，他们的爱情故事让很多人感动，与句意相符。"}], "explanations": {"认真": "词性：“认真”是形容词，“他们的认真故事”不成话，句子不通。", "停车场": "语义：停车场是停车的场所，很难成为让很多人感动的“故事”，句意别扭。", "垃圾桶": "语义：垃圾桶是盛放垃圾的器具，很难成为让很多人感动的“故事”，句意别扭。", "爱情": "爱情：男女相爱的感情，他们的爱情故事让很多人感动，与句意相符。"}, "sentence_index": 6, "correct_answer": "爱情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她对小猫有很深的爱情，常常喂它吃东西。", "explanation": "这里应该用〈爱心〉。爱情指男女之间的感情，对动物的喜爱应说爱心。"}, {"text": "她是我的爱情，每天都给我讲课。", "explanation": "这里应该用〈老师〉。爱情指男女相爱的感情，不能指职业；每天讲课的人应说“老师”。"}, {"text": "他们有过一张很长的爱情。", "explanation": "这里应该用〈一段〉。爱情的量词是“段”，“张”用于纸张、桌子等平面的东西，不用于爱情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86054, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们经历过一只很美好的爱情。", "corrected_sentence": "他们经历过一段很美好的爱情。", "error_description": "量词错误：“爱情”的量词要用“段”，说“一段爱情”；“只”是动物的量词，不能用于爱情。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86054, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们爱情很甜蜜。", "corrected_sentence": "我们的爱情很甜蜜。", "error_description": "结构错误：代词“我们”修饰抽象名词“爱情”时通常要加“的”，应说“我们的爱情”；“我们爱情”语感不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86055, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
