INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86055, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "“一般”是说很常见，没有什么特别的。", "primary_collocate": null, "pronunciation": "yì bān", "ipa": "i˥˩ pan˥", "syllable_count": 2, "sentences": [{"text": "这家店的菜很一般，没有什么特别的。", "target_word": "一般", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的成绩一般。", "target_word": "一般", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这部电影一般，不太好看。", "target_word": "一般", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的汉语水平一般。", "target_word": "一般", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那个地方的风景很一般。", "target_word": "一般", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他长得一般，但是人很好。", "target_word": "一般", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件衣服的质量只是一般。", "target_word": "一般", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我觉得这家酒店的服务非常一般。", "target_word": "一般", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他唱歌唱得很一般，不过大家都很高兴。", "target_word": "一般", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次考试的题目很一般，没有特别难的。", "target_word": "一般", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一般来说", "label": "复合"}, {"form": "一般人", "label": "复合"}], "register": "中性", "sense_fingerprint": "很常见，没有什么特别，不突出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53b78f9d-f217-4af1-8d7e-8b11ddac9746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86055, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一般", "is_correct": true, "explanation": "正确答案。一般指很常见、没有什么特别，读作 yì bān。"}, {"text": "一半", "is_correct": false, "explanation": "yí bàn 与 yì bān 两个音节的声调都不同，意思是一半。"}, {"text": "一版", "is_correct": false, "explanation": "yì bǎn 与 yì bān 第二个音节声调不同，意思是一个版本。"}, {"text": "一边", "is_correct": false, "explanation": "yì biān 与 yì bān 韵母不同（多了 i），意思是一边、同时。"}, {"text": "一瓣", "is_correct": false, "explanation": "yí bàn 与 yì bān 两个音节的声调都不同，意思是一瓣。"}], "explanations": {"一般": "正确答案。一般指很常见、没有什么特别，读作 yì bān。", "一半": "yí bàn 与 yì bān 两个音节的声调都不同，意思是一半。", "一版": "yì bǎn 与 yì bān 第二个音节声调不同，意思是一个版本。", "一边": "yì biān 与 yì bān 韵母不同（多了 i），意思是一边、同时。", "一瓣": "yí bàn 与 yì bān 两个音节的声调都不同，意思是一瓣。"}, "sentence_index": null, "correct_answer": "一般"}, "level_3": {"options": [{"text": "一般", "is_correct": true, "explanation": "正确答案。“一般”表示不突出、没有什么特别，符合“菜很……”。"}, {"text": "精彩", "is_correct": false, "explanation": "搭配：“精彩”多形容演出、比赛，不说“菜很精彩”。"}, {"text": "华丽", "is_correct": false, "explanation": "搭配：“华丽”形容装饰、辞藻，不用来形容菜的味道。"}, {"text": "高大", "is_correct": false, "explanation": "语义：菜不能“高大”，与句意不符。"}], "explanations": {"一般": "正确答案。“一般”表示不突出、没有什么特别，符合“菜很……”。", "精彩": "搭配：“精彩”多形容演出、比赛，不说“菜很精彩”。", "华丽": "搭配：“华丽”形容装饰、辞藻，不用来形容菜的味道。", "高大": "语义：菜不能“高大”，与句意不符。"}, "sentence_index": 0, "correct_answer": "一般"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他得了全国第一名，成绩很一般。", "explanation": "这里应该用〈优秀〉。得了全国第一名说明成绩很好，不能说“很一般”。"}, {"text": "这道菜特别好吃，大家都说味道很一般。", "explanation": "这里应该用〈好〉。“特别好吃”说明味道很好，与“一般”矛盾。"}, {"text": "这部电影太精彩了，我觉得它很一般。", "explanation": "这里应该用〈好看〉。“太精彩了”说明电影很好，与“一般”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86055, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "一般", "is_correct": true, "explanation": "正确答案。一般指很常见、没有什么特别，读作 yì bān。"}, {"text": "一帮", "is_correct": false, "explanation": "yì bāng 与 yì bān 第二个音节韵母不同（后鼻音 ang），意思是一群人。"}, {"text": "一板", "is_correct": false, "explanation": "yì bǎn 与 yì bān 第二个音节声调不同，意思是一块板。"}, {"text": "一盘", "is_correct": false, "explanation": "yì pán 与 yì bān 第二个音节声母（送气 p）和声调都不同，意思是一盘（东西）。"}], "explanations": {"一般": "正确答案。一般指很常见、没有什么特别，读作 yì bān。", "一帮": "yì bāng 与 yì bān 第二个音节韵母不同（后鼻音 ang），意思是一群人。", "一板": "yì bǎn 与 yì bān 第二个音节声调不同，意思是一块板。", "一盘": "yì pán 与 yì bān 第二个音节声母（送气 p）和声调都不同，意思是一盘（东西）。"}, "sentence_index": null, "correct_answer": "一般"}, "level_3": {"options": [{"text": "一般", "is_correct": true, "explanation": "正确答案。“一般”表示质量不突出，与“只是”的语气一致。"}, {"text": "优良", "is_correct": false, "explanation": "语义：“只是”表示轻描淡写，与“优良”的褒义矛盾。"}, {"text": "快速", "is_correct": false, "explanation": "搭配：“快速”形容速度，不修饰质量。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：“宽敞”形容空间，不修饰质量。"}], "explanations": {"一般": "正确答案。“一般”表示质量不突出，与“只是”的语气一致。", "优良": "语义：“只是”表示轻描淡写，与“优良”的褒义矛盾。", "快速": "搭配：“快速”形容速度，不修饰质量。", "宽敞": "搭配：“宽敞”形容空间，不修饰质量。"}, "sentence_index": 6, "correct_answer": "一般"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每次考试都是满分，学习很一般。", "explanation": "这里应该用〈好〉。每次都考满分说明学习很好，不能说“很一般”。"}, {"text": "她唱歌得了冠军，大家都说她唱得很一般。", "explanation": "这里应该用〈好〉。得了冠军说明唱得很好，与“一般”矛盾。"}, {"text": "这家饭店的菜很一般，所以每天都有很多人排队。", "explanation": "这里应该用〈好吃〉。很多人排队是因为菜好吃，“一般”与“所以”后的结果矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86055, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我觉得这部电影很的一般。", "corrected_sentence": "我觉得这部电影很一般。", "error_description": "“很”是程度副词，修饰形容词“一般”时中间不能加“的”，应说“很一般”，“的”多余。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86055, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他唱歌唱很一般。", "corrected_sentence": "他唱歌唱得很一般。", "error_description": "错误在“得”。“唱歌唱”后接补语“很一般”时要用“得”连接，应说“唱得很一般”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86056, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "特殊", "is_correct": true, "explanation": "正确答案。“一般”指普通，“特殊”指与众不同，二者是反义关系。"}, {"text": "简单", "is_correct": false, "explanation": "非反义：“简单”指不复杂，与“一般”的普通义不构成反义。"}, {"text": "漂亮", "is_correct": false, "explanation": "非反义：“漂亮”指好看，与“一般”的普通义没有对立关系。"}, {"text": "宽敞", "is_correct": false, "explanation": "非反义：“宽敞”指空间大，与“一般”没有反义关系。"}], "correct_answer": "特殊", "explanations": {"特殊": "正确答案。“一般”指普通，“特殊”指与众不同，二者是反义关系。", "简单": "非反义：“简单”指不复杂，与“一般”的普通义不构成反义。", "漂亮": "非反义：“漂亮”指好看，与“一般”的普通义没有对立关系。", "宽敞": "非反义：“宽敞”指空间大，与“一般”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86056, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "特殊", "is_correct": true, "explanation": "正确答案。“一般”指普通，“特殊”指与众不同，二者是反义关系。"}, {"text": "复杂", "is_correct": false, "explanation": "非反义：“复杂”指不简单，与“一般”的普通义没有对立关系。"}, {"text": "明亮", "is_correct": false, "explanation": "非反义：“明亮”指光线强，与“一般”没有反义关系。"}, {"text": "富裕", "is_correct": false, "explanation": "非反义：“富裕”指钱多，与“一般”的普通义没有对立关系。"}], "correct_answer": "特殊", "explanations": {"特殊": "正确答案。“一般”指普通，“特殊”指与众不同，二者是反义关系。", "复杂": "非反义：“复杂”指不简单，与“一般”的普通义没有对立关系。", "明亮": "非反义：“明亮”指光线强，与“一般”没有反义关系。", "富裕": "非反义：“富裕”指钱多，与“一般”的普通义没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86056, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容词，指普通、通常，不特别。", "primary_collocate": null, "pronunciation": "yì bān", "ipa": "i˥˩ pan˥", "syllable_count": 2, "sentences": [{"text": "他只是一般的学生，没有什么特别的爱好。", "target_word": "一般", "complexity_tier": "T3", "furigana": "tā zhǐ shì yì bān de xué sheng méi yǒu shén me tè bié de ài hào", "sentence_source": "generated"}, {"text": "他喝的是一般的绿茶，不是名茶。", "target_word": "一般", "complexity_tier": "T3", "furigana": "tā hē de shì yì bān de lǜ chá bú shì míng chá", "sentence_source": "generated"}, {"text": "一般人都不喜欢早起。", "target_word": "一般", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书只是一般的小说，没有特别的地方。", "target_word": "一般", "complexity_tier": "T3", "furigana": "zhè běn shū zhǐ shì yì bān de xiǎo shuō méi yǒu tè bié de dì fang", "sentence_source": "generated"}, {"text": "这只是一般的感冒，不用担心。", "target_word": "一般", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一般的商店每天九点开门。", "target_word": "一般", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种菜一般的饭店都有。", "target_word": "一般", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一般的公寓都比较小。", "target_word": "一般", "complexity_tier": "T3", "furigana": "yì bān de gōng yù dōu bǐ jiào xiǎo", "sentence_source": "generated"}, {"text": "一般的手机就可以拍照。", "target_word": "一般", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们学校的一般教室都很大。", "target_word": "一般", "complexity_tier": "T3", "furigana": "wǒ men xué xiào de yì bān jiào shì dōu hěn dà", "sentence_source": "generated"}], "morphological_forms": [{"form": "一般来说", "label": "复合"}, {"form": "一般人", "label": "复合"}], "register": "中性", "sense_fingerprint": "普通、通常的，不特别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53b78f9d-f217-4af1-8d7e-8b11ddac9746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86056, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一般", "is_correct": true, "explanation": "正确答案。一般指普通、不特别，读作 yì bān。"}, {"text": "一半", "is_correct": false, "explanation": "yí bàn 与 yì bān 两个音节的声调都不同，意思是一半。"}, {"text": "一版", "is_correct": false, "explanation": "yì bǎn 与 yì bān 第二个音节声调不同，意思是一个版本。"}, {"text": "一边", "is_correct": false, "explanation": "yì biān 与 yì bān 韵母不同（多了 i），意思是一边、同时。"}, {"text": "一瓣", "is_correct": false, "explanation": "yí bàn 与 yì bān 两个音节的声调都不同，意思是一瓣。"}], "explanations": {"一般": "正确答案。一般指普通、不特别，读作 yì bān。", "一半": "yí bàn 与 yì bān 两个音节的声调都不同，意思是一半。", "一版": "yì bǎn 与 yì bān 第二个音节声调不同，意思是一个版本。", "一边": "yì biān 与 yì bān 韵母不同（多了 i），意思是一边、同时。", "一瓣": "yí bàn 与 yì bān 两个音节的声调都不同，意思是一瓣。"}, "sentence_index": null, "correct_answer": "一般"}, "level_3": {"options": [{"text": "一般", "is_correct": true, "explanation": "正确答案。“一般”表示普通，与“只是”和“没有什么特别的爱好”一致。"}, {"text": "特别", "is_correct": false, "explanation": "语义：“特别”与后文“没有什么特别的爱好”矛盾。"}, {"text": "非凡", "is_correct": false, "explanation": "语域：“非凡”是书面语，与口语中的“只是……的学生”不协调。"}, {"text": "豪华", "is_correct": false, "explanation": "搭配：“豪华”形容物品或场所，不能修饰学生。"}], "explanations": {"一般": "正确答案。“一般”表示普通，与“只是”和“没有什么特别的爱好”一致。", "特别": "语义：“特别”与后文“没有什么特别的爱好”矛盾。", "非凡": "语域：“非凡”是书面语，与口语中的“只是……的学生”不协调。", "豪华": "搭配：“豪华”形容物品或场所，不能修饰学生。"}, "sentence_index": 0, "correct_answer": "一般"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是奥运冠军，只是一般的运动员。", "explanation": "这里应该用〈优秀〉。奥运冠军不是普通的运动员，与“一般”矛盾。"}, {"text": "这块宝石世界上只有一块，是一般的宝石。", "explanation": "这里应该用〈罕见〉。世界上只有一块，说明很特别，不是一般的。"}, {"text": "这是国王住的宫殿，只是一般的房子。", "explanation": "这里应该用〈豪华〉。国王的宫殿不是普通的房子，与“一般”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86056, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "一般", "is_correct": true, "explanation": "正确答案。一般指普通、不特别，读作 yì bān。"}, {"text": "一帮", "is_correct": false, "explanation": "yì bāng 与 yì bān 第二个音节韵母不同（后鼻音 ang），意思是一群人。"}, {"text": "一板", "is_correct": false, "explanation": "yì bǎn 与 yì bān 第二个音节声调不同，意思是一块板。"}, {"text": "一盘", "is_correct": false, "explanation": "yì pán 与 yì bān 第二个音节声母（送气 p）和声调都不同，意思是一盘（东西）。"}], "explanations": {"一般": "正确答案。一般指普通、不特别，读作 yì bān。", "一帮": "yì bāng 与 yì bān 第二个音节韵母不同（后鼻音 ang），意思是一群人。", "一板": "yì bǎn 与 yì bān 第二个音节声调不同，意思是一块板。", "一盘": "yì pán 与 yì bān 第二个音节声母（送气 p）和声调都不同，意思是一盘（东西）。"}, "sentence_index": null, "correct_answer": "一般"}, "level_3": {"options": [{"text": "一般", "is_correct": true, "explanation": "正确答案。“一般”表示普通，与“都有”和句意一致。"}, {"text": "罕见", "is_correct": false, "explanation": "语义：句子强调普遍存在（“都有”），与“罕见”的少见之意不符。"}, {"text": "饱和", "is_correct": false, "explanation": "搭配：“饱和”多形容溶液或市场，不用来修饰饭店，与“都有”的句意不通。"}, {"text": "寂寞", "is_correct": false, "explanation": "搭配：“寂寞”形容人的心情，不用来修饰饭店。"}], "explanations": {"一般": "正确答案。“一般”表示普通，与“都有”和句意一致。", "罕见": "语义：句子强调普遍存在（“都有”），与“罕见”的少见之意不符。", "饱和": "搭配：“饱和”多形容溶液或市场，不用来修饰饭店，与“都有”的句意不通。", "寂寞": "搭配：“寂寞”形容人的心情，不用来修饰饭店。"}, "sentence_index": 6, "correct_answer": "一般"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车只能在月球上开，是一般的车。", "explanation": "这里应该用〈特殊〉。只能在月球上开的车很特别，不是一般的车。"}, {"text": "这只熊猫是白色的，是一只一般的熊猫。", "explanation": "这里应该用〈罕见〉。白色的熊猫很少见，不是一般的熊猫。"}, {"text": "他是全国最有名的作家，只是一般的作家。", "explanation": "这里应该用〈著名〉。全国最有名的作家不是普通作家，与“一般”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86056, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他只是一般地司机。", "corrected_sentence": "他只是一般的司机。", "error_description": "错误在“地”。“一般”修饰名词时要用结构助词“的”，不用“地”，应说“一般的司机”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86056, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只是一般地问题，很容易解决。", "corrected_sentence": "这只是一般的问题，很容易解决。", "error_description": "错误在“地”。“一般”修饰名词“问题”时要用结构助词“的”，不用“地”，应说“一般的问题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
