INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86058, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "名字，人或事物的称呼。", "primary_collocate": null, "pronunciation": "míng", "ipa": "miŋ˧˥", "syllable_count": 1, "sentences": [{"text": "我想给小狗起个名。", "target_word": "名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的名很好记。", "target_word": "名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想给新公司起个什么名？", "target_word": "名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "给孩子起个好名并不容易。", "target_word": "名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个名听起来很好听。", "target_word": "名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给孩子换了个名。", "target_word": "名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的名很特别。", "target_word": "名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个名我不太喜欢。", "target_word": "名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给自己的小猫起了一个可爱的名。", "target_word": "名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个名太长了，不好记。", "target_word": "名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名字", "label": "复合"}, {"form": "名称", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词，人或事物的名称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d8f0e7b-36d4-4a15-8847-6d6ee72c61b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.valida