INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86058, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "名", "is_correct": true, "explanation": "正确答案。míng（第二声），意思是名字、称呼。"}, {"text": "命", "is_correct": false, "explanation": "mìng（第四声）与 míng（第二声）声调不同，意思是生命、命令。"}, {"text": "民", "is_correct": false, "explanation": "mín（第二声）与 míng 韵母不同（-n 与 -ng），意思是人民。"}, {"text": "平", "is_correct": false, "explanation": "píng（第二声）与 míng 声母不同（p 与 m），意思是平安、平坦。"}, {"text": "停", "is_correct": false, "explanation": "tíng（第二声）与 míng 声母不同（t 与 m），意思是停止。"}, {"text": "零", "is_correct": false, "explanation": "líng（第二声）与 míng 声母不同（l 与 m），意思是零、没有。"}], "explanations": {"名": "正确答案。míng（第二声），意思是名字、称呼。", "命": "mìng（第四声）与 míng（第二声）声调不同，意思是生命、命令。", "民": "mín（第二声）与 míng 韵母不同（-n 与 -ng），意思是人民。", "平": "píng（第二声）与 míng 声母不同（p 与 m），意思是平安、平坦。", "停": "tíng（第二声）与 míng 声母不同（t 与 m），意思是停止。", "零": "líng（第二声）与 míng 声母不同（l 与 m），意思是零、没有。"}, "sentence_index": null, "correct_answer": "名"}, "level_3": {"options": [{"text": "玩具", "is_correct": false, "explanation": "搭配：“起”说的是给事物取名字，不能说给小狗起玩具。"}, {"text": "名", "is_correct": true, "explanation": "正确答案。“起个名”指给小狗取一个称呼。"}, {"text": "项圈", "is_correct": false, "explanation": "语义：项圈是戴在脖子上的东西，不是可以起的称呼。"}, {"text": "狗窝", "is_correct": false, "explanation": "搭配：“起”不用于搭建窝，要说“搭”或“买”狗窝。"}], "explanations": {"玩具": "搭配：“起”说的是给事物取名字，不能说给小狗起玩具。", "名": "正确答案。“起个名”指给小狗取一个称呼。", "项圈": "语义：项圈是戴在脖子上的东西，不是可以起的称呼。", "狗窝": "搭配：“起”不用于搭建窝，要说“搭”或“买”狗窝。"}, "sentence_index": 0, "correct_answer": "名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他讲了一个名，大家都笑了。", "explanation": "这里应该用〈笑话〉。名指人或事物的称呼，不能指讲出来逗人笑的故事，“讲”要搭配“笑话”。"}, {"text": "班上的名贴在墙上。", "explanation": "这里应该用〈名单〉。名指称呼，不指写着名字的单子，贴在墙上的要说名单。"}, {"text": "这本名很特别。", "explanation": "量词用错。名不用“本”来计量（“本”用于书籍），应说“这个名”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc1a1d69-248a-