INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86058, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "名", "is_correct": true, "explanation": "正确答案。míng（第二声），意思是名字、称呼。"}, {"text": "情", "is_correct": false, "explanation": "qíng（第二声）与 míng 声母不同（q 与 m），意思是感情。"}, {"text": "形", "is_correct": false, "explanation": "xíng（第二声）与 míng 声母不同（x 与 m），意思是形状。"}, {"text": "晴", "is_correct": false, "explanation": "qíng（第二声）与 míng 声母不同（q 与 m），意思是天气晴朗。"}], "explanations": {"名": "正确答案。míng（第二声），意思是名字、称呼。", "情": "qíng（第二声）与 míng 声母不同（q 与 m），意思是感情。", "形": "xíng（第二声）与 míng 声母不同（x 与 m），意思是形状。", "晴": "qíng（第二声）与 míng 声母不同（q 与 m），意思是天气晴朗。"}, "sentence_index": null, "correct_answer": "名"}, "level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "搭配：“身高”指人的高矮，不能用来形容电影。"}, {"text": "名", "is_correct": true, "explanation": "正确答案。“电影的名”指电影的名称。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，电影没有身材。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”指人或动物的重量，不能用于电影。"}], "explanations": {"身高": "搭配：“身高”指人的高矮，不能用来形容电影。", "名": "正确答案。“电影的名”指电影的名称。", "身材": "体貌：“身材”指人的体形，电影没有身材。", "体重": "搭配：“体重”指人或动物的重量，不能用于电影。"}, "sentence_index": 6, "correct_answer": "名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他获得了“最佳员工”的名。", "explanation": "这里应该用〈称号〉。获得荣誉的头衔要说称号，名指人或事物的称呼。"}, {"text": "这家店起了一扇名，很好记。", "explanation": "量词用错。“名”用“个”计量，不用“扇”（“扇”用于门窗）。"}, {"text": "这家店换了一条名。", "explanation": "量词用错。“名”用“个”计量，不用“条”（“条”用于鱼、路等长条的东西）。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc1a1d69-248a-48c6-9872-687195f3abb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86058, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈给我起了一只好听的名。", "corrected_sentence": "妈妈给我起了一个好听的名。", "error_description": "“名”的量词应用“个”，不能用“只”（“只”多用于动物）。应说“起了一个好听的名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc1a1d69-248a-48c6-9872-687195f3abb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86058, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们为这家新公司起了一张名。", "corrected_sentence": "我们为这家新公司起了一个名。", "error_description": "“名”的量词应用“个”，不用“张”（“张”多用于纸张、票据）。应说“起了一个名”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc1a1d69-248a-48c6-9872-687195f3abb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
