INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86059, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "或是用在两件事中间，意思是要么这个，要么那个。", "primary_collocate": null, "pronunciation": "huò shì", "ipa": "xuo˥˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "今晚我吃饺子或是吃面条。", "target_word": "或是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你去或是我去，都可以。", "target_word": "或是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买苹果或是买香蕉，我还没想好。", "target_word": "或是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会寄信或是发邮件给你。", "target_word": "或是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周一或是周二，我们见面吧。", "target_word": "或是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们可以在家看书，或是出去走走。", "target_word": "或是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以问老师，或是问同学。", "target_word": "或是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子想喝牛奶或是果汁。", "target_word": "或是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，他爱去海边或是山里玩。", "target_word": "或是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我一杯水或是一杯茶。", "target_word": "或是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "用在两件事之间，要么这个要么那个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef952436-ac10-4596-8374-89ff1cbf54ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86059, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "但是", "is_correct": false, "explanation": "语义：「但是」表示转折，前后没有对立，此句只是在两样食物之间选择。"}, {"text": "所以", "is_correct": false, "explanation": "语义：「所以」表示因果，吃饺子不是吃面条的结果。"}, {"text": "或是", "is_correct": true, "explanation": "正确：「或是」用在两件事之间，表示要么这个，要么那个。"}, {"text": "然而", "is_correct": false, "explanation": "语域：「然而」属于书面语，口语句中不用，且句中没有转折关系。"}], "explanations": {"但是": "语义：「但是」表示转折，前后没有对立，此句只是在两样食物之间选择。", "所以": "语义：「所以」表示因果，吃饺子不是吃面条的结果。", "或是": "正确：「或是」用在两件事之间，表示要么这个，要么那个。", "然而": "语域：「然而」属于书面语，口语句中不用，且句中没有转折关系。"}, "sentence_index": 0, "correct_answer": "或是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他会寄信，或是发邮件给你，两样都会做。", "explanation": "这里应该用〈并且〉，表示两件事都做；「或是」只表示二选一，与「两样都会做」矛盾。"}, {"text": "她一边听课，或是做笔记。", "explanation": "这里应该用〈同时〉，与「一边」搭配表示同时进行；「或是」表示二选一，不能与「一边」搭配。"}, {"text": "这个城市很大，或是很干净，两点都很好。", "explanation": "这里应该用〈而且〉，表示两个优点并列；「或是」只表示二选一，与「两点都很好」矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86059, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "因为", "is_correct": false, "explanation": "语义：「因为」表示原因，问老师不是问同学的原因。"}, {"text": "不过", "is_correct": false, "explanation": "语义：「不过」表示转折，前后没有对立，此句只是给出两个可以选择的对象。"}, {"text": "无论", "is_correct": false, "explanation": "搭配：「无论」需要与「都」或「也」呼应，句中没有这样的呼应。"}, {"text": "或是", "is_correct": true, "explanation": "正确：「或是」用在两件事之间，表示问老师或者问同学，二者选其一。"}], "explanations": {"因为": "语义：「因为」表示原因，问老师不是问同学的原因。", "不过": "语义：「不过」表示转折，前后没有对立，此句只是给出两个可以选择的对象。", "无论": "搭配：「无论」需要与「都」或「也」呼应，句中没有这样的呼应。", "或是": "正确：「或是」用在两件事之间，表示问老师或者问同学，二者选其一。"}, "sentence_index": 6, "correct_answer": "或是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他先去银行，或是去超市。", "explanation": "这里应该用〈然后〉，表示先后顺序；「或是」表示二选一，与「先」不搭配。"}, {"text": "她很饿，或是去吃饭。", "explanation": "这里应该用〈于是〉，表示因为饿所以去吃饭；「或是」只连接可选项，不能表示因果。"}, {"text": "我会说英语，或是会说法语，两种都会。", "explanation": "这里应该用〈而且〉，表示两种能力都有；「或是」只表示二选一，与「两种都会」矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86059, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们明天吃饭，或是或是去看电影。", "corrected_sentence": "我们明天吃饭，或是去看电影。", "error_description": "错误：「或是」多写了一次，连续出现「或是或是」；只需保留一个「或是」。正确形式：我们明天吃饭，或是去看电影。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86059, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们今天去看电影，或是或是去逛街。", "corrected_sentence": "我们今天去看电影，或是去逛街。", "error_description": "「或是」只需连接两个选项，用一次即可；错误句重复使用「或是或是」，应删去一个。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
