INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86064, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在选举或表决时，用写票或举手等方式表示意愿。", "primary_collocate": null, "pronunciation": "tóu piào", "ipa": "tʰoʊ˧˥ pʰjɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "明天全市的人都要去投票选市长。", "target_word": "投票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同意这个办法的人，请举手投票。", "target_word": "投票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家用举手的方式投票，多数人同意。", "target_word": "投票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选举那天，很多年轻人第一次投票。", "target_word": "投票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议上，每个人都有权利投票。", "target_word": "投票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要投票决定新经理是谁。", "target_word": "投票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷每次选举都会认真投票。", "target_word": "投票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十八岁以后，你就可以投票了。", "target_word": "投票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家投票的结果是，三分之二的人同意。", "target_word": "投票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不同意的人也投票，说出你的想法。", "target_word": "投票", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "投了票", "label": "体标（了）"}, {"form": "投过票", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "选举或表决时表示意愿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '749151d6-7ed4-4f35-af8d-c2dbfaf13d12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86064, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "投票", "is_correct": true, "explanation": "正确：“去投票选市长”指全市的人在选举中表达意愿，与“选市长”搭配。"}, {"text": "投资", "is_correct": false, "explanation": "语义：“投资”指把钱用于获利，与选市长的情境不符。"}, {"text": "投降", "is_correct": false, "explanation": "语义：“投降”指认输、停止抵抗，与选举不符。"}, {"text": "投影", "is_correct": false, "explanation": "搭配：“投影”指把影像投射到屏幕上，不能用于选市长。"}], "explanations": {"投票": "正确：“去投票选市长”指全市的人在选举中表达意愿，与“选市长”搭配。", "投资": "语义：“投资”指把钱用于获利，与选市长的情境不符。", "投降": "语义：“投降”指认输、停止抵抗，与选举不符。", "投影": "搭配：“投影”指把影像投射到屏幕上，不能用于选市长。"}, "sentence_index": 0, "correct_answer": "投票"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他投票投进了篮筐里。", "explanation": "这里应该用〈投篮〉。“投票”指选举时表达意愿，不能指把球投进篮筐。"}, {"text": "他投票投得很远。", "explanation": "这里应该用〈扔〉。“投票”不能表示把东西抛向远处。"}, {"text": "他投票很准。", "explanation": "这里应该用〈投篮〉。“投票”不能用于投球，投球要说“投篮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004070df-06ea-4322-b76d-56c06d8a92e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86064, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "投票", "is_correct": true, "explanation": "正确：“爷爷每次选举都会认真投票”指在选举中表达意愿，与“选举”搭配。"}, {"text": "投注", "is_correct": false, "explanation": "语义：“投注”指赌博下注，与选举的情境不符。"}, {"text": "投靠", "is_correct": false, "explanation": "语义：“投靠”指去依附别人，与在选举中表达意愿不符。"}, {"text": "投射", "is_correct": false, "explanation": "语义：“投射”指把光线或影像射向某处，与选举无关。"}], "explanations": {"投票": "正确：“爷爷每次选举都会认真投票”指在选举中表达意愿，与“选举”搭配。", "投注": "语义：“投注”指赌博下注，与选举的情境不符。", "投靠": "语义：“投靠”指去依附别人，与在选举中表达意愿不符。", "投射": "语义：“投射”指把光线或影像射向某处，与选举无关。"}, "sentence_index": 6, "correct_answer": "投票"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把硬币投票进了自动售货机。", "explanation": "这里不能用〈投票〉。此处是把硬币放进机器，与选举或表决无关，“投票”不适用。"}, {"text": "她把信件投票进了信箱。", "explanation": "这里不能用〈投票〉。“投票”只用于选举或表决，此处是把信件放进信箱，与选举无关。"}, {"text": "他把钱投票到了股市里。", "explanation": "这里不能用〈投票〉。此处是把钱用于获利，与选举或表决无关，“投票”不适用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004070df-06ea-4322-b76d-56c06d8a92e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86064, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我上周投票了一张票。", "corrected_sentence": "我上周投了一张票。", "error_description": "“投票”是离合词，“票”已包含在“投票”里，不能在“投”后再保留“票”作宾语。应说“投了一张票”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004070df-06ea-4322-b76d-56c06d8a92e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86064, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "选举那天，我们都投票他。", "corrected_sentence": "选举那天，我们都投票给他。", "error_description": "“投票”是不及物的离合词，不能直接带人作宾语，应说“投票给他”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004070df-06ea-4322-b76d-56c06d8a92e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86065, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收", "is_correct": true, "explanation": "反义：“收”指接受别人送来的东西，与“发”的送出义相对。"}, {"text": "吃", "is_correct": false, "explanation": "无关：“吃”与“发”的任何义项都不构成反义。"}, {"text": "跑", "is_correct": false, "explanation": "无关：“跑”不是“发”的反义词。"}, {"text": "看", "is_correct": false, "explanation": "无关：“看”不是“发”的反义词。"}], "correct_answer": "收", "explanations": {"收": "反义：“收”指接受别人送来的东西，与“发”的送出义相对。", "吃": "无关：“吃”与“发”的任何义项都不构成反义。", "跑": "无关：“跑”不是“发”的反义词。", "看": "无关：“看”不是“发”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86065, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收", "is_correct": true, "explanation": "反义：“收”指接受别人送来的东西，与“发”的送出义相对。"}, {"text": "买", "is_correct": false, "explanation": "无关：“买”不是“发”的反义词，“买”与“卖”才是一对反义词。"}, {"text": "站", "is_correct": false, "explanation": "无关：“站”与“发”的任何义项都不构成反义。"}, {"text": "喝", "is_correct": false, "explanation": "无关：“喝”不是“发”的反义词。"}], "correct_answer": "收", "explanations": {"收": "反义：“收”指接受别人送来的东西，与“发”的送出义相对。", "买": "无关：“买”不是“发”的反义词，“买”与“卖”才是一对反义词。", "站": "无关：“站”与“发”的任何义项都不构成反义。", "喝": "无关：“喝”不是“发”的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86065, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "“发”是把东西送出去。", "primary_collocate": null, "pronunciation": "fā", "ipa": "fa˥", "syllable_count": 1, "sentences": [{"text": "我给老师发了一封邮件。", "target_word": "发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都给我发短信。", "target_word": "发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把照片发给我。", "target_word": "发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在微信上发了一张照片。", "target_word": "发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事你可以发邮件告诉他。", "target_word": "发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她发消息问我什么时候回家。", "target_word": "发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快递明天就能发出去。", "target_word": "发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我刚给朋友发过一个红包。", "target_word": "发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把地址发给我，我去找你。", "target_word": "发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网上发了很多视频。", "target_word": "发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发了", "label": "体标（了）"}, {"form": "发过", "label": "体标（过）"}, {"form": "發", "label": "繁体"}], "register": "中性", "sense_fingerprint": "发｜动词｜把东西送出去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '683cea7f-9faf-4ce5-be29-922b841282d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86065, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "发", "is_correct": true, "explanation": "正确：发（fā），意思是送出、传出。"}, {"text": "法", "is_correct": false, "explanation": "法（fǎ，第三声）与 fā（第一声）声调不同，意思是法律、方法。"}, {"text": "哈", "is_correct": false, "explanation": "哈（hā）与 fā 声母不同（h 与 f），意思是笑声或呼气声。"}, {"text": "翻", "is_correct": false, "explanation": "翻（fān）比 fā 多一个 n 韵尾，意思是翻转。"}, {"text": "罚", "is_correct": false, "explanation": "罚（fá，第二声）与 fā（第一声）声调不同，意思是处罚。"}], "explanations": {"发": "正确：发（fā），意思是送出、传出。", "法": "法（fǎ，第三声）与 fā（第一声）声调不同，意思是法律、方法。", "哈": "哈（hā）与 fā 声母不同（h 与 f），意思是笑声或呼气声。", "翻": "翻（fān）比 fā 多一个 n 韵尾，意思是翻转。", "罚": "罚（fá，第二声）与 fā（第一声）声调不同，意思是处罚。"}, "sentence_index": null, "correct_answer": "发"}, "level_3": {"options": [{"text": "发", "is_correct": true, "explanation": "正确：“发”表示把邮件送出去，与“给老师”的送达义相合。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，与“给老师”的送达义不合。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮料，不能“喝邮件”。"}, {"text": "跑", "is_correct": false, "explanation": "配价：“跑”不带“邮件”这样的宾语。"}], "explanations": {"发": "正确：“发”表示把邮件送出去，与“给老师”的送达义相合。", "扔": "语义：“扔”是丢弃，与“给老师”的送达义不合。", "喝": "搭配：“喝”的对象是饮料，不能“喝邮件”。", "跑": "配价：“跑”不带“邮件”这样的宾语。"}, "sentence_index": 0, "correct_answer": "发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把钱发到了银行。", "explanation": "这里应该用〈存〉。“发”指送出或发出，把钱放进银行要用〈存〉。"}, {"text": "他每天都发一朵花给老师。", "explanation": "这里应该用〈送〉。“发”用于消息或物品的发出，送花给人要用〈送〉。"}, {"text": "妈妈每天把孩子发到学校。", "explanation": "这里应该用〈送〉。“发”用于消息或物品的发出，接送人去某处要用〈送〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86065, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "发", "is_correct": true, "explanation": "正确：发（fā），意思是送出、传出。"}, {"text": "方", "is_correct": false, "explanation": "方（fāng）比 fā 多一个 ng 韵尾，意思是方向、方形。"}, {"text": "撒", "is_correct": false, "explanation": "撒（sā）与 fā 声母不同（s 与 f），意思是撒开、撒播。"}, {"text": "趴", "is_correct": false, "explanation": "趴（pā）与 fā 声母不同（p 与 f），意思是身体伏在地上。"}, {"text": "乏", "is_correct": false, "explanation": "乏（fá，第二声）与 fā（第一声）声调不同，意思是疲倦、缺少。"}], "explanations": {"发": "正确：发（fā），意思是送出、传出。", "方": "方（fāng）比 fā 多一个 ng 韵尾，意思是方向、方形。", "撒": "撒（sā）与 fā 声母不同（s 与 f），意思是撒开、撒播。", "趴": "趴（pā）与 fā 声母不同（p 与 f），意思是身体伏在地上。", "乏": "乏（fá，第二声）与 fā（第一声）声调不同，意思是疲倦、缺少。"}, "sentence_index": null, "correct_answer": "发"}, "level_3": {"options": [{"text": "发", "is_correct": true, "explanation": "正确：“发出去”表示快递被寄送出去，与“明天就能”的时间安排相合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”与快递无关，也不能说“吃出去”。"}, {"text": "装", "is_correct": false, "explanation": "搭配：“装”指放入容器，不能与“出去”组成表示寄出的说法。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔出去”指丢弃，与快递被送达的语境不合。"}], "explanations": {"发": "正确：“发出去”表示快递被寄送出去，与“明天就能”的时间安排相合。", "吃": "语义：“吃”与快递无关，也不能说“吃出去”。", "装": "搭配：“装”指放入容器，不能与“出去”组成表示寄出的说法。", "扔": "语义：“扔出去”指丢弃，与快递被送达的语境不合。"}, "sentence_index": 6, "correct_answer": "发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天晚上都发电话给妈妈。", "explanation": "这里应该用〈打〉。打电话用“打”，不说“发电话”。"}, {"text": "我发了一杯水给奶奶。", "explanation": "这里应该用〈递〉。“发”用于消息或物品的寄出，当面把东西交到别人手里要用〈递〉。"}, {"text": "我从朋友那里发了一封信。", "explanation": "这里应该用〈收〉。“发”指从自己这里送出去，从朋友那里得到要用〈收〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86065, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把合同发了给客户。", "corrected_sentence": "我把合同发给了客户。", "error_description": "错误：“了”放在了“给”前面。正确：“发给”是一个整体，“了”应放在“给”之后，即“发给了客户”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86065, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请把文件发在我的邮箱。", "corrected_sentence": "请把文件发到我的邮箱。", "error_description": "错误：“发”后表示送达地点的介词用错了。正确：送达地点要用“到”，即“发到我的邮箱”，不能说“发在我的邮箱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86066, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收", "is_correct": true, "explanation": "反义：“收”指接受、收取，与“发放”的给出义相对。"}, {"text": "唱", "is_correct": false, "explanation": "无关：“唱”与“发放”的任何义项都不构成反义。"}, {"text": "走", "is_correct": false, "explanation": "无关：“走”不是“发放”的反义词。"}, {"text": "想", "is_correct": false, "explanation": "无关：“想”不是“发放”的反义词。"}], "correct_answer": "收", "explanations": {"收": "反义：“收”指接受、收取，与“发放”的给出义相对。", "唱": "无关：“唱”与“发放”的任何义项都不构成反义。", "走": "无关：“走”不是“发放”的反义词。", "想": "无关：“想”不是“发放”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
