INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86066, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "动词，送出、交付、发放。", "primary_collocate": null, "pronunciation": "fā", "ipa": "fa˥", "syllable_count": 1, "sentences": [{"text": "公司每月十号发工资。", "target_word": "发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给每个学生发了一本书。", "target_word": "发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课前，老师发了练习题。", "target_word": "发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，公司发了奖金。", "target_word": "发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长给得奖的学生发证书。", "target_word": "发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天下午要发新校服。", "target_word": "发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们给每位客人发了一份礼物。", "target_word": "发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说下个月给大家发奖金。", "target_word": "发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院给护士们发了口罩。", "target_word": "发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车站的工作人员正在发免费地图。", "target_word": "发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发了", "label": "体标（了）"}, {"form": "发过", "label": "体标（过）"}, {"form": "發", "label": "繁体"}], "register": "中性", "sense_fingerprint": "发｜动词｜送出、交付，发放", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '683cea7f-9faf-4ce5-be29-922b841282d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86066, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "发", "is_correct": true, "explanation": "正确：发（fā），意思是发放、交付。"}, {"text": "罚", "is_correct": false, "explanation": "罚（fá，第二声）与 fā（第一声）声调不同，意思是处罚。"}, {"text": "哈", "is_correct": false, "explanation": "哈（hā）与 fā 声母不同（h 与 f），意思是笑声或呼气声。"}, {"text": "方", "is_correct": false, "explanation": "方（fāng）比 fā 多一个 ng 韵尾，意思是方向、方形。"}], "explanations": {"发": "正确：发（fā），意思是发放、交付。", "罚": "罚（fá，第二声）与 fā（第一声）声调不同，意思是处罚。", "哈": "哈（hā）与 fā 声母不同（h 与 f），意思是笑声或呼气声。", "方": "方（fāng）比 fā 多一个 ng 韵尾，意思是方向、方形。"}, "sentence_index": null, "correct_answer": "发"}, "level_3": {"options": [{"text": "发", "is_correct": true, "explanation": "正确：“发工资”指公司把工资发放给员工，与“每月十号”的支付时间相合。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物等，不能说“洗工资”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说“唱工资”。"}, {"text": "查", "is_correct": false, "explanation": "语义：“查”是核对、检查，与“发放工资”的交付义不合。"}], "explanations": {"发": "正确：“发工资”指公司把工资发放给员工，与“每月十号”的支付时间相合。", "洗": "搭配：“洗”的对象是衣物等，不能说“洗工资”。", "唱": "搭配：“唱”的对象是歌曲，不能说“唱工资”。", "查": "语义：“查”是核对、检查，与“发放工资”的交付义不合。"}, "sentence_index": 0, "correct_answer": "发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "校长把优秀学生发到台上去。", "explanation": "这里应该用〈请〉。“发”用于交付物品或消息，请人上台要用〈请〉。"}, {"text": "公司决定发他去上海出差。", "explanation": "这里应该用〈派〉。“发”用于交付物品或消息，派人去做事要用〈派〉。"}, {"text": "他今天在公园发了一只风筝。", "explanation": "这里应该用〈放〉。“发”用于交付物品或消息，放风筝要用〈放〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86066, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "发", "is_correct": true, "explanation": "正确：发（fā），意思是发放、交付。"}, {"text": "法", "is_correct": false, "explanation": "法（fǎ，第三声）与 fā（第一声）声调不同，意思是法律、方法。"}, {"text": "撒", "is_correct": false, "explanation": "撒（sā）与 fā 声母不同（s 与 f），意思是撒开、撒播。"}, {"text": "翻", "is_correct": false, "explanation": "翻（fān）比 fā 多一个 n 韵尾，意思是翻转。"}], "explanations": {"发": "正确：发（fā），意思是发放、交付。", "法": "法（fǎ，第三声）与 fā（第一声）声调不同，意思是法律、方法。", "撒": "撒（sā）与 fā 声母不同（s 与 f），意思是撒开、撒播。", "翻": "翻（fān）比 fā 多一个 n 韵尾，意思是翻转。"}, "sentence_index": null, "correct_answer": "发"}, "level_3": {"options": [{"text": "发", "is_correct": true, "explanation": "正确：“发了一份礼物”指把礼物交给每位客人，与“给每位客人”的分发义相合。"}, {"text": "收", "is_correct": false, "explanation": "配价：“收”的施事是接收方，与“给每位客人”的给出关系不合。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，与“给客人”的交付义相反。"}, {"text": "睡", "is_correct": false, "explanation": "语法：“睡”是不及物动词，不能带“一份礼物”作宾语。"}], "explanations": {"发": "正确：“发了一份礼物”指把礼物交给每位客人，与“给每位客人”的分发义相合。", "收": "配价：“收”的施事是接收方，与“给每位客人”的给出关系不合。", "扔": "语义：“扔”是丢弃，与“给客人”的交付义相反。", "睡": "语法：“睡”是不及物动词，不能带“一份礼物”作宾语。"}, "sentence_index": 6, "correct_answer": "发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我从老板那里发了一份奖金。", "explanation": "这里应该用〈领〉。“发”由给出者作主语，从别人那里得到要用〈领〉。"}, {"text": "他每天都发小孩去学校。", "explanation": "这里应该用〈送〉。“发”用于消息或物品的发出，接送人去某处要用〈送〉。"}, {"text": "他每天都发狗出门溜达。", "explanation": "这里应该用〈带〉。“发”用于交付物品或消息，带动物出门要用〈带〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86066, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司把新的工作证发了给每位员工。", "corrected_sentence": "公司把新的工作证发给了每位员工。", "error_description": "错误：“了”放在了“给”前面。正确：“发给”是一个整体，“了”应放在“给”之后，即“发给了每位员工”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86066, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医院每个月都给护士给发工资。", "corrected_sentence": "医院每个月都给护士发工资。", "error_description": "错误：“给”重复出现。正确：“给护士”只用一次，即“医院每个月都给护士发工资”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
