INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86067, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "日子是过去的一天一天。", "primary_collocate": null, "pronunciation": "rì zi", "ipa": "ʐ̩˥˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "在国外的日子，我常想家。", "target_word": "日子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那些日子，我天天都去河边。", "target_word": "日子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我忘不了在北京的那些日子。", "target_word": "日子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那段日子，他每天都很累。", "target_word": "日子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些日子你去哪儿了？", "target_word": "日子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前些日子，我生了一场病。", "target_word": "日子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想起在学校的日子，她笑了。", "target_word": "日子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈常说起他们小时候的日子。", "target_word": "日子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过去的日子，他一直记着。", "target_word": "日子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学的日子过去了，我们都长大了。", "target_word": "日子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段日子", "label": "量词"}, {"form": "那些日子", "label": "复合"}], "register": "口语", "sense_fingerprint": "日子：过去的一天天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0344090-a91f-48fd-a918-ec4ab7350984') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86067, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "日子", "is_correct": true, "explanation": "日子（rì zi）是本词，指过去的一天天。"}, {"text": "栗子", "is_correct": false, "explanation": "栗子（lì zi）与日子（rì zi）第一音节声母不同（l/r），声调相同，意思是栗子（坚果）。"}, {"text": "梨子", "is_correct": false, "explanation": "梨子（lí zi）与日子（rì zi）第一音节声母不同（l/r），声调也不同，意思是梨（水果）。"}, {"text": "椅子", "is_correct": false, "explanation": "椅子（yǐ zi）与日子（rì zi）第一音节声母不同（y/r），声调也不同，意思是椅子。"}, {"text": "腻子", "is_correct": false, "explanation": "腻子（nì zi）与日子（rì zi）第一音节声母不同（n/r），意思是腻子（一种涂料）。"}], "explanations": {"日子": "日子（rì zi）是本词，指过去的一天天。", "栗子": "栗子（lì zi）与日子（rì zi）第一音节声母不同（l/r），声调相同，意思是栗子（坚果）。", "梨子": "梨子（lí zi）与日子（rì zi）第一音节声母不同（l/r），声调也不同，意思是梨（水果）。", "椅子": "椅子（yǐ zi）与日子（rì zi）第一音节声母不同（y/r），声调也不同，意思是椅子。", "腻子": "腻子（nì zi）与日子（rì zi）第一音节声母不同（n/r），意思是腻子（一种涂料）。"}, "sentence_index": null, "correct_answer": "日子"}, "level_3": {"options": [{"text": "日子", "is_correct": true, "explanation": "“日子”指一段过去的时间，与“在国外”和“想家”搭配，句意通顺。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是装东西的袋子，不能指“在国外的一段时间”。"}, {"text": "地图", "is_correct": false, "explanation": "语义：“地图”是地理图件，不能指“在国外的一段时间”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能指“在国外”的一段时间。"}], "explanations": {"日子": "“日子”指一段过去的时间，与“在国外”和“想家”搭配，句意通顺。", "书包": "语义：“书包”是装东西的袋子，不能指“在国外的一段时间”。", "地图": "语义：“地图”是地理图件，不能指“在国外的一段时间”。", "身材": "体貌：“身材”指人的体形，不能指“在国外”的一段时间。"}, "sentence_index": 0, "correct_answer": "日子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的日子很强，大家都去树下乘凉。", "explanation": "这里应该用〈日照〉。太阳照射的强度要说“日照”，“日子”指时间或生活，不指日光。"}, {"text": "这台机器的日子有十年。", "explanation": "这里应该用〈寿命〉。机器的使用年限要说“寿命”，“日子”不用于机器的使用年限。"}, {"text": "他的上课日子是九点。", "explanation": "这里应该用〈时间〉。具体几点上课要说“时间”，“日子”只指日期或一段时期，不指钟点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86067, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "日子", "is_correct": true, "explanation": "日子（rì zi）是本词，指过去的一天天。"}, {"text": "李子", "is_correct": false, "explanation": "李子（lǐ zi）与日子（rì zi）第一音节声母不同（l/r），声调也不同，意思是李子（水果）。"}, {"text": "柿子", "is_correct": false, "explanation": "柿子（shì zi）与日子（rì zi）第一音节声母不同（sh/r），意思是柿子（水果）。"}, {"text": "栗子", "is_correct": false, "explanation": "栗子（lì zi）与日子（rì zi）第一音节声母不同（l/r），声调相同，意思是栗子（坚果）。"}, {"text": "日志", "is_correct": false, "explanation": "日志（rì zhì）与日子（rì zi）第二音节声母不同（zh/z），意思是日志（记录）。"}], "explanations": {"日子": "日子（rì zi）是本词，指过去的一天天。", "李子": "李子（lǐ zi）与日子（rì zi）第一音节声母不同（l/r），声调也不同，意思是李子（水果）。", "柿子": "柿子（shì zi）与日子（rì zi）第一音节声母不同（sh/r），意思是柿子（水果）。", "栗子": "栗子（lì zi）与日子（rì zi）第一音节声母不同（l/r），声调相同，意思是栗子（坚果）。", "日志": "日志（rì zhì）与日子（rì zi）第二音节声母不同（zh/z），意思是日志（记录）。"}, "sentence_index": null, "correct_answer": "日子"}, "level_3": {"options": [{"text": "日子", "is_correct": true, "explanation": "“日子”指一段过去的时间，“想起在学校的”加上“日子”，句意通顺。"}, {"text": "气温", "is_correct": false, "explanation": "语义：“气温”是温度数值，不能成为“想起”后“笑了”的一段经历。"}, {"text": "发票", "is_correct": false, "explanation": "语义：“发票”是交易凭证，不能指“在学校的一段时间”。"}, {"text": "音量", "is_correct": false, "explanation": "语义：“音量”指声音的大小，不能成为“想起”后“笑了”的回忆对象。"}], "explanations": {"日子": "“日子”指一段过去的时间，“想起在学校的”加上“日子”，句意通顺。", "气温": "语义：“气温”是温度数值，不能成为“想起”后“笑了”的一段经历。", "发票": "语义：“发票”是交易凭证，不能指“在学校的一段时间”。", "音量": "语义：“音量”指声音的大小，不能成为“想起”后“笑了”的回忆对象。"}, "sentence_index": 6, "correct_answer": "日子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个学位的日子是四年。", "explanation": "这里应该用〈学制〉。表示学习的年限要说“学制”，“日子”不用来计算确定的年数。"}, {"text": "这部电影的日子是两小时。", "explanation": "这里应该用〈时长〉。电影的长度要说“时长”，“日子”只用于时期或生活。"}, {"text": "借书的日子是一个月。", "explanation": "这里应该用〈期限〉。借阅的时限要说“期限”，“日子”不用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86067, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那条日子我过得很平静。", "corrected_sentence": "那段日子我过得很平静。", "error_description": "量词“条”用于细长的东西，不能用于“日子”，应说“那段日子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86067, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那颗日子，他每天过得很累。", "corrected_sentence": "那段日子，他每天过得很累。", "error_description": "量词“颗”用于小而圆的东西，不能用于“日子”，应说“那段日子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
