INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86068, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指时间，或指生活。", "primary_collocate": null, "pronunciation": "rì zi", "ipa": "ʐ̩˥˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "他一个人的日子很苦。", "target_word": "日子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "日子一天比一天好。", "target_word": "日子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "奶奶常说现在的日子真好。", "target_word": "日子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "日子久了你就会习惯。", "target_word": "日子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "离考试的日子不多了，他每天都在复习。", "target_word": "日子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这段日子过得真快。", "target_word": "日子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们现在的日子过得很好。", "target_word": "日子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们刚结婚，日子过得很甜。", "target_word": "日子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一个人带着孩子，日子过得不容易。", "target_word": "日子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候家里穷，可是我们过着快乐的日子。", "target_word": "日子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段日子", "label": "量词"}, {"form": "好日子", "label": "复合"}], "register": "口语", "sense_fingerprint": "日子：时间；生活", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0344090-a91f-48fd-a918-ec4ab7350984') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86068, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "日子", "is_correct": true, "explanation": "日子（rì zi）是本词，指时间或生活。"}, {"text": "李子", "is_correct": false, "explanation": "李子（lǐ zi）与日子（rì zi）第一音节声母不同（l/r），声调也不同，意思是李子（水果）。"}, {"text": "日志", "is_correct": false, "explanation": "日志（rì zhì）与日子（rì zi）第二音节声母不同（zh/z），意思是日志（记录）。"}, {"text": "柿子", "is_correct": false, "explanation": "柿子（shì zi）与日子（rì zi）第一音节声母不同（sh/r），意思是柿子（水果）。"}, {"text": "栗子", "is_correct": false, "explanation": "栗子（lì zi）与日子（rì zi）第一音节声母不同（l/r），声调相同，意思是栗子（坚果）。"}], "explanations": {"日子": "日子（rì zi）是本词，指时间或生活。", "李子": "李子（lǐ zi）与日子（rì zi）第一音节声母不同（l/r），声调也不同，意思是李子（水果）。", "日志": "日志（rì zhì）与日子（rì zi）第二音节声母不同（zh/z），意思是日志（记录）。", "柿子": "柿子（shì zi）与日子（rì zi）第一音节声母不同（sh/r），意思是柿子（水果）。", "栗子": "栗子（lì zi）与日子（rì zi）第一音节声母不同（l/r），声调相同，意思是栗子（坚果）。"}, "sentence_index": null, "correct_answer": "日子"}, "level_3": {"options": [{"text": "日子", "is_correct": true, "explanation": "“日子”指一段生活，“很苦”描述这段生活，句意通顺。"}, {"text": "房间", "is_correct": false, "explanation": "语义：“房间”是居住的空间，不能“很苦”。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“钥匙”是开锁的工具，不能“很苦”。"}, {"text": "日记", "is_correct": false, "explanation": "搭配：“很苦”描述生活或经历，不能修饰“日记”。"}], "explanations": {"日子": "“日子”指一段生活，“很苦”描述这段生活，句意通顺。", "房间": "语义：“房间”是居住的空间，不能“很苦”。", "钥匙": "语义：“钥匙”是开锁的工具，不能“很苦”。", "日记": "搭配：“很苦”描述生活或经历，不能修饰“日记”。"}, "sentence_index": 0, "correct_answer": "日子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天都写日子，记录生活。", "explanation": "这里应该用〈日记〉。记录每天的事要写“日记”，“日子”指时间或生活，不指记录的本子，不能说写日子。"}, {"text": "这份合同的日子是一年。", "explanation": "这里应该用〈期限〉。合同的有效时长要说“期限”，“日子”不用来表示确定的年限。"}, {"text": "这本书的日子有三百页。", "explanation": "这里应该用〈页数〉。书的长度要说“页数”，“日子”指时间或生活，不能用页来计算。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86068, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "日子", "is_correct": true, "explanation": "日子（rì zi）是本词，指时间或生活。"}, {"text": "栗子", "is_correct": false, "explanation": "栗子（lì zi）与日子（rì zi）第一音节声母不同（l/r），声调相同，意思是栗子（坚果）。"}, {"text": "梨子", "is_correct": false, "explanation": "梨子（lí zi）与日子（rì zi）第一音节声母不同（l/r），声调也不同，意思是梨（水果）。"}, {"text": "椅子", "is_correct": false, "explanation": "椅子（yǐ zi）与日子（rì zi）第一音节声母不同（y/r），声调也不同，意思是椅子。"}, {"text": "腻子", "is_correct": false, "explanation": "腻子（nì zi）与日子（rì zi）第一音节声母不同（n/r），意思是腻子（一种涂料）。"}], "explanations": {"日子": "日子（rì zi）是本词，指时间或生活。", "栗子": "栗子（lì zi）与日子（rì zi）第一音节声母不同（l/r），声调相同，意思是栗子（坚果）。", "梨子": "梨子（lí zi）与日子（rì zi）第一音节声母不同（l/r），声调也不同，意思是梨（水果）。", "椅子": "椅子（yǐ zi）与日子（rì zi）第一音节声母不同（y/r），声调也不同，意思是椅子。", "腻子": "腻子（nì zi）与日子（rì zi）第一音节声母不同（n/r），意思是腻子（一种涂料）。"}, "sentence_index": null, "correct_answer": "日子"}, "level_3": {"options": [{"text": "日子", "is_correct": true, "explanation": "“日子”指一段生活，“过得很好”描述我们现在的生活状况，句意通顺。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“房子”是建筑，不会“过得很好”。"}, {"text": "课本", "is_correct": false, "explanation": "语义：“课本”是书籍，不能“过得很好”。"}, {"text": "晚饭", "is_correct": false, "explanation": "搭配：“过”和“过得很好”一般不用于晚饭，不能搭配“晚饭”。"}], "explanations": {"日子": "“日子”指一段生活，“过得很好”描述我们现在的生活状况，句意通顺。", "房子": "语义：“房子”是建筑，不会“过得很好”。", "课本": "语义：“课本”是书籍，不能“过得很好”。", "晚饭": "搭配：“过”和“过得很好”一般不用于晚饭，不能搭配“晚饭”。"}, "sentence_index": 6, "correct_answer": "日子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵老树的日子有三百年。", "explanation": "这里应该用〈寿命〉。树的存活年限要说“寿命”，“日子”指时间或人的生活，不用于树。"}, {"text": "会议的日子定在下午三点。", "explanation": "这里应该用〈时间〉。具体的钟点要说“时间”，“日子”只指日期或一段时期，不指几点。"}, {"text": "这场比赛的日子持续了九十分钟。", "explanation": "这里应该用〈时长〉。比赛的持续长度要说“时长”，“日子”以天计，不用于分钟计算。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86068, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张日子我们过得很快。", "corrected_sentence": "这段日子我们过得很快。", "error_description": "量词“张”用于平面的东西，不能用于“日子”，应说“这段日子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86068, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我爷爷的一根日子过得很平静。", "corrected_sentence": "我爷爷的一段日子过得很平静。", "error_description": "量词“根”用于细长的东西，不能用于“日子”，应说“一段日子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
