INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86070, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "数量词，表示少量，不多。", "primary_collocate": null, "pronunciation": "yì diǎn", "ipa": "i˥˩ tjɛn˨˩", "syllable_count": 2, "sentences": [{"text": "杯子里只有一点水。", "target_word": "一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我一点时间。", "target_word": "一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只会说一点中文。", "target_word": "一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱里还有一点牛奶。", "target_word": "一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天只吃了一点米饭。", "target_word": "一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在汤里放一点盐。", "target_word": "一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上只剩一点面包了。", "target_word": "一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请再给我一点糖。", "target_word": "一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有一点问题想问老师。", "target_word": "一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们只有一点时间了。", "target_word": "一点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一点儿", "label": "儿化"}], "register": "口语", "sense_fingerprint": "数量词：修饰名词，表示少量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0c09091-d658-4b2c-8dad-66ea54b6e5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86070, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一点", "is_correct": true, "explanation": "正确答案。“一点”表示少量。"}, {"text": "一脸", "is_correct": false, "explanation": "liǎn（第三声）与 diǎn（第三声）只差声母 l 和 d，意思是“满脸”，不表示少量。"}, {"text": "一眼", "is_correct": false, "explanation": "yǎn 与 diǎn 只差声母（有无 d），意思是“看一下”，与少量无关。"}, {"text": "一连", "is_correct": false, "explanation": "lián（第二声）与 diǎn（第三声）声母、声调都不同，意思是“连续”，不表示少量。"}], "explanations": {"一点": "正确答案。“一点”表示少量。", "一脸": "liǎn（第三声）与 diǎn（第三声）只差声母 l 和 d，意思是“满脸”，不表示少量。", "一眼": "yǎn 与 diǎn 只差声母（有无 d），意思是“看一下”，与少量无关。", "一连": "lián（第二声）与 diǎn（第三声）声母、声调都不同，意思是“连续”，不表示少量。"}, "sentence_index": null, "correct_answer": "一点"}, "level_3": {"options": [{"text": "一点", "is_correct": true, "explanation": "正确：“杯子里只有一点水”表示水很少，与“只有”呼应。"}, {"text": "很多", "is_correct": false, "explanation": "语义：“很多”与“只有”矛盾，不符合句意。"}, {"text": "大量", "is_correct": false, "explanation": "搭配：“大量水”与“只有”及杯子的容量不协调，前后矛盾。"}, {"text": "全部", "is_correct": false, "explanation": "语义：“全部”与“只有”意思相反，不符合句意。"}], "explanations": {"一点": "正确：“杯子里只有一点水”表示水很少，与“只有”呼应。", "很多": "语义：“很多”与“只有”矛盾，不符合句意。", "大量": "搭配：“大量水”与“只有”及杯子的容量不协调，前后矛盾。", "全部": "语义：“全部”与“只有”意思相反，不符合句意。"}, "sentence_index": 0, "correct_answer": "一点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教室里有一点老师。", "explanation": "这里应该用〈几位〉。“一点”表示不定的少量，不能用来数人，要说“几位老师”。"}, {"text": "这栋楼一点高，有五十层。", "explanation": "这里应该用〈很〉。“一点”表示少量，不用来形容很高的楼房，要说“很高”。"}, {"text": "我们喝了一点三杯水。", "explanation": "这里应该用〈三杯〉。“一点”表示不定的少量，不能与确定的数目“三杯”并用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df381f64-996e-4af7-994f-7762088bac64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86070, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一点", "is_correct": true, "explanation": "正确：“桌上只剩一点面包了”表示剩下的很少，与“只剩”呼应。"}, {"text": "不少", "is_correct": false, "explanation": "语义：“不少”表示数量多，与“只剩”矛盾。"}, {"text": "许多", "is_correct": false, "explanation": "语义：“许多”表示数量多，与“只剩”的少量含义相反。"}, {"text": "所有", "is_correct": false, "explanation": "搭配：“只剩”后接“所有”，语义冲突，前后不一致。"}], "explanations": {"一点": "正确：“桌上只剩一点面包了”表示剩下的很少，与“只剩”呼应。", "不少": "语义：“不少”表示数量多，与“只剩”矛盾。", "许多": "语义：“许多”表示数量多，与“只剩”的少量含义相反。", "所有": "搭配：“只剩”后接“所有”，语义冲突，前后不一致。"}, "sentence_index": 6, "correct_answer": "一点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在汤里放了一点很多盐。", "explanation": "这里应该用〈很多〉。“一点”表示少量，与“很多”意思相反，不能并用。"}, {"text": "这个菜一点辣。", "explanation": "这里应该用〈有点〉。“一点”不能直接作谓语修饰形容词，要说“有点辣”。"}, {"text": "我买了一点只鸡。", "explanation": "这里应该用〈只〉。“一点”表示不定的少量，不能与个体量词“只”并用计数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df381f64-996e-4af7-994f-7762088bac64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86070, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "杯子里只有很一点果汁。", "corrected_sentence": "杯子里只有一点果汁。", "error_description": "程度副词误用：「一点」本身已表示少量，前面不能再加程度副词「很」；应删去「很」，说「只有一点果汁」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df381f64-996e-4af7-994f-7762088bac64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86070, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "桌上只有一点个蛋糕。", "corrected_sentence": "桌上只有一点蛋糕。", "error_description": "量词错误：“一点”已表示不定的少量，后面不能再加个体量词“个”，应说“一点蛋糕”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df381f64-996e-4af7-994f-7762088bac64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86071, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "和睦", "is_correct": true, "explanation": "“和睦”指关系融洽，与“不和”（关系不好）意思相反，是该义项的反义词。"}, {"text": "香甜", "is_correct": false, "explanation": "“香甜”形容味道或睡眠，与“不和”没有反义关系。"}, {"text": "宽敞", "is_correct": false, "explanation": "“宽敞”形容空间大，与“不和”没有反义关系。"}, {"text": "结实", "is_correct": false, "explanation": "“结实”形容物体坚固或人体健壮，与“不和”没有反义关系。"}], "correct_answer": "和睦", "explanations": {"和睦": "“和睦”指关系融洽，与“不和”（关系不好）意思相反，是该义项的反义词。", "香甜": "“香甜”形容味道或睡眠，与“不和”没有反义关系。", "宽敞": "“宽敞”形容空间大，与“不和”没有反义关系。", "结实": "“结实”形容物体坚固或人体健壮，与“不和”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
