INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86071, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "“不和”是说两个人关系不好，常常吵架。", "primary_collocate": null, "pronunciation": "bù hé", "ipa": "pu⁵¹ xɤ³⁵", "syllable_count": 2, "sentences": [{"text": "他们俩不和，一见面就吵架。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王和小李不和，常常吵起来。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸妈妈最近不和，常常吵架。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个邻居不和多年，从不来往。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和室友不和，每天都吵。", "target_word": "不和", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐妹俩不和，为了小事吵了一晚上。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们不和的事，全公司都知道。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说他们两口子不和，总是大声吵。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为钱的事，兄弟两人不和了。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们都知道他和老板不和。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不和：两人关系不好，常吵架", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4282b7-916c-4da7-bd32-a72c5ffbca2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86071, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不和", "is_correct": true, "explanation": "“不和”指两人关系不好、常吵架，与后句“一见面就吵架”相呼应。"}, {"text": "友好", "is_correct": false, "explanation": "语义：“友好”说关系好，与后句“一见面就吵架”矛盾。"}, {"text": "亲密", "is_correct": false, "explanation": "语义：“亲密”说关系很近，与“一见面就吵架”矛盾。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”形容环境或人不出声，不能说两人关系，且与“吵架”矛盾。"}], "explanations": {"不和": "“不和”指两人关系不好、常吵架，与后句“一见面就吵架”相呼应。", "友好": "语义：“友好”说关系好，与后句“一见面就吵架”矛盾。", "亲密": "语义：“亲密”说关系很近，与“一见面就吵架”矛盾。", "安静": "语义：“安静”形容环境或人不出声，不能说两人关系，且与“吵架”矛盾。"}, "sentence_index": 0, "correct_answer": "不和"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这双鞋的大小不和我的脚。", "explanation": "这里应该用〈不合〉。“不和”说人与人之间合不来；鞋的大小与脚是否相合要用“不合”。"}, {"text": "这两份报告的数据互相不和。", "explanation": "这里应该用〈矛盾〉。“不和”说人际关系不好；数据之间的抵触要用“矛盾”。"}, {"text": "这个决定不和，需要重新考虑。", "explanation": "这里应该用〈不妥〉。“不和”只形容人际关系；决定是否恰当要用“不妥”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86071, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不和", "is_correct": true, "explanation": "“不和”指关系不好，用作定语修饰“的事”，与“全公司都知道”相呼应。"}, {"text": "隐蔽", "is_correct": false, "explanation": "语义：“隐蔽”指不让人看见，与“全公司都知道”矛盾。"}, {"text": "隐秘", "is_correct": false, "explanation": "语义：“隐秘”指不公开，与“全公司都知道”矛盾。"}, {"text": "偏僻", "is_correct": false, "explanation": "搭配：“偏僻”形容地方，不能修饰“事”。"}], "explanations": {"不和": "“不和”指关系不好，用作定语修饰“的事”，与“全公司都知道”相呼应。", "隐蔽": "语义：“隐蔽”指不让人看见，与“全公司都知道”矛盾。", "隐秘": "语义：“隐秘”指不公开，与“全公司都知道”矛盾。", "偏僻": "搭配：“偏僻”形容地方，不能修饰“事”。"}, "sentence_index": 6, "correct_answer": "不和"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脾气很不和，大家都躲着他。", "explanation": "这里应该用〈不好〉。“不和”说的是人与人之间合不来，不能用来形容一个人的脾气；脾气差要说“脾气很不好”。"}, {"text": "这个方案的预算很不和，需要重新核算。", "explanation": "这里应该用〈不合理〉。“不和”只形容人与人之间的关系；预算是否恰当要用“不合理”。"}, {"text": "这个数字很不和，需要核对。", "explanation": "这里应该用〈不准确〉。“不和”只形容人与人之间的关系，不能用来形容数字；数字是否准确要用“不准确”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86071, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我和室友了不和，但是我们都很忍让。", "corrected_sentence": "我和室友不和，但是我们都很忍让。", "error_description": "错误形式：“不和”前多加了“了”。“不和”前不能加“了”，这里只是说明两人关系不好，应说“我和室友不和”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86071, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板和我了不和，所以我换了工作。", "corrected_sentence": "老板和我不和，所以我换了工作。", "error_description": "“了”不能放在“不和”前，“了不和”不成词。去掉“了”即可（老板和我不和），也可说“老板和我不和了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
