INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86072, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容词，指彼此感情不好，合不来。", "primary_collocate": null, "pronunciation": "bù hé", "ipa": "pu⁵¹ xɤ³⁵", "syllable_count": 2, "sentences": [{"text": "他们两个人一直不和。", "target_word": "不和", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这对夫妻不和，常常分开住。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥和姐姐从小就不和。", "target_word": "不和", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两家人因为一件小事不和了。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事们不和，工作很难做好。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，家里不和，孩子也不开心。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和邻居不和，见面也不说话。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师发现两个同学不和。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩曾经不和过一阵子，现在很好。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司里领导不和，大家都很担心。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不和：彼此感情不好，合不来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4282b7-916c-4da7-bd32-a72c5ffbca2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86072, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不和", "is_correct": true, "explanation": "“不和”指彼此感情不好、合不来，与“一直”搭配，说明关系长期如此。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”形容场面人多、喧闹，不能用来描述两个人之间的关系。"}, {"text": "拥挤", "is_correct": false, "explanation": "搭配：“拥挤”说人多、空间窄，不能用来形容“两个人”的关系。"}, {"text": "空旷", "is_correct": false, "explanation": "语义：“空旷”形容地方没有人或物，与“他们两个人”的关系无关。"}], "explanations": {"不和": "“不和”指彼此感情不好、合不来，与“一直”搭配，说明关系长期如此。", "热闹": "语义：“热闹”形容场面人多、喧闹，不能用来描述两个人之间的关系。", "拥挤": "搭配：“拥挤”说人多、空间窄，不能用来形容“两个人”的关系。", "空旷": "语义：“空旷”形容地方没有人或物，与“他们两个人”的关系无关。"}, "sentence_index": 0, "correct_answer": "不和"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件外套的尺寸不和我的身材。", "explanation": "这里应该用〈不合〉。“不和”说人与人之间合不来；衣服尺寸与身材是否相合要用“不合”。"}, {"text": "他们俩的说法互相不和。", "explanation": "这里应该用〈矛盾〉。“不和”说人际关系不好；说法之间互相抵触要用“矛盾”。"}, {"text": "这台电脑的零件和主板不和，装不上。", "explanation": "这里应该用〈不合〉。“不和”只形容人与人之间合不来；零件是否相合要用“不合”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86072, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不和", "is_correct": true, "explanation": "“不和”指两人关系不好，与后句“见面也不说话”相呼应。"}, {"text": "亲密", "is_correct": false, "explanation": "语义：“亲密”指关系很近，与后句“见面也不说话”矛盾。"}, {"text": "亲近", "is_correct": false, "explanation": "语义：“亲近”指感情好、往来多，与“见面也不说话”矛盾。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：“热情”形容对人的态度，常说“对…热情”，不说“和…热情”。"}], "explanations": {"不和": "“不和”指两人关系不好，与后句“见面也不说话”相呼应。", "亲密": "语义：“亲密”指关系很近，与后句“见面也不说话”矛盾。", "亲近": "语义：“亲近”指感情好、往来多，与“见面也不说话”矛盾。", "热情": "搭配：“热情”形容对人的态度，常说“对…热情”，不说“和…热情”。"}, "sentence_index": 6, "correct_answer": "不和"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的态度很不和，别人都不喜欢他。", "explanation": "这里应该用〈不友好〉。“不和”说的是人与人之间合不来，不能直接用来形容态度；态度恶劣要用“不友好”。"}, {"text": "这个箱子和门不和，关不上。", "explanation": "这里应该用〈不合〉。“不和”只形容人与人之间合不来；箱子与门是否相合要用“不合”。"}, {"text": "这个办法不和，需要修改。", "explanation": "这里应该用〈不妥〉。“不和”只形容人际关系，办法是否恰当要用“不妥”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86072, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们俩一直不不和，见面就吵。", "corrected_sentence": "他们俩一直不和，见面就吵。", "error_description": "「不和」前多写了一个「不」，构成双重否定，意思与「不和」相反，也与后句「见面就吵」矛盾；删去多余的「不」即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86072, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他和邻居不和着，所以不再一起吃饭。", "corrected_sentence": "他和邻居不和了，所以不再一起吃饭。", "error_description": "“不和”后应用“了”表示关系已经变坏，写成“不和着”是体标用错，应改为“不和了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
