INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86073, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86073, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东方是太阳出来的那一边。", "primary_collocate": null, "pronunciation": "dōng fāng", "ipa": "tʊŋ˥ fɑŋ˥", "syllable_count": 2, "sentences": [{"text": "太阳从东方升起来。", "target_word": "东方", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "早上，东方的天空很红。", "target_word": "东方", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们看着东方，等太阳出来。", "target_word": "东方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天亮了，东方有一片红云。", "target_word": "东方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他早上起得很早，面向东方站着。", "target_word": "东方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳出来的那一边是东方。", "target_word": "东方", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "清早，东方出现了第一道阳光。", "target_word": "东方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夕阳落在西边，明天太阳又会从东方升起。", "target_word": "东方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问：“太阳为什么从东方出来？”", "target_word": "东方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人每天早上对着东方看日出。", "target_word": "东方", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "東方", "label": "繁体"}, {"form": "东方人", "label": "复合词"}], "register": "中性", "sense_fingerprint": "方位名词：太阳升起的那一边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c500fdf8-63d3-43a2-81b5-b65303588367') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86073, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "东方", "is_correct": true, "explanation": "东方是正确答案，指太阳升起的那一边，与“太阳从……升起来”相符。"}, {"text": "西方", "is_correct": false, "explanation": "语义：“西方”指西面，太阳不从西面升起，与“升起来”的方位相反。"}, {"text": "北方", "is_correct": false, "explanation": "语义：“北方”指北面，太阳不从北方升起，与事实不符。"}, {"text": "东西", "is_correct": false, "explanation": "搭配：“东西”指物品，不能表示太阳升起的方位，与“从……升起”搭配不当。"}], "explanations": {"东方": "东方是正确答案，指太阳升起的那一边，与“太阳从……升起来”相符。", "西方": "语义：“西方”指西面，太阳不从西面升起，与“升起来”的方位相反。", "北方": "语义：“北方”指北面，太阳不从北方升起，与事实不符。", "东西": "搭配：“东西”指物品，不能表示太阳升起的方位，与“从……升起”搭配不当。"}, "sentence_index": 0, "correct_answer": "东方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他东方出门去上学了。", "explanation": "这里应该用〈早上〉。东方是方位名词，不表示时间；说出门的时间要用“早上”。"}, {"text": "妈妈把汤倒进了东方里。", "explanation": "这里应该用〈碗〉。东方指方位，不是能盛东西的容器；汤应倒进“碗”里。"}, {"text": "天上飞过一只东方。", "explanation": "这里应该用〈鸟〉。东方是方位名词，不指动物，“一只”后应接“鸟”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86073, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "东方", "is_correct": true, "explanation": "东方是正确答案，指太阳升起的方位，与“清早……出现了第一道阳光”相符。"}, {"text": "南方", "is_correct": false, "explanation": "语义：太阳不从南方升起，“南方”与清早日出的方位不符。"}, {"text": "月亮", "is_correct": false, "explanation": "搭配：“第一道阳光”由太阳发出，不能说“月亮出现了阳光”。"}, {"text": "西边", "is_correct": false, "explanation": "语义：“西边”指西侧，清早的阳光不从西边出现，与日出方位不符。"}], "explanations": {"东方": "东方是正确答案，指太阳升起的方位，与“清早……出现了第一道阳光”相符。", "南方": "语义：太阳不从南方升起，“南方”与清早日出的方位不符。", "月亮": "搭配：“第一道阳光”由太阳发出，不能说“月亮出现了阳光”。", "西边": "语义：“西边”指西侧，清早的阳光不从西边出现，与日出方位不符。"}, "sentence_index": 6, "correct_answer": "东方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他东方地跑进了教室。", "explanation": "这里应该用〈飞快〉。东方是方位名词，不能作状语修饰动词，应说“飞快地”。"}, {"text": "他把书包挂在了东方上。", "explanation": "这里应该用〈墙〉。东方是方位，不是可以挂东西的表面，应说“挂在墙上”。"}, {"text": "一只东方在院子里叫。", "explanation": "这里应该用〈狗〉。东方是方位，不指动物，“一只”后应接“狗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86073, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "晨光从东方边照进了窗户。", "corrected_sentence": "晨光从东方照进了窗户。", "error_description": "错误：在“东方”后面多加了“边”。正确：“东方”本身就是方位词，不再加“边”，应说“从东方照进了窗户”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86073, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "太阳渐渐东方升起了。", "corrected_sentence": "太阳渐渐从东方升起了。", "error_description": "错误：漏掉了介词“从”。正确：表示太阳升起的方向要说“从东方升起”，“东方”前需要“从”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
