INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86075, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“你我”是说你和我两个人。", "primary_collocate": null, "pronunciation": "nǐ wǒ", "ipa": "ni˨˩ wo˨˩", "syllable_count": 2, "sentences": [{"text": "这件事只有你我知道，别告诉别人。", "target_word": "你我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天晚上，屋里只有你我，很安静。", "target_word": "你我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是你我之间的约定。", "target_word": "你我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里没有别人，只有你我。", "target_word": "你我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你我二人今天一起去看电影吧。", "target_word": "你我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们都走了，就剩下你我了。", "target_word": "你我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间小屋太挤，只容得下你我两人。", "target_word": "你我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你我两人的想法很不一样。", "target_word": "你我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些话只是你我之间说说。", "target_word": "你我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你我一组，其他人一组，比赛开始了。", "target_word": "你我", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "确指你和我这两个人，常与“只有、两个人、之间”连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2ce387-de1a-4dee-a2b5-d7f05cb692cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86075, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "你我", "is_correct": true, "explanation": "正确：“你我”确指说话的两个人，与“别告诉别人”配合，句子意思是“只有我们两个知道”。"}, {"text": "大家", "is_correct": false, "explanation": "语义：“大家”包括所有人，与“别告诉别人”矛盾，“只有大家知道”说不通。"}, {"text": "众人", "is_correct": false, "explanation": "语域：“众人”是书面色彩较重的说法，与这句口语化的叮嘱不协调。"}, {"text": "人人", "is_correct": false, "explanation": "语义：“人人”指每一个人，与“只有”的限定意思相反，句子不通。"}], "explanations": {"你我": "正确：“你我”确指说话的两个人，与“别告诉别人”配合，句子意思是“只有我们两个知道”。", "大家": "语义：“大家”包括所有人，与“别告诉别人”矛盾，“只有大家知道”说不通。", "众人": "语域：“众人”是书面色彩较重的说法，与这句口语化的叮嘱不协调。", "人人": "语义：“人人”指每一个人，与“只有”的限定意思相反，句子不通。"}, "sentence_index": 0, "correct_answer": "你我"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你我一个人在家，很无聊。", "explanation": "这里应该用〈我〉。“你我”指两个人，不能与“一个人”搭配，只说自己要用“我”。"}, {"text": "你我一个人来了吗？", "explanation": "这里应该用〈你〉。“你我”指两个人，不能与“一个人”搭配，只问对方要用“你”。"}, {"text": "你我班上有五十个学生。", "explanation": "这里应该用〈我们班〉。“你我”只指两个人，不能指一个有五十个学生的班级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86075, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "你我", "is_correct": true, "explanation": "正确：“你我”确指两人，句子意思是“这间小屋只能容下我们两个人”。"}, {"text": "自己", "is_correct": false, "explanation": "语义：“自己”只指一个人，与句中的“两人”搭配不通，句子说不通。"}, {"text": "大家", "is_correct": false, "explanation": "语义：“大家”指很多人，与“两人”矛盾，“只容得下大家两人”说不通。"}, {"text": "您", "is_correct": false, "explanation": "语义：“您”指对方一人，又是敬称，与“两人”搭配不通，句子也显得生硬。"}], "explanations": {"你我": "正确：“你我”确指两人，句子意思是“这间小屋只能容下我们两个人”。", "自己": "语义：“自己”只指一个人，与句中的“两人”搭配不通，句子说不通。", "大家": "语义：“大家”指很多人，与“两人”矛盾，“只容得下大家两人”说不通。", "您": "语义：“您”指对方一人，又是敬称，与“两人”搭配不通，句子也显得生硬。"}, "sentence_index": 6, "correct_answer": "你我"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你我一个人去就够了，你留在家里吧。", "explanation": "这里应该用〈我〉。“你我”指两个人，不能与“一个人”搭配，而且后面说“你留在家里”，去的只有我自己。"}, {"text": "你我学校有一千名学生。", "explanation": "这里应该用〈我们学校〉。“你我”只指两个人，不能指一所有一千名学生的学校。"}, {"text": "你我全家都很忙，没有时间。", "explanation": "这里应该用〈我们全家〉。“你我”只指两个人，不能指一大家子人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86075, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次旅行只有你我一个人参加。", "corrected_sentence": "这次旅行只有你我两个人参加。", "error_description": "“你我”指两个人，后面的数量要用“两个人”。错误形式是“一个人”，与“你我”的人数不符，正确形式是“两个人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86075, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "只有你我们两个人去过那里。", "corrected_sentence": "只有你我两个人去过那里。", "error_description": "“你我”是固定词，后面不能再加“们”。错误形式是“你我们”，正确形式是“你我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
