INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86076, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "代词，指对方和自己，泛指彼此、大家。", "primary_collocate": null, "pronunciation": "nǐ wǒ", "ipa": "ni˨˩ wo˨˩", "syllable_count": 2, "sentences": [{"text": "在这个社会里，你我都是普通人。", "target_word": "你我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生活不容易，你我都有难处。", "target_word": "你我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好朋友之间，你我不用分得太清楚。", "target_word": "你我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事关系到每个人，你我都有责任。", "target_word": "你我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无论年纪大小，你我都需要朋友。", "target_word": "你我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界这么大，你我能遇见真不容易。", "target_word": "你我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人生很短，你我都应该珍惜时间。", "target_word": "你我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在大自然面前，你我都很小。", "target_word": "你我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也不是完美的，你我都会犯错。", "target_word": "你我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们的未来，和你我每个人都有关系。", "target_word": "你我", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "泛指彼此、大家，常说“你我都……”，表示人人一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2ce387-de1a-4dee-a2b5-d7f05cb692cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86076, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "你我", "is_correct": true, "explanation": "正确：“你我”泛指彼此、大家，句子意思是“在这个社会里，每个人都是普通人”。"}, {"text": "某人", "is_correct": false, "explanation": "语义：“某人”指不确定的一个人，与“都”的总括意思冲突，也不能泛指大家。"}, {"text": "我", "is_correct": false, "explanation": "语义：“我”只指说话的人，不能泛指彼此，句子的意思会变窄。"}, {"text": "他们", "is_correct": false, "explanation": "语义：“他们”指第三方，不包括说话人与听话人，不能泛指“你我”，句意变成在说别人。"}], "explanations": {"你我": "正确：“你我”泛指彼此、大家，句子意思是“在这个社会里，每个人都是普通人”。", "某人": "语义：“某人”指不确定的一个人，与“都”的总括意思冲突，也不能泛指大家。", "我": "语义：“我”只指说话的人，不能泛指彼此，句子的意思会变窄。", "他们": "语义：“他们”指第三方，不包括说话人与听话人，不能泛指“你我”，句意变成在说别人。"}, "sentence_index": 0, "correct_answer": "你我"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你我一个人在家，很无聊。", "explanation": "这里应该用〈我〉。“你我”泛指彼此，包括说话人和听话人，不能与“一个人”搭配。"}, {"text": "你我一家三口都很忙。", "explanation": "这里应该用〈我们〉。“你我”是泛指彼此的说法，不能加具体数量“一家三口”来计数。"}, {"text": "你我公司有一千名员工。", "explanation": "这里应该用〈我们〉。“你我”泛指彼此，不能作定语表示所属单位“公司”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86076, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "你我", "is_correct": true, "explanation": "正确：“你我”泛指彼此，句子意思是“人生很短，大家都应该珍惜时间”。"}, {"text": "某人", "is_correct": false, "explanation": "语义：“某人”指不确定的一个人，与“都”冲突，不能泛指彼此。"}, {"text": "对方", "is_correct": false, "explanation": "语义：“对方”指另一方，不能泛指彼此，与“人生很短”的整体判断不合。"}, {"text": "您", "is_correct": false, "explanation": "语域：“您”是敬称，与这句平等、泛指的口吻不合，读起来生硬。"}], "explanations": {"你我": "正确：“你我”泛指彼此，句子意思是“人生很短，大家都应该珍惜时间”。", "某人": "语义：“某人”指不确定的一个人，与“都”冲突，不能泛指彼此。", "对方": "语义：“对方”指另一方，不能泛指彼此，与“人生很短”的整体判断不合。", "您": "语域：“您”是敬称，与这句平等、泛指的口吻不合，读起来生硬。"}, "sentence_index": 6, "correct_answer": "你我"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你我一家十口人都住在这里。", "explanation": "这里应该用〈我们〉。“你我”泛指彼此，不能加具体数量“一家十口”。"}, {"text": "你我班有三十个学生。", "explanation": "这里应该用〈我们〉。“你我”泛指彼此，不能作定语表示所属单位“班”。"}, {"text": "你我三个人一起去旅行。", "explanation": "这里应该用〈我们〉。“你我”泛指彼此，不能与具体数量“三个人”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86076, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "面对困难，你我们都要坚持下去。", "corrected_sentence": "面对困难，你我都要坚持下去。", "error_description": "“你我”是固定词，后面不能再加“们”。错误形式是“你我们”，正确形式是“你我”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86076, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "遇到困难的时候，都你我应该互相帮助。", "corrected_sentence": "遇到困难的时候，你我都应该互相帮助。", "error_description": "“你我”是句子的主语，副词“都”要放在“你我”后面、动词前面。错误形式是“都你我”，正确形式是“你我都”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
