INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86078, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "某些", "is_correct": true, "explanation": "正确：“某些”指不确定的一部分人，符合句意。"}, {"text": "有点", "is_correct": false, "explanation": "语法：“有点”是副词，不能直接修饰名词“人”，不能说“有点人”。"}, {"text": "已经", "is_correct": false, "explanation": "语法：“已经”是副词，表示时间，不能放在名词“人”前面。"}, {"text": "非常", "is_correct": false, "explanation": "语法：“非常”是程度副词，只能修饰形容词或动词，不能修饰“人”。"}], "explanations": {"某些": "正确：“某些”指不确定的一部分人，符合句意。", "有点": "语法：“有点”是副词，不能直接修饰名词“人”，不能说“有点人”。", "已经": "语法：“已经”是副词，表示时间，不能放在名词“人”前面。", "非常": "语法：“非常”是程度副词，只能修饰形容词或动词，不能修饰“人”。"}, "sentence_index": 0, "correct_answer": "某些"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班某些同学是王明和李华。", "explanation": "这里应该去掉“某些”，直接说具体的人。“某些”只指不确定的一部分，不能说是哪几个，后面也不能列出具体名字。"}, {"text": "某些同学全部到齐了，我们班一共三十人。", "explanation": "这里应该用〈所有〉。“某些”表示不确定的一部分，与“全部到齐”和“一共三十人”指全体的说法矛盾。"}, {"text": "某些人是我的弟弟。", "explanation": "这里应该用〈这个〉。“某些人”指几个不确定的人，不能指一个特定的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983850f8-aa5e-46c1-a983-9f88fd71ecce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86078, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "某些", "is_correct": true, "explanation": "正确：“某些”指书中不确定的一部分句子，符合句意。"}, {"text": "一直", "is_correct": false, "explanation": "语法：“一直”是副词，表示动作持续，不能直接修饰名词“句子”。"}, {"text": "比较", "is_correct": false, "explanation": "语法：“比较”作副词时修饰形容词，不能直接修饰名词“句子”。"}, {"text": "刚才", "is_correct": false, "explanation": "语法：“刚才”表示时间，不能放在“书里”和“句子”之间修饰名词。"}], "explanations": {"某些": "正确：“某些”指书中不确定的一部分句子，符合句意。", "一直": "语法：“一直”是副词，表示动作持续，不能直接修饰名词“句子”。", "比较": "语法：“比较”作副词时修饰形容词，不能直接修饰名词“句子”。", "刚才": "语法：“刚才”表示时间，不能放在“书里”和“句子”之间修饰名词。"}, "sentence_index": 6, "correct_answer": "某些"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "某些国家的人正好三个，我都认识。", "explanation": "这里应该去掉“正好三个”。“某些”不说具体数量，与精确的数量矛盾。"}, {"text": "某些国家是中国，它在亚洲。", "explanation": "这里应该用〈这个国家〉。“某些”指不确定的一部分，不能指明某一个国家。"}, {"text": "某些国家是唯一一个喜欢喝茶的。", "explanation": "这里应该去掉“唯一一个”。“某些”表示不确定的几个，不能与特指一个的说法并列。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983850f8-aa5e-46c1-a983-9f88fd71ecce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86078, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "某些的同学今天没来上课。", "corrected_sentence": "某些同学今天没来上课。", "error_description": "“某些”是代词，后面直接接名词，不能加“的”。错误形式是“某些的同学”，正确形式是“某些同学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983850f8-aa5e-46c1-a983-9f88fd71ecce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
