INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86079, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "毛是动物身上长的细细软软的东西。", "primary_collocate": null, "pronunciation": "máo", "ipa": "maʊ̯˧˥", "syllable_count": 1, "sentences": [{"text": "这只猫的毛很软。", "target_word": "毛", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小狗的毛是白色的。", "target_word": "毛", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "秋天到了，猫的毛变多了。", "target_word": "毛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "兔子的毛又白又软。", "target_word": "毛", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这只羊的毛太长了，要剪一剪。", "target_word": "毛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她抱着小猫，摸着它软软的毛。", "target_word": "毛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的狗每天都掉很多毛。", "target_word": "毛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "熊猫身上的毛是黑白两种颜色的。", "target_word": "毛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天到了，小狗的毛长得又厚又密。", "target_word": "毛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我给猫洗了澡，再把它的毛吹干。", "target_word": "毛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一根毛", "label": "量词"}, {"form": "毛巾", "label": "复合"}], "register": "中性", "sense_fingerprint": "动物身上柔软的毛", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c500fdf8-63d3-43a2-81b5-b65303588367') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86079, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "毛", "is_correct": true, "explanation": "正确：毛（máo，第二声），意思是动物身上细软的毛。"}, {"text": "猫", "is_correct": false, "explanation": "猫（māo，第一声）与 máo 声调不同，意思是猫。"}, {"text": "帽", "is_correct": false, "explanation": "帽（mào，第四声）与 máo 声调不同，意思是帽子。"}, {"text": "忙", "is_correct": false, "explanation": "忙（máng，第二声）与 máo 韵母不同（ang 与 ao），意思是忙碌。"}], "explanations": {"毛": "正确：毛（máo，第二声），意思是动物身上细软的毛。", "猫": "猫（māo，第一声）与 máo 声调不同，意思是猫。", "帽": "帽（mào，第四声）与 máo 声调不同，意思是帽子。", "忙": "忙（máng，第二声）与 máo 韵母不同（ang 与 ao），意思是忙碌。"}, "sentence_index": null, "correct_answer": "毛"}, "level_3": {"options": [{"text": "毛", "is_correct": true, "explanation": "正确：毛指猫身上的毛，符合「这只猫的……很软」的句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头坚硬，与「很软」矛盾，也不是猫身上的部位。"}, {"text": "木头", "is_correct": false, "explanation": "搭配：「猫的木头」不是猫身上的东西，不能这样搭配。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃是硬的，与「很软」矛盾。"}], "explanations": {"毛": "正确：毛指猫身上的毛，符合「这只猫的……很软」的句意。", "石头": "语义：石头坚硬，与「很软」矛盾，也不是猫身上的部位。", "木头": "搭配：「猫的木头」不是猫身上的东西，不能这样搭配。", "玻璃": "语义：玻璃是硬的，与「很软」矛盾。"}, "sentence_index": 0, "correct_answer": "毛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张桌子的毛很光滑。", "explanation": "这里应该用〈表面〉。毛指动物身上长的细丝，不能用来说桌子的表面。"}, {"text": "他用毛写字。", "explanation": "这里应该用〈毛笔〉。毛笔是写字的工具，“毛”单独不能指笔。"}, {"text": "这棵树的毛很多，每年都要修剪一次。", "explanation": "这里应该用〈枝叶〉。树身上没有毛，“毛”只指动物身上长的细软东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86079, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "毛", "is_correct": true, "explanation": "正确：毛（máo，第二声），意思是动物身上细软的毛。"}, {"text": "冒", "is_correct": false, "explanation": "冒（mào，第四声）与 máo 声调不同，意思是冒出、冒险。"}, {"text": "貌", "is_correct": false, "explanation": "貌（mào，第四声）与 máo 声调不同，意思是样子、容貌。"}, {"text": "贸", "is_correct": false, "explanation": "贸（mào，第四声）与 máo 声调不同，意思是贸易。"}, {"text": "盲", "is_correct": false, "explanation": "盲（máng，第二声）与 máo 韵母不同（ang 与 ao），意思是看不见。"}], "explanations": {"毛": "正确：毛（máo，第二声），意思是动物身上细软的毛。", "冒": "冒（mào，第四声）与 máo 声调不同，意思是冒出、冒险。", "貌": "貌（mào，第四声）与 máo 声调不同，意思是样子、容貌。", "贸": "贸（mào，第四声）与 máo 声调不同，意思是贸易。", "盲": "盲（máng，第二声）与 máo 韵母不同（ang 与 ao），意思是看不见。"}, "sentence_index": null, "correct_answer": "毛"}, "level_3": {"options": [{"text": "毛", "is_correct": true, "explanation": "正确：毛指动物身上脱落的毛，符合「……掉很多……」的句意。"}, {"text": "尾巴", "is_correct": false, "explanation": "语义：狗的尾巴不会成批脱落，与「掉很多」不合。"}, {"text": "耳朵", "is_correct": false, "explanation": "搭配：耳朵不会成批掉落，「掉很多耳朵」不成搭配。"}, {"text": "脚", "is_correct": false, "explanation": "语义：狗的脚不会大量脱落，与句意不合。"}], "explanations": {"毛": "正确：毛指动物身上脱落的毛，符合「……掉很多……」的句意。", "尾巴": "语义：狗的尾巴不会成批脱落，与「掉很多」不合。", "耳朵": "搭配：耳朵不会成批掉落，「掉很多耳朵」不成搭配。", "脚": "语义：狗的脚不会大量脱落，与句意不合。"}, "sentence_index": 6, "correct_answer": "毛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条鱼身上长满了亮亮的毛。", "explanation": "这里应该用〈鳞〉。鱼身上长的是鳞，不是毛，“毛”不用于鱼。"}, {"text": "院子里开了一朵毛。", "explanation": "这里应该用〈花〉。毛是动物身上的细丝，不能用来指花。"}, {"text": "妈妈往汤里放了一点毛。", "explanation": "这里应该用〈盐〉。毛是动物身上长的细软的东西，不能放进汤里调味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86079, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "沙发上有一条白色的毛。", "corrected_sentence": "沙发上有一根白色的毛。", "error_description": "错误：“一条毛”；正确：“一根毛”。“毛”的量词是“根”，“条”不能用于这里的毛。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86079, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地毯上落了几只毛。", "corrected_sentence": "地毯上落了几根毛。", "error_description": "错误：“几只毛”；正确：“几根毛”。“毛”的量词是“根”，“只”用于动物，不能用于这里的毛。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
