INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86087, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "立即是马上，一点也不等。", "primary_collocate": null, "pronunciation": "lì jí", "ipa": "li˥˩ t͡ɕi˧˥", "syllable_count": 2, "sentences": [{"text": "你立即过来吧。", "target_word": "立即", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他一听就立即走了。", "target_word": "立即", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我一接到通知，就立即去了学校。", "target_word": "立即", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请大家立即离开这里。", "target_word": "立即", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他知道错了，立即向我道歉。", "target_word": "立即", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看着我，立即明白了我的意思。", "target_word": "立即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，我们立即回到车里。", "target_word": "立即", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子哭了，妈妈立即把他抱了起来。", "target_word": "立即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个药不会立即见效。", "target_word": "立即", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我走进那家店，看到价格太高，立即离开了。", "target_word": "立即", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "马上，毫不拖延地做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c500fdf8-63d3-43a2-81b5-b65303588367') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86087, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "立即", "is_correct": true, "explanation": "立即（lì jí）是正确答案，意思是马上，毫不拖延。"}, {"text": "密集", "is_correct": false, "explanation": "密集 mìjí 与 立即 lìjí 第一个音节声母不同（m 与 l），意思是聚集、稠密。"}, {"text": "市集", "is_correct": false, "explanation": "市集 shìjí 与 立即 lìjí 第一个音节声母不同（sh 与 l），意思是集市。"}, {"text": "利己", "is_correct": false, "explanation": "利己 lìjǐ 与 立即 lìjí 第二个音节声调不同（第三声与第二声），意思是只顾自己的利益。"}, {"text": "亦即", "is_correct": false, "explanation": "亦即 yìjí 与 立即 lìjí 第一个音节声母不同（y 与 l），意思是也就是。"}], "explanations": {"立即": "立即（lì jí）是正确答案，意思是马上，毫不拖延。", "密集": "密集 mìjí 与 立即 lìjí 第一个音节声母不同（m 与 l），意思是聚集、稠密。", "市集": "市集 shìjí 与 立即 lìjí 第一个音节声母不同（sh 与 l），意思是集市。", "利己": "利己 lìjǐ 与 立即 lìjí 第二个音节声调不同（第三声与第二声），意思是只顾自己的利益。", "亦即": "亦即 yìjí 与 立即 lìjí 第一个音节声母不同（y 与 l），意思是也就是。"}, "sentence_index": null, "correct_answer": "立即"}, "level_3": {"options": [{"text": "立即", "is_correct": true, "explanation": "立即是正确答案，表示马上行动，与“你……过来吧”的当下命令相符。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去的经历，与“过来吧”这个当下的命令矛盾。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示动作已经完成，不能用于要求对方去做的“过来吧”。"}, {"text": "刚刚", "is_correct": false, "explanation": "搭配：“刚刚”表示刚发生的事，不能用于要求对方立即行动的祈使句。"}], "explanations": {"立即": "立即是正确答案，表示马上行动，与“你……过来吧”的当下命令相符。", "曾经": "语义：“曾经”指过去的经历，与“过来吧”这个当下的命令矛盾。", "已经": "语义：“已经”表示动作已经完成，不能用于要求对方去做的“过来吧”。", "刚刚": "搭配：“刚刚”表示刚发生的事，不能用于要求对方立即行动的祈使句。"}, "sentence_index": 0, "correct_answer": "立即"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末立即到来。", "explanation": "这里应该用〈即将〉。即将表示快要出现，可以说“周末即将到来”；立即强调动作马上发生，不能与“周末”这样的将来时间连用。"}, {"text": "下周立即考试了。", "explanation": "这里应该用〈快要〉。快要表示即将出现的情况，可以说“下周快要考试了”；立即说的是没有间隔的动作，不能指还没到来的一周。"}, {"text": "我们立即就要到北京了。", "explanation": "这里应该用〈马上〉。“立即”修饰即刻采取的动作，不与“就要……了”这类说将要到来的话搭配；应说“马上就要到北京了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86087, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "立即", "is_correct": true, "explanation": "立即（lì jí）是正确答案，意思是马上，毫不拖延。"}, {"text": "意即", "is_correct": false, "explanation": "意即 yìjí 与 立即 lìjí 第一个音节声母不同（y 与 l），意思是也就是说。"}, {"text": "立基", "is_correct": false, "explanation": "立基 lìjī 与 立即 lìjí 第二个音节声调不同（第一声与第二声），意思是奠定基础。"}, {"text": "例题", "is_correct": false, "explanation": "例题 lìtí 与 立即 lìjí 第二个音节声母不同（t 与 j），意思是举例用的题目。"}, {"text": "力积", "is_correct": false, "explanation": "力积 lìjī 与 立即 lìjí 第二个音节声调不同（第一声与第二声），是物理学术语，意思是冲量。"}], "explanations": {"立即": "立即（lì jí）是正确答案，意思是马上，毫不拖延。", "意即": "意即 yìjí 与 立即 lìjí 第一个音节声母不同（y 与 l），意思是也就是说。", "立基": "立基 lìjī 与 立即 lìjí 第二个音节声调不同（第一声与第二声），意思是奠定基础。", "例题": "例题 lìtí 与 立即 lìjí 第二个音节声母不同（t 与 j），意思是举例用的题目。", "力积": "力积 lìjī 与 立即 lìjí 第二个音节声调不同（第一声与第二声），是物理学术语，意思是冲量。"}, "sentence_index": null, "correct_answer": "立即"}, "level_3": {"options": [{"text": "立即", "is_correct": true, "explanation": "立即是正确答案，表示动作紧接着马上发生，与“下雨了，我们……回到车里”的叙述相符。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”需要与否定词连用，不能用于描述刚发生的动作。"}, {"text": "一边", "is_correct": false, "explanation": "搭配：“一边”需与另一个动作并列使用（一边……一边……），单独用在这里不通。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”表示持续，与“下雨了”之后紧接着回到车里的动作不相符。"}], "explanations": {"立即": "立即是正确答案，表示动作紧接着马上发生，与“下雨了，我们……回到车里”的叙述相符。", "从来": "搭配：“从来”需要与否定词连用，不能用于描述刚发生的动作。", "一边": "搭配：“一边”需与另一个动作并列使用（一边……一边……），单独用在这里不通。", "一直": "语义：“一直”表示持续，与“下雨了”之后紧接着回到车里的动作不相符。"}, "sentence_index": 6, "correct_answer": "立即"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间屋子立即很暖和。", "explanation": "这里应该用〈一直〉。立即表示动作紧接着发生，不能修饰“很暖和”这样的状态；说屋子一直保持暖和要用“一直”。"}, {"text": "这条路立即很宽。", "explanation": "这里应该用〈原来〉。立即只能修饰动作，不能修饰“很宽”这样的状态；说路原本的样子要用“原来”。"}, {"text": "他立即很有名。", "explanation": "这里应该用〈一向〉。立即不能修饰“很有名”这样的状态；说长期如此要用“一向”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86087, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他听到消息，立即的赶了过去。", "corrected_sentence": "他听到消息，立即赶了过去。", "error_description": "错误：副词“立即”后不能直接加“的”来修饰动词。正确：“立即”是副词，直接放在动词前作状语，说“立即赶了过去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86087, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子一哭，妈妈很立即抱起了他。", "corrected_sentence": "孩子一哭，妈妈立即抱起了他。", "error_description": "错误：程度副词“很”修饰了副词“立即”。正确：“立即”本身是副词，不能再加“很”，应说“立即抱起了他”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
