INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86089, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "自我是你自己。", "primary_collocate": null, "pronunciation": "zì wǒ", "ipa": "tsɹ̩˥˩ wo˨˩˦", "syllable_count": 2, "sentences": [{"text": "他在旅行中慢慢找到了自我。", "target_word": "自我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在忙碌的生活里，别忘了自我。", "target_word": "自我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在大城市里，很多人会失去自我。", "target_word": "自我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想做回自我，不再演给别人看。", "target_word": "自我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人常常想认识自我。", "target_word": "自我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他太看重自我，不听别人的话。", "target_word": "自我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读书能让我们更好地认识自我。", "target_word": "自我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲的是怎样找回自我。", "target_word": "自我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他经过努力，终于超越了自我。", "target_word": "自我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的话让我重新看见了自我。", "target_word": "自我", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "指一个人自己", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef952436-ac10-4596-8374-89ff1cbf54ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86089, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "搭配：「找到」不能接「天气」，天气不是可以在旅行中找到的东西。"}, {"text": "运动", "is_correct": false, "explanation": "搭配：「找到」不能接「运动」，句中也没有这样的意思。"}, {"text": "数学", "is_correct": false, "explanation": "语义：「数学」是学科，不是能在旅行中慢慢找到的东西。"}, {"text": "自我", "is_correct": true, "explanation": "正确：「自我」指一个人自己，「找到自我」是自然的说法。"}], "explanations": {"天气": "搭配：「找到」不能接「天气」，天气不是可以在旅行中找到的东西。", "运动": "搭配：「找到」不能接「运动」，句中也没有这样的意思。", "数学": "语义：「数学」是学科，不是能在旅行中慢慢找到的东西。", "自我": "正确：「自我」指一个人自己，「找到自我」是自然的说法。"}, "sentence_index": 0, "correct_answer": "自我"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要把自我的钱存进银行。", "explanation": "这里应该用〈自己的〉，指属于本人的钱；「自我」指人对自己的认识，不能用来修饰「钱」。"}, {"text": "她那自我的蛋糕很好吃。", "explanation": "这里应该用〈自制〉，指自己动手做的；「自我」指人对自己的认识，不能用来说蛋糕是怎么做的。"}, {"text": "她的自我今天很好。", "explanation": "这里应该用〈心情〉，表示情绪状态；「自我」指人对自己的认识，不能用来描述今天的状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86089, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钥匙", "is_correct": false, "explanation": "搭配：「认识」一般指认识人或事物的本质，不说「认识钥匙」。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：电梯是设备，读书不能让人更好地认识它。"}, {"text": "墙壁", "is_correct": false, "explanation": "语义：墙壁是建筑的部件，读书不能让人认识它。"}, {"text": "自我", "is_correct": true, "explanation": "正确：「认识自我」指了解自己，符合句中「读书」的语境。"}], "explanations": {"钥匙": "搭配：「认识」一般指认识人或事物的本质，不说「认识钥匙」。", "电梯": "语义：电梯是设备，读书不能让人更好地认识它。", "墙壁": "语义：墙壁是建筑的部件，读书不能让人认识它。", "自我": "正确：「认识自我」指了解自己，符合句中「读书」的语境。"}, "sentence_index": 6, "correct_answer": "自我"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座房子的自我很大。", "explanation": "这里应该用〈面积〉，指房子占地的大小；「自我」指人对自己的认识，不能用来说房子的大小。"}, {"text": "他的自我很长。", "explanation": "这里应该用〈人生〉，指一个人的生命历程；「自我」不能用来说长短。"}, {"text": "这次活动的自我很好。", "explanation": "这里应该用〈效果〉，指事情产生的结果；「自我」指人对自己的认识，不能用来评价活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86089, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她终于把自我的找回来了。", "corrected_sentence": "她终于把自我找回来了。", "error_description": "「把」字句中，「把」的宾语「自我」后不能加「的」，应为「把自我找回来了」；错误句在「自我」后多加了「的」，句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86089, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他想找回自我自己。", "corrected_sentence": "他想找回自我。", "error_description": "「自我」本身就指自己，后面再加「自己」语义重复，应删去「自己」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
