INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86090, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "自己；也指一个人对自己的认识。", "primary_collocate": null, "pronunciation": "zì wǒ", "ipa": "tsɹ̩˥˩ wo˨˩˦", "syllable_count": 2, "sentences": [{"text": "小孩子长到三岁，开始有了自我。", "target_word": "自我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个人要先了解自我，才能做好选择。", "target_word": "自我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的自我很强，不爱听别人的意见。", "target_word": "自我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写日记可以帮我们看清自我。", "target_word": "自我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在音乐里找到了真正的自我。", "target_word": "自我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作太忙，他很少思考自我。", "target_word": "自我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师希望学生不要放弃自我。", "target_word": "自我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对自我的要求很高。", "target_word": "自我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失败以后，他慢慢接受了自我。", "target_word": "自我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都要学会保护自我。", "target_word": "自我", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "自己，也指人对自己的认识", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef952436-ac10-4596-8374-89ff1cbf54ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86090, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工作", "is_correct": false, "explanation": "语义：三岁的孩子不会有工作。"}, {"text": "驾照", "is_correct": false, "explanation": "语义：三岁的孩子不会有驾照，「开始有了驾照」与成长的语境不符。"}, {"text": "胡子", "is_correct": false, "explanation": "体貌：三岁的孩子不会长胡子，这一说法不符合身体发育的常识。"}, {"text": "自我", "is_correct": true, "explanation": "正确：「有了自我」指开始有自我意识，符合句中的语境。"}], "explanations": {"工作": "语义：三岁的孩子不会有工作。", "驾照": "语义：三岁的孩子不会有驾照，「开始有了驾照」与成长的语境不符。", "胡子": "体貌：三岁的孩子不会长胡子，这一说法不符合身体发育的常识。", "自我": "正确：「有了自我」指开始有自我意识，符合句中的语境。"}, "sentence_index": 0, "correct_answer": "自我"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是我的自我意见。", "explanation": "这里应该用〈个人〉，指属于本人的；「自我」不能修饰「意见」。"}, {"text": "我们要有言论自我。", "explanation": "这里应该用〈自由〉，「言论自由」是固定说法；「自我」不能替换「自由」。"}, {"text": "他的学习自我很认真。", "explanation": "这里应该用〈态度〉，指做事的态度；「自我」不能表示学习的态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86090, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "搭配：「放弃」后接机会、梦想、努力一类，不接「空气」。"}, {"text": "阳光", "is_correct": false, "explanation": "搭配：「放弃」不接「阳光」，句中也没有这样的意思。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空是自然景物，不是可以放弃的对象。"}, {"text": "自我", "is_correct": true, "explanation": "正确：「放弃自我」指放弃自己的本性，符合句中的语境。"}], "explanations": {"空气": "搭配：「放弃」后接机会、梦想、努力一类，不接「空气」。", "阳光": "搭配：「放弃」不接「阳光」，句中也没有这样的意思。", "天空": "语义：天空是自然景物，不是可以放弃的对象。", "自我": "正确：「放弃自我」指放弃自己的本性，符合句中的语境。"}, "sentence_index": 6, "correct_answer": "自我"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家餐厅的自我很好。", "explanation": "这里应该用〈味道〉，指食物的口感；「自我」指人对自己的认识，不能用来评价餐厅的食物。"}, {"text": "这座城市的自我很方便。", "explanation": "这里应该用〈交通〉，指交通状况；「自我」指人对自己的认识，不能用来说城市的便利程度。"}, {"text": "我们要保护自我的环境。", "explanation": "这里应该用〈周围〉，指身边的环境；「自我」指人对自己的认识，不能用来修饰「环境」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86090, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对自我了解越来越深。", "corrected_sentence": "他对自我的了解越来越深。", "error_description": "「自我」作定语修饰「了解」时要加「的」，应为「对自我的了解」；漏掉「的」则不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86090, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他慢慢把自我放了下。", "corrected_sentence": "他慢慢把自我放下了。", "error_description": "动补结构「放下」中，「了」应放在补语之后，即「放下了」；错误句把「了」插在「放」和「下」之间，「放了下」不是合法的说法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86091, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "卸", "is_correct": true, "explanation": "卸与装互为反义：装是放入，卸是取出，二者构成“装卸”的对立。"}, {"text": "吃", "is_correct": false, "explanation": "吃与装没有反义关系，二者意义无关。"}, {"text": "跑", "is_correct": false, "explanation": "跑与装没有反义关系，二者意义无关。"}, {"text": "唱", "is_correct": false, "explanation": "唱与装没有反义关系，二者意义无关。"}], "correct_answer": "卸", "explanations": {"卸": "卸与装互为反义：装是放入，卸是取出，二者构成“装卸”的对立。", "吃": "吃与装没有反义关系，二者意义无关。", "跑": "跑与装没有反义关系，二者意义无关。", "唱": "唱与装没有反义关系，二者意义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86091, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "卸", "is_correct": true, "explanation": "卸与装互为反义：装是放入，卸是取出，二者构成“装卸”的对立。"}, {"text": "说", "is_correct": false, "explanation": "说与装没有反义关系，二者意义无关。"}, {"text": "走", "is_correct": false, "explanation": "走与装没有反义关系，二者意义无关。"}, {"text": "看", "is_correct": false, "explanation": "看与装没有反义关系，二者意义无关。"}], "correct_answer": "卸", "explanations": {"卸": "卸与装互为反义：装是放入，卸是取出，二者构成“装卸”的对立。", "说": "说与装没有反义关系，二者意义无关。", "走": "走与装没有反义关系，二者意义无关。", "看": "看与装没有反义关系，二者意义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86091, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "装是把东西放进盒子或袋子里。", "primary_collocate": null, "pronunciation": "zhuāng", "ipa": "ʈʂwɑŋ˥", "syllable_count": 1, "sentences": [{"text": "老师把作业装进大信封里。", "target_word": "装", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈把饭装进小盒子里。", "target_word": "装", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把玩具装在大袋子里。", "target_word": "装", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个袋子太小，装不下这些书。", "target_word": "装", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把手机装进包里了。", "target_word": "装", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请帮我把糖装进袋子里。", "target_word": "装", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店的人把蛋糕装进纸盒里。", "target_word": "装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个盒子能装十个鸡蛋。", "target_word": "装", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "先把菜装进盒子，再装米饭。", "target_word": "装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把照片装进信封里，寄给了朋友。", "target_word": "装", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "装了", "label": "体标"}, {"form": "装着", "label": "体标"}, {"form": "装进", "label": "动补"}, {"form": "装好", "label": "动补"}], "register": "中性", "sense_fingerprint": "动词：把东西放进盒子、袋子等容器里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c500fdf8-63d3-43a2-81b5-b65303588367') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86091, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "装", "is_correct": true, "explanation": "正确答案：装（zhuāng），把东西放进盒子或袋子里。"}, {"text": "窗", "is_correct": false, "explanation": "声母不同：窗是 chuāng（ch），装是 zhuāng（zh），意思是窗户。"}, {"text": "双", "is_correct": false, "explanation": "声母不同：双是 shuāng（sh），装是 zhuāng（zh），意思是两个、成对。"}, {"text": "撞", "is_correct": false, "explanation": "声调不同：撞是 zhuàng（第四声），装是 zhuāng（第一声），意思是碰撞。"}, {"text": "砖", "is_correct": false, "explanation": "韵母不同：砖是 zhuān（-an），装是 zhuāng（-ang），意思是砖头。"}], "explanations": {"装": "正确答案：装（zhuāng），把东西放进盒子或袋子里。", "窗": "声母不同：窗是 chuāng（ch），装是 zhuāng（zh），意思是窗户。", "双": "声母不同：双是 shuāng（sh），装是 zhuāng（zh），意思是两个、成对。", "撞": "声调不同：撞是 zhuàng（第四声），装是 zhuāng（第一声），意思是碰撞。", "砖": "韵母不同：砖是 zhuān（-an），装是 zhuāng（-ang），意思是砖头。"}, "sentence_index": null, "correct_answer": "装"}, "level_3": {"options": [{"text": "装", "is_correct": true, "explanation": "正确答案：装。句意是把作业放进大信封里，装表示放进容器。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃是把食物送进嘴里，不能说把作业吃进信封里。"}, {"text": "拆", "is_correct": false, "explanation": "语义：拆是打开或分开，不能说把作业拆进信封里。"}, {"text": "洗", "is_correct": false, "explanation": "语义：洗是清洁东西，句子讲的是放入信封，不是清洗。"}], "explanations": {"装": "正确答案：装。句意是把作业放进大信封里，装表示放进容器。", "吃": "语义：吃是把食物送进嘴里，不能说把作业吃进信封里。", "拆": "语义：拆是打开或分开，不能说把作业拆进信封里。", "洗": "语义：洗是清洁东西，句子讲的是放入信封，不是清洗。"}, "sentence_index": 0, "correct_answer": "装"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天冷了，他把大衣装在身上出门了。", "explanation": "这里应该用〈穿〉。装指把东西放进盒子、袋子等容器里，衣服上身要用穿。"}, {"text": "他用石头装住了门口。", "explanation": "这里应该用〈堵〉。装指放进容器，不能用来指挡住门口，挡住通道要用堵。"}, {"text": "他把书装在桌子上，又去做饭了。", "explanation": "这里应该用〈放〉。装指把东西放进盒子、袋子等容器里，放在桌面上要用放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86091, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "装", "is_correct": true, "explanation": "正确答案：装（zhuāng），把东西放进盒子或袋子里。"}, {"text": "张", "is_correct": false, "explanation": "韵母不同：张是 zhāng，没有 u 介音，装是 zhuāng，意思是张开、量词。"}, {"text": "霜", "is_correct": false, "explanation": "声母不同：霜是 shuāng（sh），装是 zhuāng（zh），意思是霜。"}, {"text": "壮", "is_correct": false, "explanation": "声调不同：壮是 zhuàng（第四声），装是 zhuāng（第一声），意思是强壮。"}, {"text": "状", "is_correct": false, "explanation": "声调不同：状是 zhuàng（第四声），装是 zhuāng（第一声），意思是形状、状态。"}], "explanations": {"装": "正确答案：装（zhuāng），把东西放进盒子或袋子里。", "张": "韵母不同：张是 zhāng，没有 u 介音，装是 zhuāng，意思是张开、量词。", "霜": "声母不同：霜是 shuāng（sh），装是 zhuāng（zh），意思是霜。", "壮": "声调不同：壮是 zhuàng（第四声），装是 zhuāng（第一声），意思是强壮。", "状": "声调不同：状是 zhuàng（第四声），装是 zhuāng（第一声），意思是形状、状态。"}, "sentence_index": null, "correct_answer": "装"}, "level_3": {"options": [{"text": "装", "is_correct": true, "explanation": "正确答案：装。句意是把蛋糕放进纸盒里，装表示放进容器。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬是用牙齿夹住东西，不能说把蛋糕咬进纸盒里。"}, {"text": "熬", "is_correct": false, "explanation": "搭配：熬多接“夜”“苦”等，不说“熬进纸盒里”。"}, {"text": "哭", "is_correct": false, "explanation": "语义：哭是流泪，与把蛋糕放进纸盒的动作完全无关。"}], "explanations": {"装": "正确答案：装。句意是把蛋糕放进纸盒里，装表示放进容器。", "咬": "语义：咬是用牙齿夹住东西，不能说把蛋糕咬进纸盒里。", "熬": "搭配：熬多接“夜”“苦”等，不说“熬进纸盒里”。", "哭": "语义：哭是流泪，与把蛋糕放进纸盒的动作完全无关。"}, "sentence_index": 6, "correct_answer": "装"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她每天早上给花装水。", "explanation": "这里应该用〈浇〉。给花浇水不是放进容器，不能用装。"}, {"text": "她把玩偶装在桌上，很可爱。", "explanation": "这里应该用〈摆〉。装指放进容器，不能说把玩偶装在桌上，把物品放在桌上要用摆。"}, {"text": "她用笔在纸上装了几个字。", "explanation": "这里应该用〈写〉。装指把东西放进容器，在纸上写字不能用装。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86091, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个箱子装得不下所有的衣服。", "corrected_sentence": "这个箱子装不下所有的衣服。", "error_description": "否定位置错误：可能补语的否定要说“装不下”，“不”紧接在“装”后；不说“装得不下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86091, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把饺子都装了好，就出门了。", "corrected_sentence": "我把饺子都装好了，就出门了。", "error_description": "结果补语位置错误：“好”是结果补语，应紧跟在“装”后面，说“装好了”，不说“装了好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
