INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86093, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "“对了”是想起一件事，或者说别人说得对。", "primary_collocate": null, "pronunciation": "duì le", "ipa": "tweɪ˥˩ lə", "syllable_count": 2, "sentences": [{"text": "对了，我今天还要去买菜。", "target_word": "对了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对了，你明天有时间吗？", "target_word": "对了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对了，我的手机放在哪儿了？", "target_word": "对了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对了，老师说明天要考试。", "target_word": "对了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对了，上次你说的那本书叫什么？", "target_word": "对了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他问：“你是不是姓王？”我说：“对了。”", "target_word": "对了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“今天是星期五吧？”“对了，是星期五。”", "target_word": "对了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对了，别忘了带伞，外面在下雨。", "target_word": "对了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对了，我还没给妈妈打电话呢。", "target_word": "对了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“你是说明天开会？”“对了，下午三点。”", "target_word": "对了", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "忽然想起一件事时的话头，或回答别人“你说得对”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2ce387-de1a-4dee-a2b5-d7f05cb692cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86093, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "对了", "is_correct": true, "explanation": "对了：叹词，读 duì le，表示忽然想起一件事，或肯定对方说得对。"}, {"text": "堆了", "is_correct": false, "explanation": "duī（第一声）与 duì（第四声）声调不同，意思是堆积、堆起来。"}, {"text": "退了", "is_correct": false, "explanation": "tuì 与 duì 声母不同（t 与 d），意思是退出、退还。"}, {"text": "碎了", "is_correct": false, "explanation": "suì 与 duì 声母不同（s 与 d），意思是打碎了。"}], "explanations": {"对了": "对了：叹词，读 duì le，表示忽然想起一件事，或肯定对方说得对。", "堆了": "duī（第一声）与 duì（第四声）声调不同，意思是堆积、堆起来。", "退了": "tuì 与 duì 声母不同（t 与 d），意思是退出、退还。", "碎了": "suì 与 duì 声母不同（s 与 d），意思是打碎了。"}, "sentence_index": null, "correct_answer": "对了"}, "level_3": {"options": [{"text": "对了", "is_correct": true, "explanation": "对了：叹词，表示忽然想起一件事，正合此句引出的新话题。"}, {"text": "哈哈", "is_correct": false, "explanation": "语义：哈哈表示笑声，句中没有可笑之处，与平常的提醒语气不合。"}, {"text": "呸", "is_correct": false, "explanation": "语域：呸表示鄙视或唾弃，口气过重，不适合平和地提醒自己要去买菜。"}, {"text": "嘘", "is_correct": false, "explanation": "语义：嘘是让人安静的声音，句中并无需要安静之处，与这里想起事情不合。"}], "explanations": {"对了": "对了：叹词，表示忽然想起一件事，正合此句引出的新话题。", "哈哈": "语义：哈哈表示笑声，句中没有可笑之处，与平常的提醒语气不合。", "呸": "语域：呸表示鄙视或唾弃，口气过重，不适合平和地提醒自己要去买菜。", "嘘": "语义：嘘是让人安静的声音，句中并无需要安静之处，与这里想起事情不合。"}, "sentence_index": 0, "correct_answer": "对了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "“这个方法行吗？”“对了，这个方法不行。”", "explanation": "这里的“对了”表示肯定对方的话，后面却说“不行”，前后矛盾。否定应用〈不对〉，“对了”只用于肯定或想起事情。"}, {"text": "“他去过北京吗？”“对了，他从来没去过。”", "explanation": "这里的“对了”表示肯定或想起，后面说“从来没去过”，前后矛盾。应该用〈没有〉直接否定，不能用“对了”。"}, {"text": "“这个数字对吗？”“对了，这个数字有问题。”", "explanation": "这里的“对了”表示肯定对方的说法，后面却说“有问题”，前后矛盾。应该用〈不对〉否定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86093, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对了", "is_correct": true, "explanation": "对了：叹词，表示肯定对方的说法，正合这里的确认。"}, {"text": "嘘", "is_correct": false, "explanation": "语义：嘘是让人安静的声音，不能用来确认对方的话。"}, {"text": "嗨", "is_correct": false, "explanation": "语义：嗨是招呼或引起注意的声音，不用来回答对方的确认，与此句不合。"}, {"text": "哼", "is_correct": false, "explanation": "语义：哼表示不屑或不满，句中并无不满之处，与平淡的确认不合。"}], "explanations": {"对了": "对了：叹词，表示肯定对方的说法，正合这里的确认。", "嘘": "语义：嘘是让人安静的声音，不能用来确认对方的话。", "嗨": "语义：嗨是招呼或引起注意的声音，不用来回答对方的确认，与此句不合。", "哼": "语义：哼表示不屑或不满，句中并无不满之处，与平淡的确认不合。"}, "sentence_index": 6, "correct_answer": "对了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "“你几岁？”“对了，我二十岁。”", "explanation": "这里误用了“对了”，它表示肯定或想起，不用于回答特指问句。问年龄时应直接说出数字。"}, {"text": "“你是老师吗？”“对了，我是学生。”", "explanation": "这里误用了“对了”，它表示肯定对方的说法，后面却说“我是学生”，前后矛盾。否定应直接说〈不是〉。"}, {"text": "“你好！”“对了，你好！”", "explanation": "这里误用了“对了”，它表示肯定或想起。回应问候时应直接问候对方，不用“对了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86093, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "对了的，我的雨伞放在门口。", "corrected_sentence": "对了，我的雨伞放在门口。", "error_description": "“对了”是叹词，后面加“的”成“对了的”，不成词，是错误的。想起一件事时直接说“对了”，不能在后面加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86093, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "“你是老师吧？”“不对了，我是老师。”", "corrected_sentence": "“你是老师吧？”“对了，我是老师。”", "error_description": "“对了”表示肯定对方的说法，前面加“不”变成“不对了”，意思是“已经不正确了”，不能用来否定对方的问话。否定应说“不是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
