INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86094, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "表示忽然想起某事而插话，或表示同意、肯定对方的话。", "primary_collocate": null, "pronunciation": "duì le", "ipa": "tweɪ˥˩ lə", "syllable_count": 2, "sentences": [{"text": "对了，你还没告诉我你的名字呢。", "target_word": "对了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们快到了，对了，你带钥匙了吗？", "target_word": "对了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭的时候他说：“对了，明天放假。”", "target_word": "对了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“你的意思是明天出发？”“对了，就是这个意思。”", "target_word": "对了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“这道题选B吧？”“对了，答案是B。”", "target_word": "对了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对了，昨天的作业你做完了吗？", "target_word": "对了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说到旅行，对了，我下个月要去北京。", "target_word": "对了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“你就是新来的同学吧？”“对了，我叫小李。”", "target_word": "对了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对了，钱包还在桌子上。", "target_word": "对了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对了，周末的会议改到下午了。", "target_word": "对了", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "插话引出新话题，或肯定对方的猜测、说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2ce387-de1a-4dee-a2b5-d7f05cb692cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86094, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "对了", "is_correct": true, "explanation": "对了：叹词，读 duì le，表示忽然想起某事而插话，或肯定对方的说法。"}, {"text": "堆了", "is_correct": false, "explanation": "duī（第一声）与 duì（第四声）声调不同，意思是堆积、堆起来。"}, {"text": "退了", "is_correct": false, "explanation": "tuì 与 duì 声母不同（t 与 d），意思是退出、退还。"}, {"text": "碎了", "is_correct": false, "explanation": "suì 与 duì 声母不同（s 与 d），意思是打碎了。"}], "explanations": {"对了": "对了：叹词，读 duì le，表示忽然想起某事而插话，或肯定对方的说法。", "堆了": "duī（第一声）与 duì（第四声）声调不同，意思是堆积、堆起来。", "退了": "tuì 与 duì 声母不同（t 与 d），意思是退出、退还。", "碎了": "suì 与 duì 声母不同（s 与 d），意思是打碎了。"}, "sentence_index": null, "correct_answer": "对了"}, "level_3": {"options": [{"text": "对了", "is_correct": true, "explanation": "对了：叹词，表示忽然想起一件事，正合此句引出的补充。"}, {"text": "哈哈", "is_correct": false, "explanation": "语义：哈哈表示笑声，句中是在追问对方的名字，没有可笑之处。"}, {"text": "呸", "is_correct": false, "explanation": "语域：呸表示鄙视，口气过重，不适合用来提醒对方补充信息。"}, {"text": "嘘", "is_correct": false, "explanation": "语义：嘘是让人安静的声音，句中并无需要安静之处，与这里的插话不合。"}], "explanations": {"对了": "对了：叹词，表示忽然想起一件事，正合此句引出的补充。", "哈哈": "语义：哈哈表示笑声，句中是在追问对方的名字，没有可笑之处。", "呸": "语域：呸表示鄙视，口气过重，不适合用来提醒对方补充信息。", "嘘": "语义：嘘是让人安静的声音，句中并无需要安静之处，与这里的插话不合。"}, "sentence_index": 0, "correct_answer": "对了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "“你是学生吗？”“对了，我是老师。”", "explanation": "这里的“对了”表示肯定对方的话，后面却说身份不同，前后矛盾。否定应用〈不是〉，不能用“对了”。"}, {"text": "“这个计划可行吗？”“对了，这个计划不可行。”", "explanation": "这里的“对了”表示肯定对方的说法，后面却说“不可行”，前后矛盾。应该用〈不对〉否定。"}, {"text": "“这个答案正确吗？”“对了，这个答案有问题。”", "explanation": "这里的“对了”表示肯定，后面说“有问题”，前后矛盾。应该用〈不对〉否定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86094, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对了", "is_correct": true, "explanation": "对了：叹词，表示忽然想起一件事，正合“说到旅行”之后的转折。"}, {"text": "唉", "is_correct": false, "explanation": "语义：唉表示叹息或无奈，句中是平和地转换话题，并无叹息之意。"}, {"text": "嗨", "is_correct": false, "explanation": "语义：嗨是招呼或引起注意的声音，不表示转换话题，与此句不合。"}, {"text": "哼", "is_correct": false, "explanation": "语义：哼表示不屑或不满，句中并无此意，与平和的话题转换不合。"}], "explanations": {"对了": "对了：叹词，表示忽然想起一件事，正合“说到旅行”之后的转折。", "唉": "语义：唉表示叹息或无奈，句中是平和地转换话题，并无叹息之意。", "嗨": "语义：嗨是招呼或引起注意的声音，不表示转换话题，与此句不合。", "哼": "语义：哼表示不屑或不满，句中并无此意，与平和的话题转换不合。"}, "sentence_index": 6, "correct_answer": "对了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "“你叫什么？”“对了，我叫小王。”", "explanation": "这里误用了“对了”，它表示肯定或想起，不用于回答特指问句。问名字时应直接说出名字。"}, {"text": "“请你坐下。”“对了，我不同意。”", "explanation": "这里误用了“对了”，它表示肯定或想起，后面却说“我不同意”，前后矛盾。对方提出请求应回应〈好〉或〈不〉。"}, {"text": "“早上好！”“对了，早上好！”", "explanation": "这里误用了“对了”，它表示肯定或想起。回应问候时应直接问候对方，不用“对了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86094, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "对了的，我今天没带伞。", "corrected_sentence": "对了，我今天没带伞。", "error_description": "“对了”是叹词，后面加“的”成“对了的”，不成词，是错误的。忽然想起或肯定对方时直接说“对了”，不能在后面加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86094, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "“你是医生吗？”“不对了，我是医生。”", "corrected_sentence": "“你是医生吗？”“对了，我是医生。”", "error_description": "“对了”表示肯定对方的说法，前面加“不”变成“不对了”，意思是“已经不正确了”，不能用来回答问句。肯定地回答应说“对了”，否定应说“不是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
