INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86095, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "民主是大家一起商量事情，每个人都可以说自己的想法。", "primary_collocate": null, "pronunciation": "mín zhǔ", "ipa": "min˧˥ ʈ͡ʂu˨˩", "syllable_count": 2, "sentences": [{"text": "我们家有事大家商量，这就是民主。", "target_word": "民主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会的时候，老师讲民主，让每个人都说话。", "target_word": "民主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民主就是大家一起商量事情。", "target_word": "民主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "班里定活动计划，我们用民主的办法。", "target_word": "民主", "complexity_tier": "T3", "furigana": "mín zhǔ", "sentence_source": "generated"}, {"text": "爸爸说，家里要有民主，孩子也能发表意见。", "target_word": "民主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小组讨论要讲民主，不能只听一个人的。", "target_word": "民主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家投票决定去哪儿玩，这是民主的做法。", "target_word": "民主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有民主的公司，每个人都能说想法。", "target_word": "民主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我喜欢这个班，因为班里有民主。", "target_word": "民主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "民主让每个人都有机会说出自己的想法。", "target_word": "民主", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "大家一起商量，每个人都能发表想法的做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60f41c19-c9f1-4287-85b2-aea15cba001d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86095, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "独裁", "is_correct": false, "explanation": "语义：“独裁”是一个人说了算，与“大家商量”的意思相反。"}, {"text": "争吵", "is_correct": false, "explanation": "语义：“争吵”是吵架，与“大家商量”的意思不同。"}, {"text": "命令", "is_correct": false, "explanation": "搭配：“命令”是上级对下级的指示，不能和“大家商量”并列。"}, {"text": "民主", "is_correct": true, "explanation": "正确。“民主”指大家一起商量事情，与“大家商量”一致。"}], "explanations": {"独裁": "语义：“独裁”是一个人说了算，与“大家商量”的意思相反。", "争吵": "语义：“争吵”是吵架，与“大家商量”的意思不同。", "命令": "搭配：“命令”是上级对下级的指示，不能和“大家商量”并列。", "民主": "正确。“民主”指大家一起商量事情，与“大家商量”一致。"}, "sentence_index": 0, "correct_answer": "民主"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班里的黑板很民主。", "explanation": "这里应该用〈干净〉。“民主”形容制度或作风，不能形容黑板的状态。"}, {"text": "班里有一本民主。", "explanation": "这里应该用〈种〉。“民主”不用“本”计量，常说“一种民主”。"}, {"text": "妈妈把民主送给了朋友。", "explanation": "“民主”是作风或做法，不能像物品一样送给别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86095, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专制", "is_correct": false, "explanation": "语义：“专制”是一个人决定，与“大家投票决定”矛盾。"}, {"text": "独断", "is_correct": false, "explanation": "语义：“独断”是不听别人意见，与“大家投票”矛盾。"}, {"text": "霸道", "is_correct": false, "explanation": "语义：“霸道”是一个人强行决定，与“大家投票决定”矛盾。"}, {"text": "民主", "is_correct": true, "explanation": "正确。“民主的做法”指大家投票决定，与句子的意思一致。"}], "explanations": {"专制": "语义：“专制”是一个人决定，与“大家投票决定”矛盾。", "独断": "语义：“独断”是不听别人意见，与“大家投票”矛盾。", "霸道": "语义：“霸道”是一个人强行决定，与“大家投票决定”矛盾。", "民主": "正确。“民主的做法”指大家投票决定，与句子的意思一致。"}, "sentence_index": 6, "correct_answer": "民主"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把民主放进了冰箱。", "explanation": "“民主”指制度或作风，不是实物，不能放进冰箱。"}, {"text": "他用民主修好了自行车。", "explanation": "“民主”不是工具，不能用来修东西。"}, {"text": "他很民主地吃了一碗饭。", "explanation": "这里应该用〈快〉。“民主”形容决策或作风，不能修饰“吃饭”这样的动作；形容吃得快应说“很快地吃了一碗饭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86095, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班用民主地方法定计划。", "corrected_sentence": "我们班用民主的方法定计划。", "error_description": "错误：“民主”修饰名词“方法”时要用“的”，不能用“地”。正确：应说“民主的方法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86095, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次选班长，我们用民主了的方式。", "corrected_sentence": "这次选班长，我们用民主的方式。", "error_description": "错误：“民主”和“的”之间不能插入“了”。正确：应说“民主的方式”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86096, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "专制", "is_correct": true, "explanation": "正确。“专制”指一人说了算，与“民主”相对。"}, {"text": "河流", "is_correct": false, "explanation": "“河流”是地理事物，与“民主”没有反义关系。"}, {"text": "森林", "is_correct": false, "explanation": "“森林”是自然事物，与“民主”没有反义关系。"}, {"text": "石头", "is_correct": false, "explanation": "“石头”是实物，与“民主”的任何意义都没有反义关系。"}], "correct_answer": "专制", "explanations": {"专制": "正确。“专制”指一人说了算，与“民主”相对。", "河流": "“河流”是地理事物，与“民主”没有反义关系。", "森林": "“森林”是自然事物，与“民主”没有反义关系。", "石头": "“石头”是实物，与“民主”的任何意义都没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86096, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "专制", "is_correct": true, "explanation": "正确。“专制”指一人说了算，与“民主”相对。"}, {"text": "大海", "is_correct": false, "explanation": "“大海”是地理事物，与“民主”没有反义关系。"}, {"text": "草地", "is_correct": false, "explanation": "“草地”是地理事物，与“民主”没有反义关系。"}, {"text": "玻璃", "is_correct": false, "explanation": "“玻璃”是材料，与“民主”的任何意义都没有反义关系。"}], "correct_answer": "专制", "explanations": {"专制": "正确。“专制”指一人说了算，与“民主”相对。", "大海": "“大海”是地理事物，与“民主”没有反义关系。", "草地": "“草地”是地理事物，与“民主”没有反义关系。", "玻璃": "“玻璃”是材料，与“民主”的任何意义都没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86096, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人民可以参与国家或集体事务的决定的制度和作风。", "primary_collocate": null, "pronunciation": "mín zhǔ", "ipa": "min˧˥ ʈ͡ʂu˨˩", "syllable_count": 2, "sentences": [{"text": "这个国家实行民主制度。", "target_word": "民主", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "民主的意思是人民可以参与决定国家大事。", "target_word": "民主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司里有民主，大家都能说出自己的想法。", "target_word": "民主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校选班长是民主的做法。", "target_word": "民主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直在为民主努力。", "target_word": "民主", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "民主需要每个人都认真投票。", "target_word": "民主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老师很讲民主，不会自己一个人做决定。", "target_word": "民主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个国家，民主已经有一百多年的历史了。", "target_word": "民主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们可以投票选校长，这就是民主。", "target_word": "民主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他认为没有民主，人民就没有说话的机会。", "target_word": "民主", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人民参与国家或集体事务决定的制度和作风", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60f41c19-c9f1-4287-85b2-aea15cba001d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86096, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "民生", "is_correct": false, "explanation": "语义：“民生”指百姓的生计，不是可以“实行”的制度。"}, {"text": "民众", "is_correct": false, "explanation": "语义：“民众”指群众，不是制度，不能说“实行民众制度”。"}, {"text": "民权", "is_correct": false, "explanation": "搭配：“实行”与“民权”不搭配，应说“保障民权”。"}, {"text": "民主", "is_correct": true, "explanation": "正确。“民主”指人民参与决定的制度，可以说“实行民主制度”。"}], "explanations": {"民生": "语义：“民生”指百姓的生计，不是可以“实行”的制度。", "民众": "语义：“民众”指群众，不是制度，不能说“实行民众制度”。", "民权": "搭配：“实行”与“民权”不搭配，应说“保障民权”。", "民主": "正确。“民主”指人民参与决定的制度，可以说“实行民主制度”。"}, "sentence_index": 0, "correct_answer": "民主"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我爸爸是一个民主。", "explanation": "“民主”指制度或作风，不指人，这里说的是人，用法不对。"}, {"text": "他一个人民主地做完了作业。", "explanation": "这里应该用〈认真〉。“民主”描述决策或作风，需要多人参与，不能修饰“一个人做作业”这样的个人行为；应说“他认真地做完了作业”。"}, {"text": "这个杯子很民主。", "explanation": "这里应该用〈漂亮〉。“民主”形容制度或作风，不能用来形容杯子的外观；形容杯子好看应说“漂亮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86096, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集权", "is_correct": false, "explanation": "搭配：“讲”后不接“集权”这类表示权力集中的词，“很讲集权”不成立。"}, {"text": "独裁", "is_correct": false, "explanation": "语义：“独裁”是一人说了算，与“不会自己一个人做决定”矛盾。"}, {"text": "专制", "is_correct": false, "explanation": "搭配：“讲”后面多接道理、卫生、礼貌等，“专制”不能用“讲”来修饰。"}, {"text": "民主", "is_correct": true, "explanation": "正确。“很讲民主”指做事讲究大家商量，与后半句的意思一致。"}], "explanations": {"集权": "搭配：“讲”后不接“集权”这类表示权力集中的词，“很讲集权”不成立。", "独裁": "语义：“独裁”是一人说了算，与“不会自己一个人做决定”矛盾。", "专制": "搭配：“讲”后面多接道理、卫生、礼貌等，“专制”不能用“讲”来修饰。", "民主": "正确。“很讲民主”指做事讲究大家商量，与后半句的意思一致。"}, "sentence_index": 6, "correct_answer": "民主"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了两斤民主。", "explanation": "“民主”指制度或作风，不是可以称重买卖的东西，不能用“斤”计量。"}, {"text": "我们要民主一致，共同努力。", "explanation": "这里应该用〈团结〉。“团结一致”是固定说法，表示大家同心；“民主”指制度或作风，不能和“一致”搭配。"}, {"text": "他把民主装进了书包。", "explanation": "“民主”指制度或作风，不是实物，不能装进书包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86096, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一个很民主国家。", "corrected_sentence": "这是一个很民主的国家。", "error_description": "错误：“很民主”修饰名词“国家”时漏掉了“的”。正确：应说“很民主的国家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86096, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们建立了民主地制度。", "corrected_sentence": "他们建立了民主的制度。", "error_description": "错误：修饰名词“制度”时用了“地”。“地”用于修饰动词，修饰名词应用“的”。正确：应说“民主的制度”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
