INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86098, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86098, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示超出某个范围，相当于不仅。", "primary_collocate": null, "pronunciation": "bù zhǐ", "ipa": "pu˥˩ ʈʂʅ˨˩˦", "syllable_count": 2, "sentences": [{"text": "不只我一个人想去，大家都想去。", "target_word": "不只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法不只好用，还很便宜。", "target_word": "不只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不只会说中文，还会说日语。", "target_word": "不只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不只小孩喜欢这首歌，大人也喜欢。", "target_word": "不只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市不只春天漂亮，秋天也很漂亮。", "target_word": "不只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不只学生要早起，老师也要早起。", "target_word": "不只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不只写得好，画得也很好。", "target_word": "不只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不只中国人过春节，很多国家的人也过春节。", "target_word": "不只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆不只菜好吃，服务也很好。", "target_word": "不只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不只自己来了，还带来了朋友。", "target_word": "不只", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不只…，还/也/都…：相当于不仅，表示超出某个范围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed69058d-24aa-4c07-bc40-36884250d128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86098, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不只", "is_correct": true, "explanation": "正确：不只（bù zhǐ），相当于“不仅”，表示超出某个范围。"}, {"text": "不知", "is_correct": false, "explanation": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是“不知道”。"}, {"text": "布置", "is_correct": false, "explanation": "末字 zhì（第四声）与 zhǐ（第三声）声调不同，意思是“布置、安排”。"}, {"text": "不至", "is_correct": false, "explanation": "末字 zhì（第四声）与 zhǐ（第三声）声调不同，意思是“达不到、不会到”。"}, {"text": "不治", "is_correct": false, "explanation": "末字 zhì（第四声）与 zhǐ（第三声）声调不同，意思是“无法医治”。"}], "explanations": {"不只": "正确：不只（bù zhǐ），相当于“不仅”，表示超出某个范围。", "不知": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是“不知道”。", "布置": "末字 zhì（第四声）与 zhǐ（第三声）声调不同，意思是“布置、安排”。", "不至": "末字 zhì（第四声）与 zhǐ（第三声）声调不同，意思是“达不到、不会到”。", "不治": "末字 zhì（第四声）与 zhǐ（第三声）声调不同，意思是“无法医治”。"}, "sentence_index": null, "correct_answer": "不只"}, "level_3": {"options": [{"text": "并且", "is_correct": false, "explanation": "搭配：“并且”连接动词或小句，不能放在句首直接接“我一个人”。"}, {"text": "只有", "is_correct": false, "explanation": "语义：“只有”表示唯一，后面的“大家都想去”与之矛盾，句意不通。"}, {"text": "不只", "is_correct": true, "explanation": "正确：“不只……”表示超出范围，与后句“大家都想去”呼应。"}, {"text": "而是", "is_correct": false, "explanation": "搭配：“而是”前面要有“不是”，这句话没有否定词，不能直接使用。"}], "explanations": {"并且": "搭配：“并且”连接动词或小句，不能放在句首直接接“我一个人”。", "只有": "语义：“只有”表示唯一，后面的“大家都想去”与之矛盾，句意不通。", "不只": "正确：“不只……”表示超出范围，与后句“大家都想去”呼应。", "而是": "搭配：“而是”前面要有“不是”，这句话没有否定词，不能直接使用。"}, "sentence_index": 0, "correct_answer": "不只"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "不只天气好，我们才去爬山。", "explanation": "这里应该用〈只有〉。“只有……才……”表示条件，“不只”表示递进，不能表示条件。"}, {"text": "我很累，不只没有休息。", "explanation": "这里应该用〈但是〉。前后是转折关系，“不只”只表示递进，不能表示转折。"}, {"text": "我很想帮忙，不只没有力气。", "explanation": "这里应该用〈不过〉。“不只”表示递进，前后要有相加的内容；这里前后是转折，应该用“不过”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86098, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不只", "is_correct": true, "explanation": "正确：不只（bù zhǐ），相当于“不仅”，表示超出某个范围。"}, {"text": "不值", "is_correct": false, "explanation": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是“不值得”。"}, {"text": "不直", "is_correct": false, "explanation": "末字 zhí（第二声）与 zhǐ（第三声）声调不同，意思是“不笔直”。"}, {"text": "不致", "is_correct": false, "explanation": "末字 zhì（第四声）与 zhǐ（第三声）声调不同，意思是“不会导致”。"}], "explanations": {"不只": "正确：不只（bù zhǐ），相当于“不仅”，表示超出某个范围。", "不值": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是“不值得”。", "不直": "末字 zhí（第二声）与 zhǐ（第三声）声调不同，意思是“不笔直”。", "不致": "末字 zhì（第四声）与 zhǐ（第三声）声调不同，意思是“不会导致”。"}, "sentence_index": null, "correct_answer": "不只"}, "level_3": {"options": [{"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果结论，句中没有前因，后面“画得也很好”是并列补充，句意不通。"}, {"text": "以及", "is_correct": false, "explanation": "搭配：“以及”连接名词性成分，不能用来连接“她”和“写得好”这样的谓词性结构。"}, {"text": "不只", "is_correct": true, "explanation": "正确：“不只……，……也……”表示超出范围，与后面的“画得也很好”呼应。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”引出结论，前面没有原因，与并列补充的意思不符。"}], "explanations": {"所以": "语义：“所以”表示因果结论，句中没有前因，后面“画得也很好”是并列补充，句意不通。", "以及": "搭配：“以及”连接名词性成分，不能用来连接“她”和“写得好”这样的谓词性结构。", "不只": "正确：“不只……，……也……”表示超出范围，与后面的“画得也很好”呼应。", "因此": "语义：“因此”引出结论，前面没有原因，与并列补充的意思不符。"}, "sentence_index": 6, "correct_answer": "不只"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的菜很好，不只很便宜。", "explanation": "这里应该用〈而且〉。“不只”用于超出范围的补充，前后要有相配的成分，“很便宜”接在逗号后不构成这种关系。"}, {"text": "不只大家一起努力，就能成功。", "explanation": "这里应该用〈只要〉。“只要……就……”表示条件，“不只”表示递进，不能表示条件。"}, {"text": "他很努力，不只没有成功。", "explanation": "这里应该用〈但是〉。前后是转折关系，“不只”只表示递进，不能表示转折。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86098, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次活动不只孩子参加，老人参加。", "corrected_sentence": "这次活动不只孩子参加，老人也参加。", "error_description": "呼应词漏掉：“不只……”后面的分句要有“也”与之呼应，应为“老人也参加”，少了“也”就不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86098, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生不只很学习，还要锻炼身体。", "corrected_sentence": "学生不只要学习，还要锻炼身体。", "error_description": "错误：“不只很学习”；正确：“不只要学习”。“很”不能修饰“学习”这样的动作动词，这里应该用“要”，与后面的“还要”呼应。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
