INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86099, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "“称”是用一个名字来叫人或东西。", "primary_collocate": null, "pronunciation": "chēng", "ipa": "ʈʂʰɤŋ⁵⁵", "syllable_count": 1, "sentences": [{"text": "大家都称他为“老王”。", "target_word": "称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们称这种花为玫瑰。", "target_word": "称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们称王老师为“王姐”。", "target_word": "称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们称北京为中国的首都。", "target_word": "称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很高，朋友们称他“大个子”。", "target_word": "称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国人称中国菜为“中餐”。", "target_word": "称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们称这个小城为花城。", "target_word": "称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶称我的小狗为“小黑”。", "target_word": "称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我家，我们称爸爸的妈妈为奶奶。", "target_word": "称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们都称我为“阿李”。", "target_word": "称", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "称：用名字称呼人或东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4282b7-916c-4da7-bd32-a72c5ffbca2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86099, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "称", "is_correct": true, "explanation": "“称”（chēng，第一声）是用名字叫人或东西的意思。"}, {"text": "城", "is_correct": false, "explanation": "chéng（第二声）与 chēng（第一声）声调不同，意思是城市。"}, {"text": "秤", "is_correct": false, "explanation": "chèng（第四声）与 chēng（第一声）声调不同，意思是秤。"}, {"text": "争", "is_correct": false, "explanation": "zhēng 与 chēng 声母不同（zh/ch），意思是争夺。"}, {"text": "声", "is_correct": false, "explanation": "shēng 与 chēng 声母不同（sh/ch），意思是声音。"}], "explanations": {"称": "“称”（chēng，第一声）是用名字叫人或东西的意思。", "城": "chéng（第二声）与 chēng（第一声）声调不同，意思是城市。", "秤": "chèng（第四声）与 chēng（第一声）声调不同，意思是秤。", "争": "zhēng 与 chēng 声母不同（zh/ch），意思是争夺。", "声": "shēng 与 chēng 声母不同（sh/ch），意思是声音。"}, "sentence_index": null, "correct_answer": "称"}, "level_3": {"options": [{"text": "称", "is_correct": true, "explanation": "“称”是用名字叫人的意思，与“为“老王””搭配，说明称呼。"}, {"text": "看", "is_correct": false, "explanation": "语义：“看”指视觉动作，不能表示给人取称呼。"}, {"text": "送", "is_correct": false, "explanation": "搭配：“送”后不能接“…为…”的称呼结构。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，与给人取称呼没有关系。"}], "explanations": {"称": "“称”是用名字叫人的意思，与“为“老王””搭配，说明称呼。", "看": "语义：“看”指视觉动作，不能表示给人取称呼。", "送": "搭配：“送”后不能接“…为…”的称呼结构。", "吃": "语义：“吃”指进食，与给人取称呼没有关系。"}, "sentence_index": 0, "correct_answer": "称"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我称他来吃饭。", "explanation": "这里应该用〈叫〉。“称”只表示用名字称呼，不能表示叫人来。"}, {"text": "他在门口称我。", "explanation": "这里应该用〈喊〉。“称”指用名字叫人，不指大声呼唤。"}, {"text": "我称了他一个问题。", "explanation": "这里应该用〈问〉。“称”表示用名字称呼人或东西，不能表示提出问题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86099, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "称", "is_correct": true, "explanation": "“称”（chēng，第一声）是用名字叫人或东西的意思。"}, {"text": "成", "is_correct": false, "explanation": "chéng（第二声）与 chēng（第一声）声调不同，意思是完成。"}, {"text": "蒸", "is_correct": false, "explanation": "zhēng 与 chēng 声母不同（zh/ch），意思是蒸煮。"}, {"text": "冲", "is_correct": false, "explanation": "chōng 与 chēng 韵母不同（-ong/-eng），意思是冲击。"}, {"text": "生", "is_correct": false, "explanation": "shēng 与 chēng 声母不同（sh/ch），意思是出生。"}], "explanations": {"称": "“称”（chēng，第一声）是用名字叫人或东西的意思。", "成": "chéng（第二声）与 chēng（第一声）声调不同，意思是完成。", "蒸": "zhēng 与 chēng 声母不同（zh/ch），意思是蒸煮。", "冲": "chōng 与 chēng 韵母不同（-ong/-eng），意思是冲击。", "生": "shēng 与 chēng 声母不同（sh/ch），意思是出生。"}, "sentence_index": null, "correct_answer": "称"}, "level_3": {"options": [{"text": "称", "is_correct": true, "explanation": "“称”是用名字叫人的意思，与“为“花城””搭配，说明称呼。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”指拆除或分开，不能表示给地方取名。"}, {"text": "闻", "is_correct": false, "explanation": "语义：“闻”指用鼻子感觉气味，与给地方取名无关。"}, {"text": "抓", "is_correct": false, "explanation": "搭配：“抓”不能与“…为…”的称呼结构搭配。"}], "explanations": {"称": "“称”是用名字叫人的意思，与“为“花城””搭配，说明称呼。", "拆": "语义：“拆”指拆除或分开，不能表示给地方取名。", "闻": "语义：“闻”指用鼻子感觉气味，与给地方取名无关。", "抓": "搭配：“抓”不能与“…为…”的称呼结构搭配。"}, "sentence_index": 6, "correct_answer": "称"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师向大家称了新同学。", "explanation": "这里应该用〈介绍〉。“称”只表示用名字叫人，不表示引见他人。"}, {"text": "他狠狠称了我一拳。", "explanation": "这里应该用〈打〉。“称”表示称量或称呼，不能表示用拳头击打。"}, {"text": "他称了一句“再见”。", "explanation": "这里应该用〈说〉。“称”表示称呼或称量，不表示开口说话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86099, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们都称为她“小太阳”。", "corrected_sentence": "我们都称她为“小太阳”。", "error_description": "“称”后面应先接对象再接“为”，应说“称她为”，不能说“称为她”。“为”的位置错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86099, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶称我的猫为了“小白”。", "corrected_sentence": "奶奶称我的猫为“小白”。", "error_description": "“为”后误加“了”，“为了”表示目的，不能引出称呼。应说“称我的猫为“小白””。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
