INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86105, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "审判是法官听一听，再决定谁对谁错。", "primary_collocate": null, "pronunciation": "shěn pàn", "ipa": "ʂən˨˩˦ pʰan˥˩", "syllable_count": 2, "sentences": [{"text": "法官明天审判这个案子。", "target_word": "审判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们今天审判了一个小偷。", "target_word": "审判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案子要公开审判。", "target_word": "审判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官认真听完双方的话，才审判这个案子。", "target_word": "审判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官正在审判他的案子。", "target_word": "审判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官审判得很公平，大家都服气。", "target_word": "审判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很害怕法官审判自己。", "target_word": "审判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位法官审判过很多大案。", "target_word": "审判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位法官审判时，不让人乱说话。", "target_word": "审判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他请了律师，等着法官审判。", "target_word": "审判", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "审判了", "label": "体标"}, {"form": "审判过", "label": "体标"}, {"form": "审判长", "label": "复合"}, {"form": "审判员", "label": "复合"}], "register": "书面", "sense_fingerprint": "法官听完双方的话，决定谁对谁错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd86389b0-f4c1-4e9d-ad63-6659a36e1d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86105, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "审判", "is_correct": true, "explanation": "审判：法官依法审理案子并作出判决，与“法官”和“这个案子”搭配，填入句中正确。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能用于处理案子。"}, {"text": "表演", "is_correct": false, "explanation": "搭配：“表演”的对象是节目或角色，不能说表演案子。"}, {"text": "挖", "is_correct": false, "explanation": "语义：“挖”指掘土，与案子无关。"}], "explanations": {"审判": "审判：法官依法审理案子并作出判决，与“法官”和“这个案子”搭配，填入句中正确。", "吃": "语义：“吃”指进食，不能用于处理案子。", "表演": "搭配：“表演”的对象是节目或角色，不能说表演案子。", "挖": "语义：“挖”指掘土，与案子无关。"}, "sentence_index": 0, "correct_answer": "审判"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察审判了那个小偷，他终于承认了。", "explanation": "这里应该用〈审问〉。审问是警察或他人询问嫌疑人，审判只指法院依法作出判决。"}, {"text": "这场比赛的胜负由裁判审判，没有争议。", "explanation": "这里应该用〈判定〉。判定是裁定胜负或是非，审判只用于法院依法裁决案件，不用于体育比赛。"}, {"text": "学校审判了这份材料，没有问题。", "explanation": "这里应该用〈审查〉。审查是检查材料，审判只用于法院裁决案件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86105, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "审判", "is_correct": true, "explanation": "审判：法官对案件作出裁决，与“法官”和“害怕”的语境相符，填入句中正确。"}, {"text": "打扮", "is_correct": false, "explanation": "语义：“打扮”指装扮外表，与法官和“害怕”的语境不合。"}, {"text": "歌颂", "is_correct": false, "explanation": "语义：“歌颂”是赞美，与“他很害怕”的语境相矛盾。"}, {"text": "怀念", "is_correct": false, "explanation": "语义：“怀念”指想念过去的人或事，法官不会怀念自己，与语境不合。"}], "explanations": {"审判": "审判：法官对案件作出裁决，与“法官”和“害怕”的语境相符，填入句中正确。", "打扮": "语义：“打扮”指装扮外表，与法官和“害怕”的语境不合。", "歌颂": "语义：“歌颂”是赞美，与“他很害怕”的语境相矛盾。", "怀念": "语义：“怀念”指想念过去的人或事，法官不会怀念自己，与语境不合。"}, "sentence_index": 6, "correct_answer": "审判"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校审判了偷东西的学生，让他写检讨。", "explanation": "这里应该用〈处罚〉。处罚是对违纪者施以惩罚，审判只用于法院依法裁决。"}, {"text": "警察审判了这起事故，很快找到了原因。", "explanation": "这里应该用〈调查〉。调查是弄清事实，审判指法院依法作出判决，不用于事故调查。"}, {"text": "比赛的审判很公正，大家都服气。", "explanation": "这里应该用〈评判〉。评判是评定优劣，审判只用于法律案件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86105, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "法官审判地很认真，大家都没有意见。", "corrected_sentence": "法官审判得很认真，大家都没有意见。", "error_description": "补语标记错误：“审判”后的补语要用“得”，应说“审判得很认真”。“地”用于修饰动词的状语，不能放在动词后作补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86105, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "法官正在审判了这个案子。", "corrected_sentence": "法官正在审判这个案子。", "error_description": "体标错误：“正在”表示动作进行中，不能与表示完成的“了”连用。应说“正在审判这个案子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
