INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86106, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "法院依法审理并作出判决。", "primary_collocate": null, "pronunciation": "shěn pàn", "ipa": "ʂən˨˩˦ pʰan˥˩", "syllable_count": 2, "sentences": [{"text": "法院依法审判这起案件。", "target_word": "审判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院下周审判那两个公司老板。", "target_word": "审判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家法院审判过很多案子。", "target_word": "审判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院会按照法律审判他。", "target_word": "审判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这起案件由法院公开审判。", "target_word": "审判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院审判完以后，作出了决定。", "target_word": "审判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他犯了法，法院要审判他。", "target_word": "审判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院正在审判一起偷钱案。", "target_word": "审判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院审判时，记者也可以来听。", "target_word": "审判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他要到法院接受审判。", "target_word": "审判", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "审判了", "label": "体标"}, {"form": "审判过", "label": "体标"}, {"form": "审判长", "label": "复合"}, {"form": "审判员", "label": "复合"}], "register": "书面", "sense_fingerprint": "法院依照法律审理案件并作出判决", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd86389b0-f4c1-4e9d-ad63-6659a36e1d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86106, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "审判", "is_correct": true, "explanation": "审判：法院依照法律审理案件并作出判决，与“法院”和“这起案件”搭配，填入句中正确。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能用于处理案件。"}, {"text": "表演", "is_correct": false, "explanation": "搭配：“表演”只能搭配节目或角色，不能说表演案件。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”指修理物品，案件不能被修。"}], "explanations": {"审判": "审判：法院依照法律审理案件并作出判决，与“法院”和“这起案件”搭配，填入句中正确。", "吃": "语义：“吃”指进食，不能用于处理案件。", "表演": "搭配：“表演”只能搭配节目或角色，不能说表演案件。", "修": "语义：“修”指修理物品，案件不能被修。"}, "sentence_index": 0, "correct_answer": "审判"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察审判了那个抢劫犯，他终于承认了。", "explanation": "这里应该用〈审问〉。审问是询问嫌疑人，审判只指法院依法作出判决。"}, {"text": "公司审判了这份报告，没有问题。", "explanation": "这里应该用〈审查〉。审查是检查文件，审判只用于法院裁决案件。"}, {"text": "班主任审判了迟到的学生。", "explanation": "这里应该用〈处罚〉。处罚是学校或老师对违纪学生的惩罚，审判只用于法院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86106, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "审判", "is_correct": true, "explanation": "审判：法院对犯法的人依法作出判决，与“犯了法”的语境相符，填入句中正确。"}, {"text": "宠爱", "is_correct": false, "explanation": "语义：“宠爱”指溺爱疼爱，与“犯了法”的语境冲突。"}, {"text": "歌颂", "is_correct": false, "explanation": "语义：“歌颂”是赞美，犯了法的人不会被歌颂，与语境矛盾。"}, {"text": "打扮", "is_correct": false, "explanation": "语义：“打扮”指装扮外表，与“犯了法”的语境无关。"}], "explanations": {"审判": "审判：法院对犯法的人依法作出判决，与“犯了法”的语境相符，填入句中正确。", "宠爱": "语义：“宠爱”指溺爱疼爱，与“犯了法”的语境冲突。", "歌颂": "语义：“歌颂”是赞美，犯了法的人不会被歌颂，与语境矛盾。", "打扮": "语义：“打扮”指装扮外表，与“犯了法”的语境无关。"}, "sentence_index": 6, "correct_answer": "审判"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警方审判了这场火灾，找到了原因。", "explanation": "这里应该用〈调查〉。调查是弄清事实，审判指法院依法作出判决，不用于火灾调查。"}, {"text": "演讲比赛的审判很公正，大家都很服气。", "explanation": "这里应该用〈评判〉。评判是评定优劣，审判只用于法律案件。"}, {"text": "他上课迟到，老师审判了他。", "explanation": "这里应该用〈批评〉。批评是指出错误，审判只用于法院依法裁决。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86106, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "法院审判地很公正，当事人都没有意见。", "corrected_sentence": "法院审判得很公正，当事人都没有意见。", "error_description": "补语标记错误：“审判”后的补语要用“得”，应说“审判得很公正”。“地”用于动词前作状语，不能放在动词后作补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86106, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "法院正在审判了这起案件。", "corrected_sentence": "法院正在审判这起案件。", "error_description": "体标错误：“正在”表示动作进行中，不能与表示完成的“了”连用。应说“正在审判这起案件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
