INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86110, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "对年轻女子的尊称。", "primary_collocate": null, "pronunciation": "xiǎo jiě", "ipa": "ɕjɑʊ˨˩ tɕjɛ˨˩", "syllable_count": 2, "sentences": [{"text": "王小姐是我们公司的新经理。", "target_word": "小姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小姐，请问洗手间在哪儿？", "target_word": "小姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李小姐昨天给我打过电话。", "target_word": "小姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，哪位是张小姐？", "target_word": "小姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位小姐想找一本中文书。", "target_word": "小姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小姐，您要喝茶还是喝咖啡？", "target_word": "小姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "陈小姐住在我家楼上。", "target_word": "小姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位小姐把包忘在椅子上了。", "target_word": "小姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说，请林小姐明天九点来。", "target_word": "小姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢你，小姐，你帮了我很大的忙。", "target_word": "小姐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小姐们", "label": "复数"}], "register": "礼貌", "sense_fingerprint": "对年轻女子的尊称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adca781d-1525-4feb-b95c-ac2c37686162') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86110, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小姐", "is_correct": true, "explanation": "小姐（xiǎo jiě）：对年轻女子的尊称，即本条词义。"}, {"text": "小结", "is_correct": false, "explanation": "小结（xiǎo jié）：jié（第二声）与 jiě（第三声）声调不同，意思是简要总结。"}, {"text": "小街", "is_correct": false, "explanation": "小街（xiǎo jiē）：jiē（第一声）与 jiě（第三声）声调不同，意思是小的街道。"}, {"text": "小写", "is_correct": false, "explanation": "小写（xiǎo xiě）：xiě 与 jiě 声母不同（x 与 j），意思是小写字母。"}, {"text": "消解", "is_correct": false, "explanation": "消解（xiāo jiě）：xiāo（第一声）与 xiǎo（第三声）声调不同，意思是消除。"}], "explanations": {"小姐": "小姐（xiǎo jiě）：对年轻女子的尊称，即本条词义。", "小结": "小结（xiǎo jié）：jié（第二声）与 jiě（第三声）声调不同，意思是简要总结。", "小街": "小街（xiǎo jiē）：jiē（第一声）与 jiě（第三声）声调不同，意思是小的街道。", "小写": "小写（xiǎo xiě）：xiě 与 jiě 声母不同（x 与 j），意思是小写字母。", "消解": "消解（xiāo jiě）：xiāo（第一声）与 xiǎo（第三声）声调不同，意思是消除。"}, "sentence_index": null, "correct_answer": "小姐"}, "level_3": {"options": [{"text": "同学", "is_correct": false, "explanation": "语义：“同学”指学生，与“新经理”矛盾。"}, {"text": "小姐", "is_correct": true, "explanation": "正确：“王小姐”是对年轻女子的尊称，与“新经理”的句意相符。"}, {"text": "小朋友", "is_correct": false, "explanation": "语义：小朋友不能当公司的新经理，与后半句冲突。"}, {"text": "学生", "is_correct": false, "explanation": "搭配：“王学生”不是称呼人的说法，且与“新经理”矛盾。"}], "explanations": {"同学": "语义：“同学”指学生，与“新经理”矛盾。", "小姐": "正确：“王小姐”是对年轻女子的尊称，与“新经理”的句意相符。", "小朋友": "语义：小朋友不能当公司的新经理，与后半句冲突。", "学生": "搭配：“王学生”不是称呼人的说法，且与“新经理”矛盾。"}, "sentence_index": 0, "correct_answer": "小姐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位小姐快七十岁了，走路还很稳。", "explanation": "这里应该用〈老太太〉。小姐指年轻女子，不能用来称呼年纪很大的女性。"}, {"text": "那位小姐是我的老师，我很尊敬他。", "explanation": "这里应该用〈先生〉。小姐只用于称呼年轻女子，指男老师时要说先生。"}, {"text": "这位小姐是我的妈妈，她在银行工作。", "explanation": "这里应该用〈妈妈〉。小姐是对年轻女子的尊称，不能用来称呼自己的母亲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad5a228-33b1-4a81-90f6-5bd375ffe5fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86110, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小区", "is_correct": false, "explanation": "语义：“小区”是地方，不是人，不能住在楼上，与句子矛盾。"}, {"text": "小姐", "is_correct": true, "explanation": "正确：“陈小姐住在我家楼上”指一位年轻女子，只有“小姐”符合。"}, {"text": "小孩", "is_correct": false, "explanation": "搭配：“陈小孩”不是称呼人的说法，与“陈小姐”的称呼格式不符。"}, {"text": "幼儿", "is_correct": false, "explanation": "搭配：“陈幼儿”不是称呼人的说法，与“陈小姐”的称呼格式不符。"}], "explanations": {"小区": "语义：“小区”是地方，不是人，不能住在楼上，与句子矛盾。", "小姐": "正确：“陈小姐住在我家楼上”指一位年轻女子，只有“小姐”符合。", "小孩": "搭配：“陈小孩”不是称呼人的说法，与“陈小姐”的称呼格式不符。", "幼儿": "搭配：“陈幼儿”不是称呼人的说法，与“陈小姐”的称呼格式不符。"}, "sentence_index": 6, "correct_answer": "小姐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位小姐才五岁，很爱画画。", "explanation": "这里应该用〈小朋友〉。小姐指年轻女子，不用于五岁的孩子。"}, {"text": "那位小姐的孙女今年上小学了。", "explanation": "这里应该用〈老奶奶〉。句中说她有孙女上小学，年纪已大；小姐只用于年轻女子。"}, {"text": "那位小姐的胡子又白又长，正在公园下棋。", "explanation": "这里应该用〈老爷爷〉。句中说有白胡子，指男性老人，小姐只用于年轻女子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad5a228-33b1-4a81-90f6-5bd375ffe5fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86110, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只小姐是我的同事。", "corrected_sentence": "这位小姐是我的同事。", "error_description": "错在量词：称呼人要用“位”，“只”用于动物，“这只小姐”不成立，应为“这位小姐”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad5a228-33b1-4a81-90f6-5bd375ffe5fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86110, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那本小姐在门口等你。", "corrected_sentence": "那位小姐在门口等你。", "error_description": "错在量词：称呼人要用“位”，“本”用于书，“那本小姐”不成立，应为“那位小姐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad5a228-33b1-4a81-90f6-5bd375ffe5fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
