INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86111, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "少年是十来岁、正在长大的男孩或女孩。", "primary_collocate": null, "pronunciation": "shào nián", "ipa": "ʂau̯˥˩ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "那个少年每天骑车上学。", "target_word": "少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个少年在河边钓鱼。", "target_word": "少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个少年很爱看书。", "target_word": "少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少年站在门口，不说话。", "target_word": "少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一个很聪明的少年。", "target_word": "少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少年们在草地上踢足球。", "target_word": "少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个少年把球扔给了我。", "target_word": "少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位少年帮老人提着包。", "target_word": "少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少年看见了妈妈，马上跑过去。", "target_word": "少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个少年今年十二岁，个子很高。", "target_word": "少年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "少年们", "label": "复数"}], "register": "中性", "sense_fingerprint": "少年：十来岁正在长大的孩子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528460c6-b68d-4819-9976-ec879930a8cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86111, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "少年", "is_correct": true, "explanation": "正确：十来岁、正在长大的孩子，与“每天骑车上学”相符。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿还不会骑车，也不上学。"}, {"text": "老人", "is_correct": false, "explanation": "语义：老人已经不上学，与“上学”矛盾。"}, {"text": "工人", "is_correct": false, "explanation": "搭配：“上学”的主体是学生，工人应说“上班”。"}], "explanations": {"少年": "正确：十来岁、正在长大的孩子，与“每天骑车上学”相符。", "婴儿": "语义：婴儿还不会骑车，也不上学。", "老人": "语义：老人已经不上学，与“上学”矛盾。", "工人": "搭配：“上学”的主体是学生，工人应说“上班”。"}, "sentence_index": 0, "correct_answer": "少年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "幼儿园的少年在唱歌。", "explanation": "这里应该用〈儿童〉。少年指十来岁、正在长大的孩子，幼儿园的孩子年纪还小，要说儿童。"}, {"text": "他已经四十岁了，是一个少年。", "explanation": "这里应该用〈中年人〉。少年指十来岁的人，四十岁的人要说中年人。"}, {"text": "我爷爷是一个八十岁的少年。", "explanation": "这里应该用〈老人〉。少年指十来岁、正在长大的孩子，八十岁的人要说老人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86111, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "少年", "is_correct": true, "explanation": "正确：“少年”是人，能把球扔给别人，与句意相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会扔球，也不能把球扔给我。"}, {"text": "小猫", "is_correct": false, "explanation": "配价：“扔给”的施事要能扔东西，小猫不能把球扔给别人。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是地方，不是能扔球的人或物。"}], "explanations": {"少年": "正确：“少年”是人，能把球扔给别人，与句意相符。", "石头": "语义：石头不会扔球，也不能把球扔给我。", "小猫": "配价：“扔给”的施事要能扔东西，小猫不能把球扔给别人。", "厨房": "语义：厨房是地方，不是能扔球的人或物。"}, "sentence_index": 6, "correct_answer": "少年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位少年今年三十岁，是这家医院的医生。", "explanation": "这里应该用〈青年〉。少年指十来岁的人，三十岁的人要说青年。"}, {"text": "那位少年已经六十岁了，每天去公园散步。", "explanation": "这里应该用〈老人〉。少年指十来岁的人，六十岁的人要说老人。"}, {"text": "那个少年已经当了三个孩子的爸爸。", "explanation": "这里应该用〈成年人〉。少年指十来岁的人，当爸爸的人要说成年人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86111, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只少年很喜欢画画。", "corrected_sentence": "那个少年很喜欢画画。", "error_description": "量词错误：“少年”指人，应说“那个少年”，不能说“那只少年”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86111, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三个少年们在草地上踢足球。", "corrected_sentence": "三个少年在草地上踢足球。", "error_description": "复数错误：“三个”已经表示数量，后面不能再加“们”，应说“三个少年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
