INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86112, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86112, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指十岁到十几岁的青少年。", "primary_collocate": null, "pronunciation": "shào nián", "ipa": "ʂau̯˥˩ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他是一个十三岁的少年。", "target_word": "少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是写给少年看的。", "target_word": "少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他十几岁的时候，还是个瘦瘦的少年。", "target_word": "少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少年正在长身体，要多吃饭。", "target_word": "少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校为少年们办了一场比赛。", "target_word": "少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些少年都在读初中。", "target_word": "少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十三四岁的少年都爱玩手机。", "target_word": "少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少年的个子长得很快。", "target_word": "少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十一岁的少年已经会做饭了。", "target_word": "少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有很多玩游戏的少年。", "target_word": "少年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "少年们", "label": "复数"}], "register": "中性", "sense_fingerprint": "少年：十岁到十几岁的青少年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528460c6-b68d-4819-9976-ec879930a8cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86112, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "少年", "is_correct": true, "explanation": "正确：十岁到十几岁的青少年，与“十三岁”相符。"}, {"text": "大人", "is_correct": false, "explanation": "语义：“大人”指成年人，十三岁还不是成年人。"}, {"text": "老头", "is_correct": false, "explanation": "体貌：“老头”指年老的男性，与“十三岁”不符。"}, {"text": "中年人", "is_correct": false, "explanation": "语义：中年一般指四五十岁左右，与“十三岁”矛盾。"}], "explanations": {"少年": "正确：十岁到十几岁的青少年，与“十三岁”相符。", "大人": "语义：“大人”指成年人，十三岁还不是成年人。", "老头": "体貌：“老头”指年老的男性，与“十三岁”不符。", "中年人": "语义：中年一般指四五十岁左右，与“十三岁”矛盾。"}, "sentence_index": 0, "correct_answer": "少年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他二十五岁了，已经是一个少年。", "explanation": "这里应该用〈成年人〉。少年指十岁到十几岁的人，二十五岁的人要说成年人。"}, {"text": "公园里跳舞的少年都已经七十岁了。", "explanation": "这里应该用〈老年人〉。少年指十岁到十几岁的人，七十岁的人要说老年人。"}, {"text": "那个少年刚出生三天。", "explanation": "这里应该用〈婴儿〉。少年指十岁到十几岁的人，刚出生的孩子要说婴儿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86112, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "少年", "is_correct": true, "explanation": "正确：“十三四岁”指青少年时期，玩手机的正是这个年龄段的少年。"}, {"text": "老年人", "is_correct": false, "explanation": "语义：“十三四岁”指青少年时期，与老年人矛盾。"}, {"text": "幼儿园", "is_correct": false, "explanation": "语义：幼儿园是地方，不指人，与“十三四岁”不合。"}, {"text": "猫", "is_correct": false, "explanation": "配价：“玩手机”的主体要是人，猫不能玩手机。"}], "explanations": {"少年": "正确：“十三四岁”指青少年时期，玩手机的正是这个年龄段的少年。", "老年人": "语义：“十三四岁”指青少年时期，与老年人矛盾。", "幼儿园": "语义：幼儿园是地方，不指人，与“十三四岁”不合。", "猫": "配价：“玩手机”的主体要是人，猫不能玩手机。"}, "sentence_index": 6, "correct_answer": "少年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位少年今年五十岁，在公司工作。", "explanation": "这里应该用〈中年人〉。少年指十岁到十几岁的人，五十岁的人要说中年人。"}, {"text": "那位少年已经三十岁了，每天在工厂上班。", "explanation": "这里应该用〈青年〉。少年指十岁到十几岁的人，三十岁的人要说青年。"}, {"text": "那位少年已经教了三十年书。", "explanation": "这里应该用〈老师〉。少年指十岁到十几岁的人，教了三十年书的人要说老师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86112, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是一条十五岁的少年。", "corrected_sentence": "她是一个十五岁的少年。", "error_description": "量词错误：“少年”指人，应说“一个少年”，“条”用于细长的东西，不能用于人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86112, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公园里有几只玩游戏的少年。", "corrected_sentence": "公园里有几个玩游戏的少年。", "error_description": "量词错误：“少年”指人，应说“几个少年”，“只”多用于动物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
