INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86116, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示程度很高，常用来加强语气。", "primary_collocate": null, "pronunciation": "zhēn", "ipa": "ʈʂən˥", "syllable_count": 1, "sentences": [{"text": "这个菜真好吃！", "target_word": "真", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天天气真冷。", "target_word": "真", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你的汉语说得真好。", "target_word": "真", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个孩子真可爱。", "target_word": "真", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我真想马上回家。", "target_word": "真", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的画真漂亮，我很喜欢。", "target_word": "真", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的夏天真热，我不想出门。", "target_word": "真", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你真聪明，一下子就懂了。", "target_word": "真", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到这个好消息，我真高兴。", "target_word": "真", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书真有意思，我看了两遍。", "target_word": "真", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "真的", "label": "复合"}], "register": "口语", "sense_fingerprint": "加强语气，表示程度很高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d8f0e7b-36d4-4a15-8847-6d6ee72c61b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86116, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "真", "is_correct": true, "explanation": "正确答案。真 zhēn（第一声），副词，表示确实、很。"}, {"text": "深", "is_correct": false, "explanation": "shēn（第一声）与 zhēn（第一声）声母不同（sh 与 zh），意思是深。"}, {"text": "镇", "is_correct": false, "explanation": "zhèn（第四声）与 zhēn（第一声）声调不同，意思是城镇。"}, {"text": "枕", "is_correct": false, "explanation": "zhěn（第三声）与 zhēn（第一声）声调不同，意思是枕头。"}, {"text": "争", "is_correct": false, "explanation": "zhēng（第一声）与 zhēn（第一声）韵母不同（eng 与 en），意思是争夺。"}], "explanations": {"真": "正确答案。真 zhēn（第一声），副词，表示确实、很。", "深": "shēn（第一声）与 zhēn（第一声）声母不同（sh 与 zh），意思是深。", "镇": "zhèn（第四声）与 zhēn（第一声）声调不同，意思是城镇。", "枕": "zhěn（第三声）与 zhēn（第一声）声调不同，意思是枕头。", "争": "zhēng（第一声）与 zhēn（第一声）韵母不同（eng 与 en），意思是争夺。"}, "sentence_index": null, "correct_answer": "真"}, "level_3": {"options": [{"text": "真", "is_correct": true, "explanation": "正确。“真”表示程度很高、确实如此，用来加强感叹语气。"}, {"text": "大概", "is_correct": false, "explanation": "语义：“大概”表示推测，与句末“！”所表达的确信语气矛盾。"}, {"text": "也许", "is_correct": false, "explanation": "语义：“也许”表示不确定，与句末“！”所表达的确信语气矛盾。"}, {"text": "固然", "is_correct": false, "explanation": "搭配：“固然”要和后面的“但是”呼应，这里没有转折分句，不成立。"}], "explanations": {"真": "正确。“真”表示程度很高、确实如此，用来加强感叹语气。", "大概": "语义：“大概”表示推测，与句末“！”所表达的确信语气矛盾。", "也许": "语义：“也许”表示不确定，与句末“！”所表达的确信语气矛盾。", "固然": "搭配：“固然”要和后面的“但是”呼应，这里没有转折分句，不成立。"}, "sentence_index": 0, "correct_answer": "真"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服比那件真便宜。", "explanation": "这里应该用〈更〉。「真」表示确实、加强语气，不能用在比较句中修饰形容词，比较时要用〈更〉。"}, {"text": "我没有你真聪明。", "explanation": "这里应该用〈那么〉。「真」不能用于“没有……那么……”的比较句，此处要用〈那么〉。"}, {"text": "今天比昨天真冷。", "explanation": "这里应该用〈更〉。「真」不能放在“比”字句的形容词前表示比较，比较程度时要用〈更〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc1a1d69-248a-48c6-9872-687195f3abb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86116, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "真", "is_correct": true, "explanation": "正确答案。真 zhēn（第一声），副词，表示确实、很。"}, {"text": "身", "is_correct": false, "explanation": "shēn（第一声）与 zhēn（第一声）声母不同（sh 与 zh），意思是身体。"}, {"text": "阵", "is_correct": false, "explanation": "zhèn（第四声）与 zhēn（第一声）声调不同，意思是一阵、阵子。"}, {"text": "诊", "is_correct": false, "explanation": "zhěn（第三声）与 zhēn（第一声）声调不同，意思是诊断。"}, {"text": "蒸", "is_correct": false, "explanation": "zhēng（第一声）与 zhēn（第一声）韵母不同（eng 与 en），意思是蒸煮。"}], "explanations": {"真": "正确答案。真 zhēn（第一声），副词，表示确实、很。", "身": "shēn（第一声）与 zhēn（第一声）声母不同（sh 与 zh），意思是身体。", "阵": "zhèn（第四声）与 zhēn（第一声）声调不同，意思是一阵、阵子。", "诊": "zhěn（第三声）与 zhēn（第一声）声调不同，意思是诊断。", "蒸": "zhēng（第一声）与 zhēn（第一声）韵母不同（eng 与 en），意思是蒸煮。"}, "sentence_index": null, "correct_answer": "真"}, "level_3": {"options": [{"text": "真", "is_correct": true, "explanation": "正确。“真”加强“热”的程度，与后句“我不想出门”的理由相接。"}, {"text": "甚", "is_correct": false, "explanation": "语域：“甚”是书面语，与句中口语化的“我不想出门”不协调。"}, {"text": "诚然", "is_correct": false, "explanation": "搭配：“诚然”要和后面的“但是”呼应，这里没有转折分句。"}, {"text": "不", "is_correct": false, "explanation": "语义：“不热”与后句“我不想出门”的因果关系不通，前后矛盾。"}], "explanations": {"真": "正确。“真”加强“热”的程度，与后句“我不想出门”的理由相接。", "甚": "语域：“甚”是书面语，与句中口语化的“我不想出门”不协调。", "诚然": "搭配：“诚然”要和后面的“但是”呼应，这里没有转折分句。", "不": "语义：“不热”与后句“我不想出门”的因果关系不通，前后矛盾。"}, "sentence_index": 6, "correct_answer": "真"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜真一些咸。", "explanation": "这里应该用〈有些〉。「真」表示确实，不能表示轻微的程度，与数量词「一些」搭配也不通。"}, {"text": "他真学生，每天都去上课。", "explanation": "这里应该用〈是〉。「真」修饰名词性谓语时要带〈是〉，说“真学生”不合语法。"}, {"text": "这座山很真高，我们爬不上去。", "explanation": "「真」是副词，不能受程度副词「很」修饰，应说“这座山真高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc1a1d69-248a-48c6-9872-687195f3abb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86116, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部电影好真看。", "corrected_sentence": "这部电影真好看。", "error_description": "“真”是副词，要放在形容词“好看”前面，应说“真好看”，不能放在“好”的后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc1a1d69-248a-48c6-9872-687195f3abb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86116, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书很真不错。", "corrected_sentence": "这本书真不错。", "error_description": "“真”是副词，不能受程度副词“很”修饰，“很真不错”不成句；应去掉“很”，说“真不错”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc1a1d69-248a-48c6-9872-687195f3abb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
