INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86117, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "层是一样东西叠在另一样上面，用来数有几层的词。", "primary_collocate": null, "pronunciation": "céng", "ipa": "tsʰɤŋ˧˥", "syllable_count": 1, "sentences": [{"text": "这个蛋糕有三层。", "target_word": "层", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我家住在六层的楼里。", "target_word": "层", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个书架有五层。", "target_word": "层", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在床上盖了两层被子。", "target_word": "层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天很冷，我穿了三层衣服。", "target_word": "层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面包上涂了一层奶油。", "target_word": "层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子上铺着一层白布。", "target_word": "层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个盒子里放着两层巧克力。", "target_word": "层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这两层纸分开。", "target_word": "层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把饼干一层一层放进盒子里。", "target_word": "层", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "層", "label": "繁体"}, {"form": "层层", "label": "重叠"}], "register": "中性", "sense_fingerprint": "层：数叠放的层数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0344090-a91f-48fd-a918-ec4ab7350984') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86117, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "层", "is_correct": true, "explanation": "正确：听到的是“层”（céng），指一样东西叠在另一样上面的层数。"}, {"text": "城", "is_correct": false, "explanation": "chéng 与 céng 声母不同（ch/c），意思是城市，不是叠放的层。"}, {"text": "丛", "is_correct": false, "explanation": "cóng 与 céng 韵母不同（ong/eng），意思是丛、一簇，与层不同。"}, {"text": "蹭", "is_correct": false, "explanation": "cèng 与 céng 声调不同（第四声），意思是蹭、擦，不是层。"}], "explanations": {"层": "正确：听到的是“层”（céng），指一样东西叠在另一样上面的层数。", "城": "chéng 与 céng 声母不同（ch/c），意思是城市，不是叠放的层。", "丛": "cóng 与 céng 韵母不同（ong/eng），意思是丛、一簇，与层不同。", "蹭": "cèng 与 céng 声调不同（第四声），意思是蹭、擦，不是层。"}, "sentence_index": null, "correct_answer": "层"}, "level_3": {"options": [{"text": "层", "is_correct": true, "explanation": "正确：“层”用于一样东西叠在另一样上面的层，蛋糕分三层。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”用于平面的东西，蛋糕不能说“张”。"}, {"text": "条", "is_correct": false, "explanation": "搭配：“条”用于细长的东西，蛋糕不能说“条”。"}, {"text": "座", "is_correct": false, "explanation": "语义：“座”指山、楼等大型固定物，蛋糕不是这样的东西。"}], "explanations": {"层": "正确：“层”用于一样东西叠在另一样上面的层，蛋糕分三层。", "张": "搭配：“张”用于平面的东西，蛋糕不能说“张”。", "条": "搭配：“条”用于细长的东西，蛋糕不能说“条”。", "座": "语义：“座”指山、楼等大型固定物，蛋糕不是这样的东西。"}, "sentence_index": 0, "correct_answer": "层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他送给我一层礼物。", "explanation": "这里应该用〈份〉。份用于礼物、工作等，“层”只用于一样东西叠在另一样上面的层数。"}, {"text": "我昨晚做了一层梦。", "explanation": "这里应该用〈场〉。梦用“场”或“个”计量，“层”只用于叠放的东西，不能用来数梦。"}, {"text": "他买了一层桌子。", "explanation": "这里应该用〈张〉。桌子是单个的家具，用“张”计量，“层”指叠放的层数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86117, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "层", "is_correct": true, "explanation": "正确：听到的是“层”（céng），指一样东西叠在另一样上面的层数。"}, {"text": "成", "is_correct": false, "explanation": "chéng 与 céng 声母不同（ch/c），意思是完成、成为。"}, {"text": "从", "is_correct": false, "explanation": "cóng 与 céng 韵母不同（ong/eng），意思是从、跟随。"}, {"text": "藏", "is_correct": false, "explanation": "cáng 与 céng 韵母不同（ang/eng），意思是隐藏。"}], "explanations": {"层": "正确：听到的是“层”（céng），指一样东西叠在另一样上面的层数。", "成": "chéng 与 céng 声母不同（ch/c），意思是完成、成为。", "从": "cóng 与 céng 韵母不同（ong/eng），意思是从、跟随。", "藏": "cáng 与 céng 韵母不同（ang/eng），意思是隐藏。"}, "sentence_index": null, "correct_answer": "层"}, "level_3": {"options": [{"text": "层", "is_correct": true, "explanation": "正确：“层”指铺在桌上的一层白布，表示覆盖的一层。"}, {"text": "颗", "is_correct": false, "explanation": "搭配：“颗”用于小而圆的东西，布不能说“颗”。"}, {"text": "根", "is_correct": false, "explanation": "搭配：“根”用于细长的东西，布不能说“根”。"}, {"text": "把", "is_correct": false, "explanation": "搭配：“把”用于有柄的器具，布不能说“把”。"}], "explanations": {"层": "正确：“层”指铺在桌上的一层白布，表示覆盖的一层。", "颗": "搭配：“颗”用于小而圆的东西，布不能说“颗”。", "根": "搭配：“根”用于细长的东西，布不能说“根”。", "把": "搭配：“把”用于有柄的器具，布不能说“把”。"}, "sentence_index": 6, "correct_answer": "层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在山谷里发现了一层河。", "explanation": "这里应该用〈条〉。河是细长的，用“条”计量；“层”只用于覆盖或叠放在表面的东西，河不能铺成一层。"}, {"text": "他们在操场上跑了一层步。", "explanation": "这里应该用〈圈〉。跑步用“圈”或“次”计量；“层”只用于覆盖或叠放的东西，不能用来数跑步。"}, {"text": "他给我讲了一层笑话。", "explanation": "这里应该用〈个〉。笑话用“个”或“则”计量；“层”只用于覆盖或叠放的东西，不能用来数笑话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86117, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个柜子有四个层。", "corrected_sentence": "这个柜子有四层。", "error_description": "“层”作量词时，数词后直接接“层”，不能再加“个”。错误是“四个层”，正确应说“四层”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86117, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "书柜的每一层层都放满了书。", "corrected_sentence": "书柜的每一层都放满了书。", "error_description": "“层层”是重叠形式，表示一层接一层，不能在“每一层”后面再加“层”。错误是“每一层层”，正确应说“每一层”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
