INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86118, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词，用于重叠、积累的东西。", "primary_collocate": null, "pronunciation": "céng", "ipa": "tsʰɤŋ˧˥", "syllable_count": 1, "sentences": [{"text": "山上有一层薄薄的雾。", "target_word": "层", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这块蛋糕上抹了一层奶油。", "target_word": "层", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "早上，草地上有一层白霜。", "target_word": "层", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "桌子上落了一层灰。", "target_word": "层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的额头上出了一层汗。", "target_word": "层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事让她心里多了一层担心。", "target_word": "层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地上结了一层薄冰。", "target_word": "层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在墙上刷了一层油漆。", "target_word": "层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和他之间隔着一层误会。", "target_word": "层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪过后，地上盖着厚厚的一层雪。", "target_word": "层", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "層", "label": "繁体"}, {"form": "层层", "label": "重叠"}], "register": "中性", "sense_fingerprint": "层：数覆盖、积累的一层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0344090-a91f-48fd-a918-ec4ab7350984') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86118, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "层", "is_correct": true, "explanation": "正确：听到的是“层”（céng），指覆盖在表面上的一层。"}, {"text": "城", "is_correct": false, "explanation": "chéng 与 céng 声母不同（ch/c），意思是城市，不是覆盖的一层。"}, {"text": "丛", "is_correct": false, "explanation": "cóng 与 céng 韵母不同（ong/eng），意思是丛、一簇。"}, {"text": "蹭", "is_correct": false, "explanation": "cèng 与 céng 声调不同（第四声），意思是蹭、擦。"}], "explanations": {"层": "正确：听到的是“层”（céng），指覆盖在表面上的一层。", "城": "chéng 与 céng 声母不同（ch/c），意思是城市，不是覆盖的一层。", "丛": "cóng 与 céng 韵母不同（ong/eng），意思是丛、一簇。", "蹭": "cèng 与 céng 声调不同（第四声），意思是蹭、擦。"}, "sentence_index": null, "correct_answer": "层"}, "level_3": {"options": [{"text": "层", "is_correct": true, "explanation": "正确：“层”用于覆盖在表面的一层，山上笼罩着一层雾。"}, {"text": "座", "is_correct": false, "explanation": "搭配：“座”用于山、楼等大型固定物，雾不能说“座”。"}, {"text": "根", "is_correct": false, "explanation": "语义：“根”用于细长的东西，雾不是细长的。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”多用于动物或成对物件中的一个，雾不能用“只”计量。"}], "explanations": {"层": "正确：“层”用于覆盖在表面的一层，山上笼罩着一层雾。", "座": "搭配：“座”用于山、楼等大型固定物，雾不能说“座”。", "根": "语义：“根”用于细长的东西，雾不是细长的。", "只": "搭配：“只”多用于动物或成对物件中的一个，雾不能用“只”计量。"}, "sentence_index": 0, "correct_answer": "层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "树林里刮起一层风。", "explanation": "这里应该用〈阵〉。阵用于一段时间突然出现的风、雨等，“层”用于覆盖在表面的东西。"}, {"text": "他给我讲了一层故事。", "explanation": "这里应该用〈个〉。故事用“个”或“则”计量；“层”只用于覆盖或叠放的东西，不能用来数故事。"}, {"text": "他寄了一层信。", "explanation": "这里应该用〈封〉。信件用“封”计量，“层”只用于覆盖或叠放的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
